local config = {
  ui_story_5075_50750100_1_dialog_content = "(Após sobreviver à longa e perigosa jornada do Shadowind pelo mar, finalmente chegamos às margens de Longzhou.)",
  ui_story_5075_50750100_2_dialog_content = "(Yuebai e Zhong Xu tinham uma entrega para fazer em nome de sua guilda, então eles tiveram que ficar mais alguns dias.)",
  ui_story_5075_50750100_3_dialog_content = "(A Guilda Lin gentilmente nos convidou para viajar com eles...)",
  ui_story_5075_50750100_4_dialog_content = "(Mas como o enviado oficial de Astra, escolhi seguir Dantang e Jiu para a capital do Reino Ji primeiro.)",
  ui_story_5075_50750100_5_dialog_content = "Ó Donzela do Dragão, a ti eu rezo.",
  ui_story_5075_50750100_6_dialog_content = "Por favor, não deixe a chuva cair. Amanhã ao amanhecer, tofu seco será minha oferta a enviar—",
  ui_story_5075_50750100_7_dialog_content = "<color=#e8d9bb>Respingo.</color>",
  ui_story_5075_50750100_8_dialog_content = "Ugh!",
  ui_story_5075_50750100_9_dialog_content = "Cuidado, PlayerName!",
  ui_story_5075_50750100_10_dialog_content = "Sei que você está intrigado com a paisagem do Reino Ji, mas este barco fluvial não é o Shadowind.",
  ui_story_5075_50750100_11_dialog_content = "Por favor, tente não ficar tão hipnotizado a ponto de cair na água.",
  ui_story_5075_50750100_12_dialog_content = "Não foi fácil para mim conseguir um emissário tão querido como você vindo diretamente do Astra.",
  ui_story_5075_50750100_13_dialog_content = "Você cruzou o oceano e sobreviveu aos ataques dos Eclipsitas e piratas sem nenhum arranhão.",
  ui_story_5075_50750100_14_dialog_content = "Não posso suportar a culpa e o remorso se você se afogar a poucos passos do palácio.",
  ui_story_5075_50750100_15_dialog_content = "Haha... Desculpe por preocupar você assim.",
  ui_story_5075_50750100_16_dialog_content = "Fiquei tão envolvido ouvindo a canção daquele barqueiro que esqueci que estava em um barco eu mesmo.",
  ui_story_5075_50750100_17_dialog_content = "Tenho ouvido músicas assim desde que estive no porto.",
  ui_story_5075_50750100_18_dialog_content = "As notas são tão leves e rápidas, e parece que a letra está em um idioma local. Sobre o que eles estão cantando?",
  ui_story_5075_50750100_19_dialog_content = "Essa é uma canção de remo.",
  ui_story_5075_50750100_20_dialog_content = "Ji é repleto de lagos e rios que proporcionam sustento para as pessoas. Naturalmente, isso torna os barqueiros e pescadores prevalentes.",
  ui_story_5075_50750100_21_dialog_content = "Com o tempo, eles desenvolveram canções para pescar e navegar.",
  ui_story_5075_50750100_22_dialog_content = "Exuberantes sejam as montanhas, clara seja a água. Flores estejam florescendo, salgueiros sejam elegantes. É sobre isso que eles cantam.",
  ui_story_5075_50750100_23_dialog_content = "E a melodia que você acabou de ouvir foi uma que buscava bênçãos das divindades.",
  ui_story_5075_50750100_24_dialog_content = "\"Dragon Maiden, por favor, garanta um dia ensolarado e uma navegação tranquila.\"",
  ui_story_5075_50750100_25_dialog_content = "\"Vou oferecer a você um delicioso tofu seco depois que eu chegar em casa com segurança.\"",
  ui_story_5075_50750100_26_dialog_content = "Essa é a essência disso.",
  ui_story_5075_50750100_27_dialog_content = "Ah, a Donzela Dragão!",
  ui_story_5075_50750100_28_dialog_content = "Não é <color=#FFB400>Dragon Maiden Over Turbulent Seas</color> o nome daquela dança que você ensinou a Vice em Twin Pavilions Bay?",
  ui_story_5075_50750100_29_dialog_content = "Lembro-me de você dizer que o povo costeiro de Longzhou realmente reverencia a Donzela do Dragão.",
  ui_story_5075_50750100_30_dialog_content = "... Mas as divindades realmente gostam tanto de tofu seco?",
  ui_story_5075_50750100_31_dialog_content = "Bem, não exatamente. A oferta na canção popular na verdade varia.",
  ui_story_5075_50750100_32_dialog_content = "A Donzela do Dragão não pede oferendas, mas as pessoas ainda as adicionam à música para mostrar seu apreço.",
  ui_story_5075_50750100_33_dialog_content = "Aquele homem cantou sobre tofu seco provavelmente porque era o que ele tinha em casa.",
  ui_story_5075_50750100_34_dialog_content = "E ela está bem com isso? Que deidade curiosa.",
  ui_story_5075_50750100_35_dialog_content = "Achei que tinha aprendido muito sobre Longzhou quando estava em Twin Pavilions Bay...",
  ui_story_5075_50750100_36_dialog_content = "Mas agora que estou aqui, parece que estou aprendendo algo novo a cada passo que dou.",
  ui_story_5075_50750100_37_dialog_content = "Eu só queria que Vice e Carleen estivessem aqui para ver isso também.",
  ui_story_5075_50750100_38_dialog_content = "Isso pode acontecer mais cedo do que você pensa.",
  ui_story_5075_50750100_39_dialog_content = "Isso mesmo! Afinal, nossa missão é fortalecer as relações entre nossas duas terras.",
  ui_story_5075_50750100_40_dialog_content = "Se tudo correr bem, talvez meus amigos de Astra possam visitar Longzhou e ver tudo por si mesmos!",
  ui_story_5075_50750100_41_dialog_content = "Além de trocar a estratégia e tecnologia para combater os Eclipsitas.",
  ui_story_5075_50750100_42_dialog_content = "A comunicação e a cooperação só podem facilitar a paz para ambas as pessoas.",
  ui_story_5075_50750100_43_dialog_content = "Acho que devemos contar com você como o emissário para tornar essa visão realidade.",
  ui_story_5075_50750100_44_dialog_content = "<color=#e8d9bb>Baque.</color>",
  ui_story_5075_50750100_45_dialog_content = "Chegamos à costa e o destino está à frente, Vossa Alteza e PlayerName.",
  ui_story_5075_50750100_46_dialog_content = "Temos que desembarcar aqui para entrar na cidade.",
  ui_story_5075_50750100_47_dialog_content = "Por favor, aguarde um segundo, PlayerName.",
  ui_story_5075_50750100_48_dialog_content = "<color=#e8d9bb>Dantang desce do navio, sorri e faz uma leve reverência.</color>",
  ui_story_5075_50750100_49_dialog_content = "Eu sou a Princesa Zhuohua, encarregada pelo Rei de Ji para ser a embaixadora em Astra.",
  ui_story_5075_50750100_50_dialog_content = "Vossa Excelência aceitou meu convite e viajou longe até Longzhou.",
  ui_story_5075_50750100_51_dialog_content = "Por isso, permita-me expressar novamente minha gratidão e apreciação.",
  ui_story_5075_50750100_52_dialog_content = "Bem-vindo à <color=#FFB400>capital do Reino Ji</color>—",
  ui_story_5075_50750100_53_dialog_content = "<color=#FFB400>Haojin</color>.",
  ui_story_5075_50750100_54_dialog_content = "Não mencione isso, e obrigado por me receber!",
  ui_story_5075_50750100_55_dialog_content = "Agora é hora de eu cumprir minha parte do acordo como enviado de Astra.",
  ui_story_5075_50750100_56_dialog_content = "Alteza, os atendentes reais chegaram. Devemos retornar ao palácio e ao rei.",
  ui_story_5075_50750100_57_dialog_content = "Bem, PlayerName...",
  ui_story_5075_50750100_58_dialog_content = "Saudações, Sua Alteza, estimado emissário.",
  ui_story_5075_50750100_59_dialog_content = "Sou o mordomo responsável pela Casa de Hóspedes Real, e é uma grande honra tê-lo como nosso convidado, estimado emissário.",
  ui_story_5075_50750100_60_dialog_content = "A pousada cuidará de todas as atividades diárias e arranjos de segurança para você enquanto estiver no Reino de Ji.",
  ui_story_5075_50750100_61_dialog_content = "Parece que devemos nos separar por enquanto.",
  ui_story_5075_50750100_62_dialog_content = "Assim que eu terminar os negócios oficiais e Yuebai retornar em dois dias, nos reuniremos novamente. Eu te levarei para um tour por Haojin.",
  ui_story_5075_50750100_63_dialog_content = "O Festival da Primavera estará conosco em breve. É a época mais comemorada em Longzhou.",
  ui_story_5075_50750100_64_dialog_content = "As ruas serão pontilhadas com lanternas coloridas, dragões dançantes, bem como feiras com inúmeros vendedores de lanches.",
  ui_story_5075_50750100_65_dialog_content = "Certamente deixará uma impressão duradoura em você.",
  ui_story_5075_50750100_66_dialog_content = "Ansioso por isso!",
  ui_story_5075_50750100_67_dialog_content = "(Mal sabíamos que um plano tão simples acabaria cheio de complicações...)",
  ui_story_5075_50750100_68_dialog_content = "<color=#e8d9bb>Pousada Real</color>",
  ui_story_5075_50750100_69_dialog_content = "Excelência, por favor, tome um pouco de chá.",
  ui_story_5075_50750100_70_dialog_content = "É chá de bambu ametista, preparado com água fresca da nascente, recém-trazida da montanha, oferecendo um sabor puro e doce incomparável.",
  ui_story_5075_50750100_71_dialog_content = "É delicioso! Obrigado.",
  ui_story_5075_50750100_72_dialog_content = "Emissário estimado, não tenho certeza sobre suas preferências, então preparei uma variedade de lanches.",
  ui_story_5075_50750100_73_dialog_content = "Aqui temos creme dourado crocante, bolo de sete camadas e bola de orvalho de jade... Se preferir algo diferente, é só nos avisar.",
  ui_story_5075_50750100_74_dialog_content = "Isso é uma grande variedade de lanches!",
  ui_story_5075_50750100_75_dialog_content = "Emissário estimado, deixe-me ajudá-lo a se trocar e tomar banho.",
  ui_story_5075_50750100_76_dialog_content = "N-N-Não, obrigado! Eu posso fazer isso sozinho!",
  ui_story_5075_50750100_77_dialog_content = "V-Vocês certamente sabem como cuidar dos convidados...",
  ui_story_5075_50750100_78_dialog_content = "Isso me deixa bastante nervoso. Eu não quero arruinar a imagem da Astra fazendo algo errado, sabe?",
  ui_story_5075_50750100_79_dialog_content = "Devemos ir ao palácio amanhã para discutir assuntos oficiais, então acho que não ficarei aqui por muito tempo.",
  ui_story_5075_50750100_80_dialog_content = "<color=#e8d9bb>Dia Dois</color>",
  ui_story_5075_50750100_81_dialog_content = "Alguém está chegando! Eles estão aqui para me chamar para o palácio?",
  ui_story_5075_50750100_82_dialog_content = "Estimado emissário, nosso rei está emocionado em saber que você veio de tão longe, do exterior.",
  ui_story_5075_50750100_83_dialog_content = "Então ele me enviou para lhe entregar seus presentes de boas-vindas, incluindo chá e frutas raras, roupas luxuosas e seda, bem como várias fragrâncias.",
  ui_story_5075_50750100_84_dialog_content = "São todos esses realmente para mim? Mas...",
  ui_story_5075_50750100_85_dialog_content = "Agora que os presentes foram entregues, vou me despedir.",
  ui_story_5075_50750100_86_dialog_content = "May que você goze de boa saúde durante sua estadia em Ji para aliviar a ansiedade da Princesa Zhuohua, Vossa Excelência.",
  ui_story_5075_50750100_87_dialog_content = "<color=#e8d9bb>Terceiro dia</color>",
  ui_story_5075_50750100_88_dialog_content = "... Por que ainda não fui chamado para o palácio?",
  ui_story_5075_50750100_89_dialog_content = "Está se sentindo entediado, Vossa Excelência? Que tal um pouco de ópera?",
  ui_story_5075_50750100_90_dialog_content = "Se você estiver interessado, posso conseguir alguns artistas de primeira linha para fazer um show para você.",
  ui_story_5075_50750100_91_dialog_content = "Não foi o que eu quis dizer...",
  ui_story_5075_50750100_92_dialog_content = "Não é a sua praia? Que tal um pouco de Pingtan ou shows de rua?",
  ui_story_5075_50750100_93_dialog_content = "Se nada disso te interessar, você pode experimentar lutas de grilos, lutas de codornas e muitos outros divertimentos na cidade de Haojin.",
  ui_story_5075_50750100_94_dialog_content = "Não, eu realmente não preciso de nada assim no momento...",
  ui_story_5075_50750100_95_dialog_content = "Eu só quero ir encontrar o governante do Reino Ji!",
  ui_story_5075_50750100_96_dialog_content = "<color=#e8d9bb>Dia Quatro</color>",
  ui_story_5075_50750100_97_dialog_content = "Ah, finalmente livre.",
  ui_story_5075_50750100_98_dialog_content = "Que lugar é esse? Com todas essas placas, duvido que o rei viva por aqui...",
  ui_story_5075_50750100_99_dialog_content = "Estimado emissário, em resposta à sua pergunta, parece que você tem pulado refeições nos últimos dias, talvez por tédio.",
  ui_story_5075_50750100_100_dialog_content = "Então, conversei com o mordomo para montar um cronograma divertido para você.",
  ui_story_5075_50750100_101_dialog_content = "Para os que visitam Haojin pela primeira vez, o Templo da Donzela Dragão nas Montanhas do Sul é uma visita obrigatória.",
  ui_story_5075_50750100_102_dialog_content = "Além das magníficas paisagens com picos imponentes e rochas intrincadas, rumores dizem que existem milagres manifestados pela Donzela do Dragão.",
  ui_story_5075_50750100_103_dialog_content = "Sinta-se à vontade para apreciar a paisagem ou fazer suas orações. Todos os outros já foram retirados, então ninguém irá perturbá-lo.",
  ui_story_5075_50750100_104_dialog_content = "Huh? Você fez as pessoas saírem só por minha causa? Não é à toa que este lugar está tão abandonado...",
  ui_story_5075_50750100_105_dialog_content = "Você realmente não precisa se dar a todo esse trabalho. Eu não sou uma pessoa famosa ou algo assim, e definitivamente não me importo de fazer parte do público.",
  ui_story_5075_50750100_106_dialog_content = "Você brinca, estimado emissário. Você é um convidado de honra do Reino Ji, e estamos dedicados a servi-lo com nossos maiores esforços.",
  ui_story_5075_50750100_107_dialog_content = "Sinta-se à vontade para seguir em frente e se divertir.",
  ui_story_5075_50750100_108_dialog_content = "(Tudo bem... Já que estou aqui, acho que vou dar uma olhada ao redor.)",
  ui_story_5075_50750100_109_dialog_content = "(Há uma estátua seriamente imponente no centro do salão principal. Seria essa a Donzela do Dragão?)",
  ui_story_5075_50750100_110_dialog_content = "(Há todos os tipos de ofertas como Dantang disse, tudo desde frutas e legumes até chá e lanches...)",
  ui_story_5075_50750100_111_dialog_content = "Hã? Tem mais alguém aqui também?",
  ui_story_5075_50750100_112_dialog_content = "<color=#e8d9bb>Ding—</color>",
  ui_story_5075_50750100_113_dialog_content = "Eu me pergunto qual criada deixou isso cair... Ou será que pertence àquele estranho que acabei de ver?",
  ui_story_5075_50750100_114_dialog_content = "Emissário estimado...",
  ui_story_5075_50750100_115_dialog_content = "Eu inspecionei aqui várias vezes. Não há mais ninguém no templo além de você.",
  ui_story_5075_50750100_116_dialog_content = "Mas tenho certeza de que vi alguém aqui agora mesmo. Parece que eles também deixaram cair algo...",
  ui_story_5075_50750100_117_dialog_content = "Eu não vi nenhum... Hã?",
  ui_story_5075_50750100_118_dialog_content = "Para onde foram todas as oferendas?",
  ui_story_5075_50750100_119_dialog_content = "C-como isso pode...",
  ui_story_5075_50750100_120_dialog_content = "Por favor, aceite nossas desculpas, Vossa Excelência. Foi nossa negligência permitir que um ladrão entrasse.",
  ui_story_5075_50750100_121_dialog_content = "Espíritos malignos não ousariam se aproximar do Templo da Donzela do Dragão. Devem ser aqueles demônios astutos novamente...",
  ui_story_5075_50750100_122_dialog_content = "Qual é o problema com os demônios?",
  ui_story_5075_50750100_123_dialog_content = "Não é grande coisa, não vale a pena se preocupar, estimado emissário.",
  ui_story_5075_50750100_124_dialog_content = "Foi nossa negligência. Por favor, desça a colina com os guardas primeiro. Vou relatar isso ao mordomo.",
  ui_story_5075_50750100_125_dialog_content = "Guardas! Escoltem o emissário de volta à casa de hóspedes!",
  ui_story_5075_50750100_126_dialog_content = "Afirmativo!",
  ui_story_5075_50750100_127_dialog_content = "E-Espere, todos... Ao menos deixem-me tomar mais algumas lufadas de ar fresco—",
  ui_story_5075_50750100_128_dialog_content = "(Os próximos dias não foram diferentes de antes.)",
  ui_story_5075_50750100_129_dialog_content = "(Comi, dormi e me diverti... Eles cuidaram de mim de todas as maneiras possíveis, e os guardas me escoltaram onde quer que eu fosse.)",
  ui_story_5075_50750100_130_dialog_content = "(Mas ninguém me dava uma resposta direta sempre que eu perguntava sobre ir ao palácio.)",
  ui_story_5075_50750100_131_dialog_content = "Nada vai ser resolvido neste ritmo. Eu deveria apenas ir falar com o mordomo eu mesmo.",
  ui_story_5075_50750100_132_dialog_content = "Preciso garantir uma audiência com o rei, ou então Dantang e eu nunca completaremos nossa missão.",
  ui_story_5075_50750100_133_dialog_content = "Eu só espero que não haja guardas para atrapalhar meu caminho...",
  ui_story_5075_50750100_134_dialog_content = "... Princesa Zhuohua.",
  ui_story_5075_50750100_135_dialog_content = "(Hã? Alguém acabou de mencionar Dantang?)",
  ui_story_5075_50750100_136_dialog_content = "A notícia é verdadeira?",
  ui_story_5075_50750100_137_dialog_content = "Haha, você sabe, não há fumaça sem fogo.",
  ui_story_5075_50750100_138_dialog_content = "Ouvi dizer que nosso príncipe herdeiro está perdidamente apaixonado por aquela princesa. Ele só tem olhos para ela.",
  ui_story_5075_50750100_139_dialog_content = "A princesa ainda não concordou. Mas as empregadas do palácio dizem que o rei pretende arranjar um casamento para eles.",
  ui_story_5075_50750100_140_dialog_content = "Isso faz sentido! Não é à toa que o palácio tem estado agitado, ocupado demais para se preocupar com qualquer outra coisa.",
  ui_story_5075_50750100_141_dialog_content = "Nossa, o patinho realmente se transformou em um cisne! Se eu me lembro corretamente, ela não estava aqui para quitar uma dívida?",
  ui_story_5075_50750100_142_dialog_content = "?",
  ui_story_5075_50750100_143_dialog_content = "Com licença, mas de quem você está falando—",
  ui_story_5075_50750100_144_dialog_content = "Acontece que você está aqui, estimado emissário. Eu estava procurando por você em todos os lugares.",
  ui_story_5075_50750100_145_dialog_content = "O rei emitiu um decreto, convidando especialmente você para participar do grande banquete de hoje e compartilhar suas percepções sobre assuntos estrangeiros.",
  ui_story_5075_50750100_146_dialog_content = "Por favor, vá se preparar agora, então eu te levarei ao palácio.",
  ui_story_5075_50750100_147_dialog_content = "Você quer dizer agora mesmo? Por que ninguém me contou antes?",
  ui_story_5075_50750201_1_dialog_content = "<color=#e8d9bb>Jade torres, portões de ouro, majestosos e grandiosos. Melodias em harmonia, ecoando na terra imperial.</color>",
  ui_story_5075_50750201_2_dialog_content = "Emissário de Astra, por favor, entre no tribunal real!",
  ui_story_5075_50750201_3_dialog_content = "Acontece que as pessoas das terras ocidentais realmente parecem diferentes de nós.",
  ui_story_5075_50750201_4_dialog_content = "As roupas são bastante novas, embora a modelagem justa reduza a elegância.",
  ui_story_5075_50750201_5_dialog_content = "Dizem por aí que ele é um Celestita, algo bastante raro até mesmo nas terras ocidentais.",
  ui_story_5075_50750201_6_dialog_content = "(Parece que eles estão falando de mim.)",
  ui_story_5075_50750201_7_dialog_content = "(Dantang também está aqui, e ninguém parece estar implicando com ela, mas ela parece bastante tensa.)",
  ui_story_5075_50750201_8_dialog_content = "Você é PlayerName, certo? Dizem por aí que você fez muito para recuperar as rotas marítimas entre os dois continentes.",
  ui_story_5075_50750201_9_dialog_content = "Ao te encontrar agora, posso dizer que você é realmente um jovem talentoso.",
  ui_story_5075_50750201_10_dialog_content = "Você me elogia demais. O Shadowind só conseguiu retornar em segurança graças aos esforços conjuntos de todos...",
  ui_story_5075_50750201_11_dialog_content = "Não precisa ser humilde. Alguém, sirva nosso convidado com um chá.",
  ui_story_5075_50750201_12_dialog_content = "É bastante raro encontrar um viajante do outro lado do mar. Que tal compartilhar algumas histórias de terras estrangeiras conosco?",
  ui_story_5075_50750201_13_dialog_content = "Dizem que existem gigantes de aço habilidosos em guerra no seu continente.",
  ui_story_5075_50750201_14_dialog_content = "Esses gigantes, controlados por soldados dentro deles apenas com pensamentos, têm olhos brilhantes como relâmpagos e a força para mover montanhas. Isso é verdade?",
  ui_story_5075_50750201_X14_option_content = "Isso é demais...",
  ui_story_5075_50750201_15_dialog_content = "Isso é... um pouco de exagero.",
  ui_story_5075_50750201_16_dialog_content = "A tecnologia do Astra ainda não está nesse nível.",
  ui_story_5075_50750201_17_dialog_content = "Embora seja verdade que temos Colossi, eles não são as incríveis armas que você está descrevendo.",
  ui_story_5075_50750201_18_dialog_content = "Sem mencionar que não restam muitos deles, e apenas algumas pessoas no mundo podem controlá-los.",
  ui_story_5075_50750201_X18_option_content = "Talvez no futuro, porém.",
  ui_story_5075_50750201_X19_dialog_content = "Embora tal força poderosa não exista agora...",
  ui_story_5075_50750201_X20_dialog_content = "Com a Federação Illumina, experiente em tecnologia militar, e Lumopolis, proficiente em magia ritual, por perto...",
  ui_story_5075_50750201_X21_dialog_content = "Talvez Astra crie os gigantes que você descreveu um dia.",
  ui_story_5075_50750201_X22_dialog_content = "Ah, então você está dizendo que isso não existe.",
  ui_story_5075_50750201_19_dialog_content = "Então, como seus soldados confrontam os espíritos malignos na batalha?",
  ui_story_5075_50750201_20_dialog_content = "Nossos militares pesquisam e produzem todos os tipos de armas e armaduras para combatê-los.",
  ui_story_5075_50750201_21_dialog_content = "Combinado com Luminatics, eles nos permitem afastar os Eclipsitas... ou \"espíritos malignos\", como você os chama.",
  ui_story_5075_50750201_22_dialog_content = "Então, você ainda está contando com a força física no combate, huh?",
  ui_story_5075_50750201_23_dialog_content = "Bem, então, no seu vasto continente, existem técnicas de imortalidade ou maneiras de ascender?",
  ui_story_5075_50750201_24_dialog_content = "Eu, uh... Acho que não.",
  ui_story_5075_50750201_25_dialog_content = "Temos algumas pessoas de longa vida em nossa terra. Na verdade, a rainha de Northland é famosa por sua aparência eternamente jovem.",
  ui_story_5075_50750201_26_dialog_content = "Mas quanto a verdadeiros imortais... Receio que eu não tenha ouvido falar de nenhum.",
  ui_story_5075_50750201_27_dialog_content = "Hmm, parece que apesar do mar no meio, o outro continente não é muito diferente do nosso Longzhou.",
  ui_story_5075_50750201_28_dialog_content = "Não é totalmente verdade—",
  ui_story_5075_50750201_29_dialog_content = "Aham.",
  ui_story_5075_50750201_30_dialog_content = "(Não seja impulsivo.)",
  ui_story_5075_50750201_31_dialog_content = "...",
  ui_story_5075_50750201_32_dialog_content = "Mais interessante ainda, ouvi dizer que, PlayerName, você tem algumas habilidades peculiares.",
  ui_story_5075_50750201_33_dialog_content = "E eles podem amplificar a força das Artes da Força várias vezes.",
  ui_story_5075_50750201_34_dialog_content = "Que tal eu te nomear para um cargo nominal para que você possa permanecer no Reino Ji?",
  ui_story_5075_50750201_35_dialog_content = "Você viu a beleza da cidade de Haojin de perto nesses dias.",
  ui_story_5075_50750201_36_dialog_content = "O nosso Reino de Ji, abençoado com terra e mar abundantes, florescendo em todos os aspectos, é como um paraíso na terra.",
  ui_story_5075_50750201_37_dialog_content = "Não é muito melhor do que aquela terra invadida por espíritos malignos?",
  ui_story_5075_50750201_38_dialog_content = "Hmm, agradeço o gesto gentil, mas Astra é minha casa. Mais cedo ou mais tarde, terei que voltar.",
  ui_story_5075_50750201_39_dialog_content = "Não apenas isso, mas eu não estou aqui para meu próprio prazer. Eu vim como um emissário para promover melhores relações entre nossas terras.",
  ui_story_5075_50750201_40_dialog_content = "De volta em Astra, desenvolvemos todos os tipos de contramedidas eficazes contra Eclipsites. Seja Illumina ou Lumopolis—",
  ui_story_5075_50750201_41_dialog_content = "Bem, você tem um ponto. Mas deixe a Marinha Mercante lidar com esses assuntos menores.",
  ui_story_5075_50750201_42_dialog_content = "Discutir essas questões agora seria um desperdício de um momento tão bonito.",
  ui_story_5075_50750201_43_dialog_content = "O Festival da Primavera está se aproximando, e Ji está repleto de prosperidade e maravilhas. Devemos comemorar juntos.",
  ui_story_5075_50750201_44_dialog_content = "Todos, levantem seus copos!",
  ui_story_5075_50750201_45_dialog_content = "Mas…",
  ui_story_5075_50750201_46_dialog_content = "Viva a longevidade do rei e seu reinado eterno!",
  ui_story_5075_50750201_47_dialog_content = "Viva à abundância e prosperidade do Reino de Ji!",
  ui_story_5075_50750201_48_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5075_50750201_49_dialog_content = "É um terremoto!",
  ui_story_5075_50750201_50_dialog_content = "Pressa, proteja o rei!",
  ui_story_5075_50750201_51_dialog_content = "<color=#e8d9bb>Mesas e cadeiras tremem, pratos batem e caem, e os tremores demoram um pouco para cessar completamente.</color>",
  ui_story_5075_50750201_52_dialog_content = "<color=#e8d9bb>O grande salão, animado há um momento, agora está uma bagunça, preenchido com os sons de pessoas correndo e gritando ordens.</color>",
  ui_story_5075_50750201_53_dialog_content = "<color=#e8d9bb>Os oficiais, que estavam cheios de espírito há apenas alguns momentos, agora parecem bastante desgrenhados.</color>",
  ui_story_5075_50750201_54_dialog_content = "Ufa, foi por pouco, mas acabei de receber a boa notícia de que as pessoas estão seguras.",
  ui_story_5075_50750201_55_dialog_content = "Não foi como planejei, mas é aqui que o banquete termina hoje.",
  ui_story_5075_50750201_56_dialog_content = "Dantang?",
  ui_story_5075_50750201_57_dialog_content = "Venha, PlayerName. Vamos para um lugar mais tranquilo.",
  ui_story_5075_50750201_58_dialog_content = "Acho que minha bandana agarrou em alguma coisa...",
  ui_story_5075_50750201_59_dialog_content = "Desculpe, Dantang, mas você poderia me dar uma mão?",
  ui_story_5075_50750201_60_dialog_content = "As flores nesta árvore são tão bonitas. Eu não quero machucar algo tão precioso acidentalmente.",
  ui_story_5075_50750201_61_dialog_content = "Hee, essas flores de ameixeira não são exatamente preciosas, mas bastante comuns. Você pode ser o primeiro a tratá-las com tanta delicadeza.",
  ui_story_5075_50750201_62_dialog_content = "Por favor, fique parado e deixe-me libertar você.",
  ui_story_5075_50750201_63_dialog_content = "...",
  ui_story_5075_50750201_64_dialog_content = "Certo, está feito.",
  ui_story_5075_50750201_65_dialog_content = "Está encontrando a sua estadia na Pousada Real agradável nestes últimos dias?",
  ui_story_5075_50750201_66_dialog_content = "Sim, mas parece que todos estão exagerando um pouco na hospitalidade.",
  ui_story_5075_50750201_67_dialog_content = "Eles nem mesmo me deixam servir um copo de água para mim mesmo. Isso me faz sentir como se eu fosse realmente valioso ou algo assim.",
  ui_story_5075_50750201_68_dialog_content = "Não é esse o caso?",
  ui_story_5075_50750201_69_dialog_content = "Por favor, não brinque sobre isso.",
  ui_story_5075_50750201_70_dialog_content = "Eu fiz o meu melhor para não fazer papel de bobo. Isso não foi fácil para mim, sabe.",
  ui_story_5075_50750201_71_dialog_content = "Eu também não fiz um bom trabalho como emissário.",
  ui_story_5075_50750201_72_dialog_content = "Entrar no palácio parece impossível. Eu nem tive a chance de apresentar Astra, muito menos negociar melhores laços.",
  ui_story_5075_50750201_73_dialog_content = "... Me desculpe, PlayerName.",
  ui_story_5075_50750201_74_dialog_content = "Isso é negligência da minha parte.",
  ui_story_5075_50750201_75_dialog_content = "Eu te convidei para vir até aqui e falhei em fornecer um fórum para você.",
  ui_story_5075_50750201_76_dialog_content = "Isso não é sua culpa, Dantang. Se eu tivesse me preparado melhor, não estaria me debatendo assim.",
  ui_story_5075_50750201_77_dialog_content = "Não, a culpa é minha...",
  ui_story_5075_50750201_78_dialog_content = "*risadas*",
  ui_story_5075_50750201_79_dialog_content = "Hahaha... Toda essa troca de desculpas entre amigos é meio engraçada, não é?",
  ui_story_5075_50750201_80_dialog_content = "Bem, não adianta se preocupar com o passado. Eu vou voltar e me preparar para minha próxima viagem ao palácio, e prometo que farei melhor da próxima vez.",
  ui_story_5075_50750201_81_dialog_content = "... Ah, e mais uma coisa.",
  ui_story_5075_50750201_82_dialog_content = "Sim?",
  ui_story_5075_50750201_83_dialog_content = "Antes de eu chegar, ouvi duas das empregadas conversando... Elas disseram algo sobre planos de casamento entre você e o príncipe do Reino Ji?",
  ui_story_5075_50750201_84_dialog_content = "E eles não falaram de você em um tom agradável, dizendo que você está aqui como garantia.",
  ui_story_5075_50750201_85_dialog_content = "É por isso que eu tenho que perguntar: eles estão te tratando bem aqui?",
  ui_story_5075_50750201_86_dialog_content = "Bom...",
  ui_story_5075_50750201_87_dialog_content = "Eu-Eu estou bem.",
  ui_story_5075_50750201_88_dialog_content = "Na verdade, eu já ouvi os mesmos rumores antes, mas não esperava que você também os ouvisse.",
  ui_story_5075_50750201_89_dialog_content = "Essa é a intenção do rei, mas deixei minha posição clara, e ele não pode me forçar.",
  ui_story_5075_50750201_X89_dialog_content = "Sobre isso... É verdade que estou aqui por causa de um empréstimo para Ye.",
  ui_story_5075_50750201_X90_dialog_content = "No entanto, não é assunto para os servos julgarem. Eu lidarei com os fofoqueiros mais tarde.",
  ui_story_5075_50750201_X91_dialog_content = "Dantang...",
  ui_story_5075_50750201_90_dialog_content = "Não se preocupe. Estou aqui há tempo suficiente para obter apoio suficiente.",
  ui_story_5075_50750201_91_dialog_content = "Ninguém em todo o palácio ousou me desafiar abertamente até agora.",
  ui_story_5075_50750201_92_dialog_content = "Isso inclui o príncipe, certo?",
  ui_story_5075_50750201_93_dialog_content = "Claro! Sem mencionar que o príncipe herdeiro é apenas um...",
  ui_story_5075_50750201_94_dialog_content = "Dantang! Você está bem, Dantang?",
  ui_story_5075_50750201_95_dialog_content = "... Príncipe Herdeiro? Você deveria estar descansando em seu quarto a essa hora da noite.",
  ui_story_5075_50750201_96_dialog_content = "Estou preocupado com você.",
  ui_story_5075_50750201_97_dialog_content = "Esse terremoto foi bastante forte agora mesmo. Você está bem? Alguma lesão? Assustado?",
  ui_story_5075_50750201_98_dialog_content = "*suspiros* Estou bem e sem ferimentos, não se preocupe.",
  ui_story_5075_50750201_99_dialog_content = "Mas o rei vai te punir novamente se descobrir que você saiu sem nenhum guarda a reboque.",
  ui_story_5075_50750201_100_dialog_content = "Eu já cresci agora! E-Eu não tenho medo de punição!",
  ui_story_5075_50750201_101_dialog_content = "Além disso, como um verdadeiro homem, devo estar lá para minha noiva em tempos de crise!",
  ui_story_5075_50750201_102_dialog_content = "Pfft—",
  ui_story_5075_50750201_103_dialog_content = "Como você pode dizer isso—",
  ui_story_5075_50750201_104_dialog_content = "Oh? Um homem de verdade? Parece que eu deixei algo passar.",
  ui_story_5075_50750201_105_dialog_content = "Sua carga de estudos está atualmente no nível das crianças, mas como você já é um homem de verdade, bem...",
  ui_story_5075_50750201_106_dialog_content = "Vou ter que dizer ao professor que seu dever de casa está muito leve e precisamos dobrá-lo a partir de agora!",
  ui_story_5075_50750201_107_dialog_content = "Não... Por favor, não! Eu admito... Ainda não me tornei um homem de verdade!",
  ui_story_5075_50750201_108_dialog_content = "E-Eu posso ter grandes aspirações, mas meu corpo e mente não estão totalmente desenvolvidos para tal carga!",
  ui_story_5075_50750201_109_dialog_content = "... Cansei por hoje. Estou voltando para descansar.",
  ui_story_5075_50750201_110_dialog_content = "Dantang, vamos sair juntos novamente amanhã!",
  ui_story_5075_50750201_111_dialog_content = "Contratamos um novo chef que é especialista em culinária Ye. Pai te convidou para um banquete amanhã.",
  ui_story_5075_50750201_112_dialog_content = "Você tem que vir!",
  ui_story_5075_50750201_113_dialog_content = "*suspira*",
  ui_story_5075_50750201_114_dialog_content = "Obrigado pela sua ajuda, senhor, ou o príncipe nunca voltaria.",
  ui_story_5075_50750201_115_dialog_content = "Este é o Conselheiro Chefe do Rei do Reino de Ji, PlayerName.",
  ui_story_5075_50750201_116_dialog_content = "E também meu mentor.",
  ui_story_5075_50750201_117_dialog_content = "Eu consegui prosperar em Ji graças à sua ajuda e orientação.",
  ui_story_5075_50750201_118_dialog_content = "(Ele é realmente tão importante? Espere, como as pessoas costumam mostrar respeito em Longzhou?)",
  ui_story_5075_50750201_119_dialog_content = "Bom te ver, senhor!",
  ui_story_5075_50750201_120_dialog_content = "Senhor, este é PlayerName de Astra, acredito que você o viu durante o banquete.",
  ui_story_5075_50750201_121_dialog_content = "Hmm, estou profundamente impressionado.",
  ui_story_5075_50750201_122_dialog_content = "(Sim, ele é definitivamente o professor de Dantang. Seu olhar me deixa ainda mais nervoso do que uma sala inteira de pessoas me encarando...)",
  ui_story_5075_50750201_123_dialog_content = "Hã? Aquela marca na carta que você está segurando...",
  ui_story_5075_50750201_124_dialog_content = "Um relatório urgente do Escritório de Inspeção.",
  ui_story_5075_50750201_125_dialog_content = "É do esquadrão que foi apressadamente enviado para defender a baía devido ao aumento da presença de Eclipsitas?",
  ui_story_5075_50750201_126_dialog_content = "Agora, seus oponentes, temo, são mais do que apenas espíritos malignos.",
  ui_story_5075_50750201_127_dialog_content = "De acordo com o relatório urgente, logo após o terremoto, os demônios perto do mar de repente enlouqueceram e começaram a prejudicar as pessoas.",
  ui_story_5075_50750201_128_dialog_content = "Embora as patrulhas tenham intervindo a tempo e os tenham parado, receio que este não seja um incidente isolado.",
  ui_story_5075_50750201_129_dialog_content = "Fiendlings frenéticos? Mas como? Há mais no terremoto do que simplesmente ser um desastre natural?",
  ui_story_5075_50750202_1_dialog_content = "É por isso que vim aqui, esperando que você possa investigar isso para nós.",
  ui_story_5075_50750202_2_dialog_content = "Claro, amanhã eu vou—",
  ui_story_5075_50750202_3_dialog_content = "Você não deveria cuidar do príncipe para o rei novamente amanhã?",
  ui_story_5075_50750202_4_dialog_content = "Bem, hum...",
  ui_story_5075_50750202_5_dialog_content = "Tem alguma coisa que eu possa fazer?",
  ui_story_5075_50750202_6_dialog_content = "Dantang pode não ter tempo livre, mas eu tenho. Se tudo que você precisa é de alguém para investigar, eu posso lidar com isso muito bem.",
  ui_story_5075_50750202_7_dialog_content = "Não. Já é um grande favor seu vir como emissário, PlayerName.",
  ui_story_5075_50750202_8_dialog_content = "Como podemos sobrecarregar você com os assuntos de Ji?",
  ui_story_5075_50750202_9_dialog_content = "Acredito que seja viável.",
  ui_story_5075_50750202_10_dialog_content = "Senhor?",
  ui_story_5075_50750202_11_dialog_content = "Revisei a proposta de troca de Zhuohua.",
  ui_story_5075_50750202_12_dialog_content = "Mas na corte real, está claro que o rei não está interessado em execução imediata.",
  ui_story_5075_50750202_13_dialog_content = "Que pena.",
  ui_story_5075_50750202_14_dialog_content = "PlayerName, sendo um emissário, você deve gostar de outra chance de persuadir o rei.",
  ui_story_5075_50750202_15_dialog_content = "Isso mesmo.",
  ui_story_5075_50750202_16_dialog_content = "Muitas pessoas me ajudaram a chegar aqui, e tantas outras estão contando comigo. Eu me recuso a voltar de mãos vazias.",
  ui_story_5075_50750202_17_dialog_content = "Bem, essa é uma oportunidade de ouro.",
  ui_story_5075_50750202_18_dialog_content = "Como o Festival da Primavera está logo ali, a cidade está agitada com pessoas, juntamente com várias atividades.",
  ui_story_5075_50750202_19_dialog_content = "Então, qualquer problema causado por espíritos malignos e demônios pode levar a sérias consequências e prejudicar os cidadãos.",
  ui_story_5075_50750202_20_dialog_content = "E quando isso acontecer, se alguém pudesse resolver logo, seria uma ação meritória.",
  ui_story_5075_50750202_21_dialog_content = "O rei certamente concederá recompensas onde elas são devidas.",
  ui_story_5075_50750202_22_dialog_content = "Na verdade, eu não me importo nem um pouco com recompensas. Afinal, eu nem sei o que fazer com a pilha de presentes que tenho de volta na pousada...",
  ui_story_5075_50750202_23_dialog_content = "Mas se possível, eu realmente gostaria de usar isso como uma oportunidade para compartilhar nosso plano com o rei!",
  ui_story_5075_50750202_24_dialog_content = "Então, por favor, deixe essa tarefa comigo, senhor.",
  ui_story_5075_50750202_25_dialog_content = "Tenho outro pedido e, se você concordar, deixarei essa questão em suas mãos.",
  ui_story_5075_50750202_26_dialog_content = "O que foi?",
  ui_story_5075_50750202_27_dialog_content = "... Tente manter um perfil discreto durante sua investigação e não deixe ninguém na corte real saber sobre isso.",
  ui_story_5075_50750202_28_dialog_content = "Senhor, PlayerName é estrangeiro e não está familiarizado com o Reino Ji, muito menos em realizar uma missão sozinho.",
  ui_story_5075_50750202_29_dialog_content = "Eu nunca disse que PlayerName deveria lidar com isso sozinho.",
  ui_story_5075_50750202_30_dialog_content = "Não entendeu minha dica, huh? Zhuohua, você está sendo muito impaciente.",
  ui_story_5075_50750202_31_dialog_content = "...",
  ui_story_5075_50750202_32_dialog_content = "Tudo bem, Dantang.",
  ui_story_5075_50750202_33_dialog_content = "Já peguei muitos trabalhos que me levaram a lugares desconhecidos em Astra. Por mais difíceis que fossem esses trabalhos, ganhei muita experiência com esse tipo de coisa.",
  ui_story_5075_50750202_34_dialog_content = "Ótimo.",
  ui_story_5075_50750202_35_dialog_content = "Zhuohua, veja nosso jovem visitante fora do palácio.",
  ui_story_5075_50750202_36_dialog_content = "Certamente...",
  ui_story_5075_50750202_37_dialog_content = "PlayerName—",
  ui_story_5075_50750202_38_dialog_content = "Só para que você saiba, eu não vou ouvir se você for se desculpar ou tentar me convencer do contrário.",
  ui_story_5075_50750202_39_dialog_content = "Mas se você for feito para correr assim enquanto eu fico no palácio...",
  ui_story_5075_50750202_40_dialog_content = "Mas a comida é deliciosa no banquete.",
  ui_story_5075_50750202_41_dialog_content = "?",
  ui_story_5075_50750202_42_dialog_content = "Você não acha que é muitas vezes melhor do que a tarifa em Twin Pavilions Bay?",
  ui_story_5075_50750202_43_dialog_content = "Sim, já que são preparados pelo chef real.",
  ui_story_5075_50750202_44_dialog_content = "Em outras palavras, não fomos nós que fizemos isso. Nós também não plantamos o arroz, certo?",
  ui_story_5075_50750202_45_dialog_content = "É claro, vem de fazendeiros locais.",
  ui_story_5075_50750202_46_dialog_content = "Então nós o enviamos para a cidade?",
  ui_story_5075_50750202_47_dialog_content = "Não, as casas de comércio em todo o país são responsáveis por isso.",
  ui_story_5075_50750202_48_dialog_content = "Nós compramos nós mesmos?",
  ui_story_5075_50750202_49_dialog_content = "Não, essa é a tarefa do tesoureiro real.",
  ui_story_5075_50750202_50_dialog_content = "E ainda assim você não se preocupou em incomodá-los, ou se ofereceu para fazer essas coisas por eles.",
  ui_story_5075_50750202_51_dialog_content = "... Eu não sou tão presunçoso para acreditar que posso fazer o trabalho deles.",
  ui_story_5075_50750202_52_dialog_content = "Esta tarefa também não é diferente.",
  ui_story_5075_50750202_53_dialog_content = "Ninguém pode fazer tudo sozinho. Se você não está livre para fazer algo enquanto eu tenho tempo e habilidade, eu deveria ser o que está fazendo isso.",
  ui_story_5075_50750202_54_dialog_content = "Incomodar os outros, depender dos outros, é assim que o mundo funciona.",
  ui_story_5075_50750202_55_dialog_content = "Claro, se você acha que eu não sou capaz de lidar com o trabalho...",
  ui_story_5075_50750202_56_dialog_content = "Eu jamais!",
  ui_story_5075_50750202_57_dialog_content = "... Você sabe, você é mais adequado para ser um debatedor do que um emissário, PlayerName.",
  ui_story_5075_50750202_58_dialog_content = "Por mais sensato que você tenha sido, seria sábio da minha parte me render.",
  ui_story_5075_50750202_59_dialog_content = "Haha, se você diz...",
  ui_story_5075_50750202_60_dialog_content = "É maravilhoso ver que você está muito melhor do que quando partimos.",
  ui_story_5075_50750202_61_dialog_content = "Ahem. Foi assim tão óbvio?",
  ui_story_5075_50750202_62_dialog_content = "É por minha causa que você se estressou demais, com as relações diplomáticas, as consequências do terremoto...",
  ui_story_5075_50750202_63_dialog_content = "Sem mencionar a preocupação com a possibilidade de eu ser injustiçado, você está tão estressado que não tem sido você mesmo ultimamente.",
  ui_story_5075_50750202_64_dialog_content = "Então você acha que eu estou preocupado com muitas coisas?",
  ui_story_5075_50750202_65_dialog_content = "Dificilmente, eu tomei isso mais como um conselho amigável.",
  ui_story_5075_50750202_66_dialog_content = "Por sua causa, devo me recompor e resolver os problemas o mais rápido possível.",
  ui_story_5075_50750202_67_dialog_content = "Bom, então vamos dar o nosso melhor juntos! Mesmo que não estejamos exatamente lutando na mesma frente—",
  ui_story_5075_50750202_68_dialog_content = "Ainda podemos trabalhar juntos e atingir nossos objetivos.",
  ui_story_5075_50750202_69_dialog_content = "Emissário estimado, estou aqui para acompanhá-lo de volta.",
  ui_story_5075_50750202_70_dialog_content = "Oh, olá de novo. Você está aqui apenas para me acompanhar de volta?",
  ui_story_5075_50750202_71_dialog_content = "Certamente. Enquanto você estiver no Reino Ji, será um convidado de honra em nossa Pousada Real, e não negligenciaremos nossos deveres.",
  ui_story_5075_50750202_72_dialog_content = "Parece que é hora de eu ir. Vou te manter atualizado, Dantang!",
  ui_story_5075_50750202_73_dialog_content = "Então, aguardarei suas boas notícias no palácio.",
  ui_story_5075_50750202_74_dialog_content = "<color=#e8d9bb>Momentos depois—</color>",
  ui_story_5075_50750202_75_dialog_content = "Sua Alteza? O que está fazendo aqui sozinho?",
  ui_story_5075_50750202_76_dialog_content = "Ah, você voltou, Jiu. Como está indo com aquela coisa sobre a qual falamos?",
  ui_story_5075_50750202_77_dialog_content = "Ainda estou trabalhando duro nisso.",
  ui_story_5075_50750202_78_dialog_content = "Mas ainda há numerosos agentes secretos ativos em Haojin.",
  ui_story_5075_50750202_79_dialog_content = "Então, por favor, tenha cuidado quando eu não estiver por perto.",
  ui_story_5075_50750202_80_dialog_content = "Entendi. Muito bem, Jiu.",
  ui_story_5075_50750202_81_dialog_content = "Vou ficar no palácio por um futuro previsível, então, não estou esperando nenhum perigo.",
  ui_story_5075_50750202_82_dialog_content = "Ah, me lembre de escrever uma carta quando voltarmos.",
  ui_story_5075_50750202_83_dialog_content = "Até o Capitão Yuebai entregou todas as cargas e está de volta em Haojin...",
  ui_story_5075_50750202_84_dialog_content = "Uma certa Ministra Armilla não manteve contato, exceto por uma mensagem enigmática desde que desembarcou...",
  ui_story_5075_50750202_85_dialog_content = "Vejo que terei que repreendê-la eu mesmo.",
  ui_story_5075_50750202_86_dialog_content = "Hum?",
  ui_story_5075_50750202_87_dialog_content = "O que há de errado, Sua Alteza?",
  ui_story_5075_50750202_88_dialog_content = "Fique tranquilo. Estou apenas um pouco surpreso.",
  ui_story_5075_50750202_89_dialog_content = "Parece que as flores desta ameixeira floresceram num piscar de olhos.",
  ui_story_5075_50750202_90_dialog_content = "Mas você não prefere apenas begônias?",
  ui_story_5075_50750202_91_dialog_content = "Sim, mas também acho as flores de ameixeira de hoje deliciosas.",
  ui_story_5075_50750301_1_dialog_content = "(Mesmo estando cheio de confiança quando concordei em fazer essa investigação...)",
  ui_story_5075_50750301_2_dialog_content = "(Não esperava encontrar um obstáculo tão grande logo de cara!)",
  ui_story_5075_50750301_3_dialog_content = "Ei... Toda essa proteção é meio desnecessária, você não acha? Eu só queria fazer umas comprinhas.",
  ui_story_5075_50750301_4_dialog_content = "Vossa Excelência, considerando o seu distinto status, seis guardas são apenas a medida de segurança básica, nada de especial.",
  ui_story_5075_50750301_5_dialog_content = "Já solicitei a adição de mais nove guardas para garantir sua segurança.",
  ui_story_5075_50750301_6_dialog_content = "Mais guardas?",
  ui_story_5075_50750301_7_dialog_content = "Esquece, tenho algo mais importante para perguntar...",
  ui_story_5075_50750301_8_dialog_content = "Por que não há uma única pessoa nesta rua?",
  ui_story_5075_50750301_9_dialog_content = "Para evitar qualquer interrupção indesejada em seu lazer, nós limpamos a área com antecedência.",
  ui_story_5075_50750301_10_dialog_content = "Mas isso simplesmente estraga toda a experiência!",
  ui_story_5075_50750301_11_dialog_content = "Você é muito superprotetor de qualquer maneira que se olhe!",
  ui_story_5075_50750301_12_dialog_content = "(Se eu não consigo nem falar com ninguém aqui fora, minha investigação terminará antes de começar.)",
  ui_story_5075_50750301_13_dialog_content = "... Não precisa se incomodar. Eu vou entregar para você.",
  ui_story_5075_50750301_14_dialog_content = "(Huh? Alguém está falando lá fora?)",
  ui_story_5075_50750301_15_dialog_content = "O palácio me disse para entregar isso pessoalmente ao emissário. Por favor, não torne as coisas difíceis para mim.",
  ui_story_5075_50750301_16_dialog_content = "Se esse é o caso, por favor entre.",
  ui_story_5075_50750301_17_dialog_content = "Saudações, Vossa Excelência.",
  ui_story_5075_50750301_18_dialog_content = "Estes são petiscos preparados pelo novo chef do palácio. Os nobres acham bastante saborosos.",
  ui_story_5075_50750301_19_dialog_content = "Então eles me enviaram para trazer alguns para você experimentar.",
  ui_story_5075_50750301_20_dialog_content = "Obrigado. Huh? Ainda está quente.",
  ui_story_5075_50750301_21_dialog_content = "Apesar do clima ameno de Haojin, ainda é inverno.",
  ui_story_5075_50750301_22_dialog_content = "Então, há um aquecedor embaixo do recipiente de comida para manter tudo quente e saboroso para você.",
  ui_story_5075_50750301_23_dialog_content = "O aquecedor ali usa uma nova técnica importada do Reino Ye.",
  ui_story_5075_50750301_24_dialog_content = "E seu estilo é meticulosamente projetado, com artesãos habilidosos esculpindo flores no interior, tornando-o um ornamento adequado.",
  ui_story_5075_50750301_25_dialog_content = "No interior? Por que fazer esculturas tão intrincadas em um lugar onde ninguém pode vê-las?",
  ui_story_5075_50750301_26_dialog_content = "Bem, eles disseram... é mais fácil lidar com as coisas onde não é visível.",
  ui_story_5075_50750301_27_dialog_content = "O quê?",
  ui_story_5075_50750301_28_dialog_content = "Eu estava apenas murmurando para mim mesmo. Aproveite o seu tempo, estimado emissário. Eu voltarei ao palácio e farei o relatório.",
  ui_story_5075_50750301_29_dialog_content = "Emissário estimado, gostaria de alguns lanches agora? Ou há algo mais que você precisa?",
  ui_story_5075_50750301_30_dialog_content = "Não, obrigado. Estou um pouco cansado, então acho que vou tirar uma soneca por agora. Vocês podem ir.",
  ui_story_5075_50750301_31_dialog_content = "Ah, você pode deixar a comida bem aqui. Eu vou comer quando acordar.",
  ui_story_5075_50750301_32_dialog_content = "Sim, Vossa Excelência.",
  ui_story_5075_50750301_33_dialog_content = "<color=#e8d9bb>O aquecedor está soltando uma fumaça fraca, e através das peças de cobre entrelaçadas, você pode ver as chamas tremulando por dentro.</color>",
  ui_story_5075_50750301_34_dialog_content = "<color=#e8d9bb>Clic.</color>",
  ui_story_5075_50750301_35_dialog_content = "<color=#e8d9bb>Assim que as chamas dentro do aquecedor se apagam, as peças de cobre que estavam anteriormente interligadas de repente se espalham.</color>",
  ui_story_5075_50750301_36_dialog_content = "<color=#e8d9bb>Então, eles se desdobram em uma pequena e delicada flor de begônia.</color>",
  ui_story_5075_50750301_37_dialog_content = "Há uma insígnia escondida dentro, assim como uma nota?",
  ui_story_5075_50750301_38_dialog_content = "May que você goze de boa saúde durante sua estadia em Ji para aliviar a ansiedade da Princesa Zhuohua, Vossa Excelência.",
  ui_story_5075_50750301_39_dialog_content = "Ela estava entregando uma mensagem secreta de Dantang!",
  ui_story_5075_50750301_40_dialog_content = "(A insígnia pertence àquele \"Escritório de Inspeção\", eu acho, mas não sei o que fazer com ela agora.)",
  ui_story_5075_50750301_41_dialog_content = "(É um mapa? Com um endereço ainda!)",
  ui_story_5075_50750301_42_dialog_content = "(As empregadas acontecem estar fora agora! Esta é a minha chance!)",
  ui_story_5075_50750301_43_option_content = "Varredura Psíquica",
  ui_story_5075_50750301_44_dialog_content = "(Posso sentir dois guardas a leste e três ao sul... Então, parece que vou para o oeste.)",
  ui_story_5075_50750301_45_dialog_content = "Ei, se mova rápido! O emissário está desaparecido!",
  ui_story_5075_50750301_46_dialog_content = "Você fica aqui. Eu vou lá e vejo se consigo encontrar alguma coisa!",
  ui_story_5075_50750301_47_dialog_content = "(Isso não demorou nada, mas felizmente cheguei à beira do pátio. Agora só preciso passar por essas paredes...)",
  ui_story_5075_50750301_48_dialog_content = "... Eles são muito altos!",
  ui_story_5075_50750301_49_dialog_content = "Estimada Enviada! Estimada Enviada!",
  ui_story_5075_50750301_50_dialog_content = "(Eu vou estar cercado em pouco tempo! Tenho que pensar em algo...)",
  ui_story_5075_50750301_51_dialog_content = "Você está brincando de esconde-esconde?",
  ui_story_5075_50750301_52_dialog_content = "Hã?",
  ui_story_5075_50750301_53_dialog_content = "Aqui!",
  ui_story_5075_50750301_54_dialog_content = "Olhe para cima.",
  ui_story_5075_50750301_55_dialog_content = "Uma criança pequena? O que você está fazendo em cima do muro? É perigoso lá em cima!",
  ui_story_5075_50750301_56_dialog_content = "Não é perigoso de todo. Eu até consigo andar numa corda.",
  ui_story_5075_50750301_57_dialog_content = "Então você está brincando de esconde-esconde? Eu também quero brincar.",
  ui_story_5075_50750301_58_dialog_content = "Não estou jogando...",
  ui_story_5075_50750301_59_dialog_content = "Emissário estimado? Você está aqui?",
  ui_story_5075_50750301_60_dialog_content = "Uh-oh! Desculpe, mas eu tenho que ir—",
  ui_story_5075_50750301_61_dialog_content = "!",
  ui_story_5075_50750301_62_dialog_content = "Ah, uh... Eu só estava indo dar uma volta!",
  ui_story_5075_50750301_63_dialog_content = "Emissário? Você está por aqui?",
  ui_story_5075_50750301_64_dialog_content = "?",
  ui_story_5075_50750301_65_dialog_content = "Não está aqui também. Para onde ele foi?",
  ui_story_5075_50750301_66_dialog_content = "Emissário—",
  ui_story_5075_50750301_67_dialog_content = "E você disse que não estava jogando.",
  ui_story_5075_50750301_68_dialog_content = "Aquele guarda não me viu agora há pouco. Você fez isso?",
  ui_story_5075_50750301_69_dialog_content = "Hehe. Talvez um pouco.",
  ui_story_5075_50750301_70_dialog_content = "?",
  ui_story_5075_50750301_71_dialog_content = "?",
  ui_story_5075_50750301_72_dialog_content = "Espere um minuto.",
  ui_story_5075_50750301_73_dialog_content = "Você não deveria estar impressionado com minha aura dominante e cair de joelhos perante o grande e majestoso Chen'ni até agora?",
  ui_story_5075_50750301_74_dialog_content = "Aura dominante...",
  ui_story_5075_50750301_75_dialog_content = "Uh, o que te faz pensar que eu deveria fazer isso?",
  ui_story_5075_50750301_76_dialog_content = "Porque foi isso que eu ouvi do contador de histórias na ponte no meu caminho para cá!",
  ui_story_5075_50750301_77_dialog_content = "Ele disse que essa é a tendência atual. Isso não está certo?",
  ui_story_5075_50750301_78_dialog_content = "Eu não acho que era exatamente isso que ele estava falando...",
  ui_story_5075_50750301_79_dialog_content = "Enfim—",
  ui_story_5075_50750301_80_dialog_content = "Definitivamente ouvi algo acontecendo aqui.",
  ui_story_5075_50750301_81_dialog_content = "Mas eu acabei de verificar... Bem, só para garantir, vamos verificar novamente.",
  ui_story_5075_50750301_82_dialog_content = "Vamos brincar de esconde-esconde!",
  ui_story_5075_50750301_83_dialog_content = "Eu só preciso de ajuda para sair daqui primeiro. Acha que pode fazer isso, grande e majestoso Chen'ni?",
  ui_story_5075_50750301_84_dialog_content = "Oh, você certamente tem uma língua loquaz para uma criança!",
  ui_story_5075_50750301_85_dialog_content = "Relaxe. Sou um especialista neste jogo. Você não vai errar com Chen'ni!",
  ui_story_5075_50750301_86_dialog_content = "O segredo é ir com tudo!",
  ui_story_5075_50750302_1_dialog_content = "Huff... Puff...",
  ui_story_5075_50750302_2_dialog_content = "Estou começando a pensar... que você realmente não sabe como jogar esconde-esconde...",
  ui_story_5075_50750302_3_dialog_content = "Isso é impossível.",
  ui_story_5075_50750302_4_dialog_content = "Veja, aqui estamos fora do portão.",
  ui_story_5075_50750302_5_dialog_content = "E ninguém nos pegou todo esse tempo.",
  ui_story_5075_50750302_6_dialog_content = "Estou dizendo que você não deveria correr assim durante a brincadeira de esconde-esconde...",
  ui_story_5075_50750302_7_dialog_content = "E o fato de ninguém ter nos visto significa que você trapaceou de alguma forma.",
  ui_story_5075_50750302_8_dialog_content = "...Então, novamente, acho que isso significa que eu também trapaceei.",
  ui_story_5075_50750302_9_dialog_content = "De qualquer forma, obrigado novamente, Chen'ni... Quer dizer, o grande e majestoso Chen'ni!",
  ui_story_5075_50750302_10_dialog_content = "Bem, já que você foi gentil o suficiente para brincar comigo, podemos dispensar o tratamento formal.",
  ui_story_5075_50750302_11_dialog_content = "Claro, Chen'ni. A propósito, meu nome é PlayerName. Eu sou—",
  ui_story_5075_50750302_12_dialog_content = "Um Celestita.",
  ui_story_5075_50750302_13_dialog_content = "Eu sei.",
  ui_story_5075_50750302_14_dialog_content = "Hã?",
  ui_story_5075_50750302_15_dialog_content = "Emissário? É você lá fora?",
  ui_story_5075_50750302_16_dialog_content = "Devo sair daqui enquanto ainda posso.",
  ui_story_5075_50750302_17_dialog_content = "Emissário estimado, é realmente você!",
  ui_story_5075_50750302_18_dialog_content = "Por que você saiu sem guardas? É muito arriscado.",
  ui_story_5075_50750302_19_dialog_content = "Guardas!",
  ui_story_5075_50750302_20_dialog_content = "Espere, eu não...",
  ui_story_5075_50750302_21_dialog_content = "Rangido!",
  ui_story_5075_50750302_22_dialog_content = "Ahh—um rato! S-Socorro!",
  ui_story_5075_50750302_23_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5075_50750302_24_dialog_content = "Ahhh! É um diabólico... Um diabólico está nos atacando!",
  ui_story_5075_50750302_25_dialog_content = "... Silêncio, não seja tão alto.",
  ui_story_5075_50750302_26_dialog_content = "<color=#e8d9bb>Baque.</color>",
  ui_story_5075_50750302_27_dialog_content = "O que é que você fez, Chen'ni?",
  ui_story_5075_50750302_28_dialog_content = "Coloque-a para dormir um pouco.",
  ui_story_5075_50750302_29_dialog_content = "Esse é o próximo.",
  ui_story_5075_50750302_30_dialog_content = "Rangido...",
  ui_story_5075_50750302_31_dialog_content = "Isso definitivamente não é um rato comum...",
  ui_story_5075_50750302_32_dialog_content = "Isso deve ser um daqueles demônios que Liqing e os outros me contaram. Um demônio que falhou em assumir uma forma adequada.",
  ui_story_5075_50750302_33_dialog_content = "Algo sobre isso me faz sentir realmente desconfortável... É frenético, não é?",
  ui_story_5075_50750302_X33_dialog_content = "De acordo com o relatório urgente, logo após o terremoto, os demônios perto do mar de repente enlouqueceram e começaram a prejudicar as pessoas.",
  ui_story_5075_50750302_34_dialog_content = "Você poderia dizer?",
  ui_story_5075_50750302_35_dialog_content = "Então você também deve ser capaz de ver isso.",
  ui_story_5075_50750302_36_dialog_content = "<color=#e8d9bb>As pontas dos dedos de Chen'ni passam pelo diabólico caído, puxando uma sombra escura de seu corpo.</color>",
  ui_story_5075_50750302_37_dialog_content = "<color=#e8d9bb>É como uma névoa turva, com um toque vago de malícia se acumulando.</color>",
  ui_story_5075_50750302_38_option_content = "Tentar telepatia",
  ui_story_5075_50750302_39_dialog_content = "Ódio...",
  ui_story_5075_50750302_40_dialog_content = "Ai—",
  ui_story_5075_50750302_41_dialog_content = "Dói quando uso meus poderes nele, como se estivesse tocando um líquido corrosivo... O que é isso?",
  ui_story_5075_50750302_42_dialog_content = "Uma praga persistente e podre.",
  ui_story_5075_50750302_43_dialog_content = "Cuidado, está começando a se mover! Ele pode tentar fugir!",
  ui_story_5075_50750302_44_dialog_content = "<color=#e8d9bb>Mas a garota nem sequer pisca.</color>",
  ui_story_5075_50750302_45_dialog_content = "<color=#e8d9bb>Um simples beliscão e torção de Chen'ni, e a ameaçadora névoa negra se dispersa no ar como uma chama sufocada.</color>",
  ui_story_5075_50750302_46_dialog_content = "Vamos lá, eu não pulei a hora de dormir e vim aqui para esse tipo de problema.",
  ui_story_5075_50750302_47_dialog_content = "Vá brincar sozinho, PlayerName. Tenho outras coisas para fazer.",
  ui_story_5075_50750302_48_dialog_content = "Espere aí—",
  ui_story_5075_50750302_49_dialog_content = "O que devo fazer com esses dois?",
  ui_story_5075_50750302_50_dialog_content = "Ops, esqueci dessa bagunça.",
  ui_story_5075_50750302_51_dialog_content = "Ufa.",
  ui_story_5075_50750302_52_dialog_content = "<color=#e8d9bb>A garota segura a donzela pelo ombro e a \"leva voando\" de volta à Casa de Hóspedes Real.</color>",
  ui_story_5075_50750302_53_dialog_content = "<color=#e8d9bb>Então, agarrando a cauda do demônio, ela a lança longe no céu.</color>",
  ui_story_5075_50750302_54_dialog_content = "Isso está realmente bem?",
  ui_story_5075_50750302_55_dialog_content = "Claro. Fiendlings não são tão fracos.",
  ui_story_5075_50750302_56_dialog_content = "Se eles não pudessem suportar isso, seria melhor esquecerem a transformação e permanecerem como animais pelo resto de suas vidas.",
  ui_story_5075_50750302_57_dialog_content = "Tive essa sensação quando usei meus poderes, e considerando o comportamento estranho...",
  ui_story_5075_50750302_58_dialog_content = "Você também é um demônio, não é?",
  ui_story_5075_50750302_59_dialog_content = "Chen'ni? Ei, onde você foi?",
  ui_story_5075_50750302_60_dialog_content = "Ainda queria perguntar a ela sobre aquela bola de névoa negra... Ah, tudo bem.",
  ui_story_5075_50750302_61_dialog_content = "Talvez eu encontre ela novamente durante minha investigação.",
  ui_story_5075_50750302_62_dialog_content = "Por agora, eu deveria começar verificando este endereço.",
  ui_story_5075_50750302_63_dialog_content = "...",
  ui_story_5075_50750401_1_dialog_content = "É Festival da Primavera novamente. Venha e experimente nossas tangerinas da sorte doces!",
  ui_story_5075_50750401_2_dialog_content = "Pegue algumas tangerinas da sorte! Vamos lá, vou descascar uma para você. Não cobro se não estiver doce.",
  ui_story_5075_50750401_3_dialog_content = "Sementes de gergelim, sementes de melão e frutas açucaradas! Todos feitos de maneiras testadas pelo tempo! Jovem, por que não vem dar uma olhada?",
  ui_story_5075_50750401_4_dialog_content = "Está tão animado aqui. Andar pelas ruas sozinho é completamente diferente.",
  ui_story_5075_50750401_5_dialog_content = "Com licença, mas você sabe como chegar à Rua Yulin?",
  ui_story_5075_50750401_6_dialog_content = "É um pouco longe. Você deve seguir em direção à ponte mais movimentada primeiro, depois perguntar a outra pessoa após cruzar o cruzamento.",
  ui_story_5075_50750401_7_dialog_content = "Obrigado. Há tantas pessoas lá.",
  ui_story_5075_50750401_8_dialog_content = "Primeira vez aqui? A cidade de Haojin organiza feiras em cada Festival da Primavera - isso é um grande sucesso.",
  ui_story_5075_50750401_9_dialog_content = "Está bem naquela rua.",
  ui_story_5075_50750401_10_dialog_content = "Haverá atores famosos se apresentando mais tarde. Você definitivamente deveria ir assistir se não estiver com pressa ou algo assim.",
  ui_story_5075_50750401_11_dialog_content = "Claro, vou dar uma olhada quando tiver tempo.",
  ui_story_5075_50750401_12_dialog_content = "Ah, você escolheu a hora errada para vir. Este lugar costumava ser ainda mais animado nos anos anteriores.",
  ui_story_5075_50750401_13_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5075_50750401_14_dialog_content = "Que barulho foi esse?",
  ui_story_5075_50750401_15_dialog_content = "Ah, as crianças estão se divertindo brincando com fogos de artifício.",
  ui_story_5075_50750401_16_dialog_content = "Este não está alto o suficiente. Pegue outro!",
  ui_story_5075_50750401_17_dialog_content = "Fogos de artifício estouram, afugentando os demônios, banindo a má sorte de uma maneira alegre!",
  ui_story_5075_50750401_18_dialog_content = "<color=#e8d9bb>Esmaga, esmaga!</color>",
  ui_story_5075_50750401_19_dialog_content = "Hahahaha!",
  ui_story_5075_50750401_20_dialog_content = "Rangido...",
  ui_story_5075_50750401_21_dialog_content = "Isso é a sua ideia de diversão? Soltar fogos de artifício em uma rua movimentada como esta é perigoso!",
  ui_story_5075_50750401_22_dialog_content = "Esse demônio também não está enlouquecendo... Na verdade, parece completamente inofensivo!",
  ui_story_5075_50750401_23_dialog_content = "Não é grande coisa. Veja, mesmo para um Festival da Primavera comum, há uma tradição de usar fogos de artifício para afastar demônios.",
  ui_story_5075_50750401_24_dialog_content = "A única diferença é que eles costumavam contratar atores para interpretar demônios no passado, e essas crianças estão lidando com um real.",
  ui_story_5075_50750401_25_dialog_content = "Eu não levava esse ritual a sério antes, mas ultimamente, as coisas estão ficando inquietas.",
  ui_story_5075_50750401_26_dialog_content = "Talvez os demônios sejam de fato um pouco sinistros.",
  ui_story_5075_50750401_27_dialog_content = "Mesmo que você seja um recém-chegado, eu aconselho você a se manter longe dessas coisas. Infelizmente, estarei indo agora.",
  ui_story_5075_50750401_28_dialog_content = "Por que não está se movendo de jeito nenhum? Já está morto?",
  ui_story_5075_50750401_29_dialog_content = "Devemos tentar outra explosão?",
  ui_story_5075_50750401_30_dialog_content = "Pare com isso! Vocês crianças estão levando isso longe demais.",
  ui_story_5075_50750401_31_dialog_content = "!",
  ui_story_5075_50750401_32_dialog_content = "(A névoa negra novamente! E está sufocando o demônio!)",
  ui_story_5075_50750401_33_dialog_content = "Saia daqui, suas crianças!",
  ui_story_5075_50750401_34_dialog_content = "Huh? Por quê?",
  ui_story_5075_50750401_35_dialog_content = "...",
  ui_story_5075_50750401_36_dialog_content = "Este... parece um pouco estranho, não parece?",
  ui_story_5075_50750401_37_dialog_content = "Rangido!",
  ui_story_5075_50750401_38_dialog_content = "Oh não, é tarde demais—",
  ui_story_5075_50750401_39_dialog_content = "Aqui vem uma cabeçada!",
  ui_story_5075_50750401_40_dialog_content = "Rangido—",
  ui_story_5075_50750401_41_dialog_content = "O demônio... Ele foi cabeceado para o céu.",
  ui_story_5075_50750401_42_dialog_content = "Mantenha a guarda! Está voltando!",
  ui_story_5075_50750402_1_dialog_content = "Rangido...",
  ui_story_5075_50750402_2_dialog_content = "Relaxe, está tudo bem agora. Ei, pare de se contorcer ou vai acabar se machucando ainda mais.",
  ui_story_5075_50750402_3_dialog_content = "Rangido! Rangido!",
  ui_story_5075_50750402_4_dialog_content = "Você foi quem me ajudou agora há pouco, não foi? Muito obrigado, isso foi um comando incrível!",
  ui_story_5075_50750402_5_dialog_content = "Eu vi agora mesmo, a maneira como você se adiantou para salvar este demônio. Você deve ser uma pessoa realmente boa!",
  ui_story_5075_50750402_6_dialog_content = "Haha... Eu não fiz muito. Além disso, você foi quem o dominou.",
  ui_story_5075_50750402_7_dialog_content = "E você fez isso tão rápido também! Eu não acho que alguém sequer notou que algo aconteceu.",
  ui_story_5075_50750402_8_dialog_content = "Tudo isso faz parte do meu trabalho.",
  ui_story_5075_50750402_9_dialog_content = "Desculpe, ainda não me apresentei. Meu nome é Luo Song, e eu sou uma espécie de sacerdote errante.",
  ui_story_5075_50750402_10_dialog_content = "Rangido!",
  ui_story_5075_50750402_11_dialog_content = "Na maioria das vezes, apenas viajo pela terra, eliminando demônios de vez em quando.",
  ui_story_5075_50750402_12_dialog_content = "Rangido! Rangido!",
  ui_story_5075_50750402_13_dialog_content = "Algo tem agitado os demônios nesta área recentemente, fazendo-os perder a cabeça e atacar pessoas indiscriminadamente.",
  ui_story_5075_50750402_14_dialog_content = "Vim aqui para investigar a causa deste estranho fenômeno, mas até mesmo uma cidade tão bem guardada como Haojin...",
  ui_story_5075_50750402_15_dialog_content = "Rangido! Rangido!",
  ui_story_5075_50750402_16_dialog_content = "Há algo de errado com aquele demônio?",
  ui_story_5075_50750402_17_dialog_content = "Parece ser o caso. Desde que eu o capturei, ele não parou de tentar me morder ou se contorcer para sair.",
  ui_story_5075_50750402_18_dialog_content = "Assista, PlayerName.",
  ui_story_5075_50750402_19_dialog_content = "Ah, isso não é nada. Afinal, eu ganho a vida lidando com fiendlings o tempo todo.",
  ui_story_5075_50750402_20_dialog_content = "Para um diabólico como este, tudo o que você precisa fazer é segurar seu polegar e indicador assim...",
  ui_story_5075_50750402_21_dialog_content = "E com um pouco de pressão, não pode escapar!",
  ui_story_5075_50750402_22_dialog_content = "Eu vejo. Você realmente deve ser um profissional afinal!",
  ui_story_5075_50750402_23_dialog_content = "... Espere, não foi isso que eu estava perguntando!",
  ui_story_5075_50750402_24_dialog_content = "Deixe-me tentar sentir isso...",
  ui_story_5075_50750402_25_dialog_content = "Eu sabia. Aquela estranha bola de névoa negra ainda está dentro do corpo do fiendling.",
  ui_story_5075_50750402_26_dialog_content = "\"Bola estranha de névoa preta\"?",
  ui_story_5075_50750402_27_dialog_content = "Sim, eu posso ver! Aposto que essa névoa negra está fazendo os demônios saírem do controle.",
  ui_story_5075_50750402_28_dialog_content = "Algo assim está além da minha especialidade. Provavelmente é necessário o toque de um mestre para isso.",
  ui_story_5075_50750402_29_dialog_content = "A menos que você ache que podemos vencer essa névoa negra?",
  ui_story_5075_50750402_30_dialog_content = "Uh, provavelmente não.",
  ui_story_5075_50750402_31_dialog_content = "Mas eu conheci uma garota mais cedo—",
  ui_story_5075_50750402_32_dialog_content = "Ei! Por que vocês de repente correram e ficaram aqui sussurrando? Qual é o problema?",
  ui_story_5075_50750402_33_dialog_content = "Ah, quase esqueci desse bando de crianças.",
  ui_story_5075_50750402_34_dialog_content = "Sem mencionar... Eu nunca cheguei a perguntar o seu nome.",
  ui_story_5075_50750402_35_dialog_content = "Eu? Sou o PlayerName.",
  ui_story_5075_50750402_36_dialog_content = "É um prazer conhecer você, PlayerName. Você se importaria de segurar este cara para mim?",
  ui_story_5075_50750402_37_dialog_content = "Hã?",
  ui_story_5075_50750402_38_dialog_content = "Rangido!",
  ui_story_5075_50750402_39_dialog_content = "Ei, não jogue isso em mim assim! Uau, esse fiendling é mais forte do que parece!",
  ui_story_5075_50750402_40_dialog_content = "(Não estava nem se movendo na mão de Luo Song antes! Quão forte ele é - ei, pare de se mexer!)",
  ui_story_5075_50750402_41_option_content = "Aumento de Força!",
  ui_story_5075_50750402_42_dialog_content = "Rangido...",
  ui_story_5075_50750402_43_dialog_content = "Ufa, isso é melhor.",
  ui_story_5075_50750402_44_dialog_content = "<color=#e8d9bb>Baque! Baque! Baque!</color>",
  ui_story_5075_50750402_45_dialog_content = "<color=#e8d9bb>Luo Song dá um peteleco na cabeça das crianças como punição.</color>",
  ui_story_5075_50750402_46_dialog_content = "(Com a força de Luo Song, isso provavelmente dói muito...)",
  ui_story_5075_50750402_47_dialog_content = "Uaaaaahhh—",
  ui_story_5075_50750402_48_dialog_content = "Quem você pensa que é, cutucando nossas cabeças assim? Isso dói!",
  ui_story_5075_50750402_49_dialog_content = "Luo Song é o meu nome. Seja vagando pela terra ou lidando com demônios, isso não muda.",
  ui_story_5075_50750402_50_dialog_content = "Isso porque não tenho nada a esconder. Minhas intenções são retas e honestas.",
  ui_story_5075_50750402_51_dialog_content = "Você, por outro lado, tem muito a explicar para seus pais. Quais são os seus nomes?",
  ui_story_5075_50750402_52_dialog_content = "Acender fogos de artifício na rua para intimidar os fracos e indefesos não é algo que eu possa permitir, mesmo para crianças.",
  ui_story_5075_50750402_53_dialog_content = "Eu, eh, meu nome é...",
  ui_story_5075_50750402_54_dialog_content = "Espere, por que eu deveria te contar?",
  ui_story_5075_50750402_55_dialog_content = "Meus pais disseram que é porque esses demônios trazem má sorte que espíritos malignos têm causado caos ultimamente.",
  ui_story_5075_50750402_56_dialog_content = "Você está com eles, o que significa que você também não presta!",
  ui_story_5075_50750402_57_dialog_content = "Parece nada mais que superstição para mim.",
  ui_story_5075_50750402_58_dialog_content = "Além disso, usar as palavras de outras pessoas para desculpar seu mau comportamento ainda é inaceitável.",
  ui_story_5075_50750402_59_dialog_content = "Você já viu algum demônio trabalhando junto com os espíritos malignos?",
  ui_story_5075_50750402_60_dialog_content = "Bem... Embora não tenhamos visto isso, esse demônio roubou nosso melão de açúcar!",
  ui_story_5075_50750402_61_dialog_content = "Todos contribuíram com seu dinheiro de bolso para comprá-lo, mas num piscar de olhos, ele se foi.",
  ui_story_5075_50750402_62_dialog_content = "De fato!",
  ui_story_5075_50750402_63_dialog_content = "Ladrões não prestam, então o que fizemos é tudo para manter a comunidade segura!",
  ui_story_5075_50750402_64_dialog_content = "Você disse que sumiu num piscar de olhos, então isso significa que você nunca viu ele roubar seus lanches em primeiro lugar.",
  ui_story_5075_50750402_65_dialog_content = "Mas essa criatura era a única coisa se esgueirando por perto. Se não for ela, então quem mais poderia ser?",
  ui_story_5075_50750402_66_dialog_content = "PlayerName.",
  ui_story_5075_50750402_67_dialog_content = "Você poderia, por favor, verificar se há algum resíduo açucarado na boca desse diabólico?",
  ui_story_5075_50750402_68_dialog_content = "Deixe-me ver... Não.",
  ui_story_5075_50750402_69_dialog_content = "Além de um pouco de lama e alguns cortes e contusões, não há mais nada no corpo deste demônio.",
  ui_story_5075_50750402_70_dialog_content = "Isso não prova que não era o ladrão!",
  ui_story_5075_50750402_71_dialog_content = "Talvez tenha usado alguma mágica, transferindo o melão de açúcar para outro lugar num sopro.",
  ui_story_5075_50750402_72_dialog_content = "Uh, eu não acho que seria roubar doces se eles tivessem poderes assim.",
  ui_story_5075_50750402_73_dialog_content = "Como exatamente é o seu melão açucarado?",
  ui_story_5075_50750402_74_dialog_content = "O que mais poderia parecer? Apenas branco, redondo, como...",
  ui_story_5075_50750402_75_dialog_content = "Uma tangerina da sorte descascada?",
  ui_story_5075_50750402_76_dialog_content = "Exatamente! Um melão de açúcar tão bonito e saboroso, os diabinhos certamente iriam adorá-lo.",
  ui_story_5075_50750402_77_dialog_content = "Você comprou isso na barraca daquele velhote lá em cima na rua, certo?",
  ui_story_5075_50750402_78_dialog_content = "Se você tivesse que juntar todo o seu dinheiro para comprá-lo, provavelmente não poderia pagar mais nada depois.",
  ui_story_5075_50750402_79_dialog_content = "Mas as crianças são gananciosas, especialmente quando se trata de lanches - e aconteceu de haver um vendedor de tangerinas da sorte oferecendo amostras grátis por perto.",
  ui_story_5075_50750402_80_dialog_content = "Não me diga que você não viu.",
  ui_story_5075_50750402_81_dialog_content = "Fomos lá, e daí?",
  ui_story_5075_50750402_82_dialog_content = "Enquanto você estava comendo as tangerinas dele, onde você colocou o seu melão açucarado?",
  ui_story_5075_50750402_83_dialog_content = "Acabei de colocá-lo bem ao lado da barraca de frutas... Oh!",
  ui_story_5075_50750402_84_dialog_content = "De fato, este é o nosso melão de açúcar, misturado com as tangerinas da fortuna descascadas.",
  ui_story_5075_50750402_85_dialog_content = "...",
  ui_story_5075_50750402_86_dialog_content = "E assim a verdade aparece.",
  ui_story_5075_50750402_87_dialog_content = "O que vocês têm a dizer por si mesmos agora?",
  ui_story_5075_50750402_88_dialog_content = "Desculpe...",
  ui_story_5075_50750402_89_dialog_content = "Na próxima vez que se deparar com esse tipo de situação, pare e pense primeiro.",
  ui_story_5075_50750402_90_dialog_content = "Não pense que pode simplesmente culpar os demônios por todas as suas desgraças.",
  ui_story_5075_50750402_91_dialog_content = "Diga-me, machucar um demônio assim traria de volta o seu melão açucarado?",
  ui_story_5075_50750402_92_dialog_content = "Por causa de superstições e estereótipos, tendemos a rotular coisas que não entendemos como \"mal\" para que possamos atacá-las...",
  ui_story_5075_50750402_93_dialog_content = "Mas esse tipo de comportamento não é melhor do que uma criança fazendo birra.",
  ui_story_5075_50750402_94_dialog_content = "Isso não é um ato de heroísmo, mas de covardia. Você entende?",
  ui_story_5075_50750402_95_dialog_content = "Entendi...",
  ui_story_5075_50750402_96_dialog_content = "Bom, agora vá para casa e conte aos seus pais sobre o que aconteceu aqui hoje.",
  ui_story_5075_50750402_97_dialog_content = "Tá bom...",
  ui_story_5075_50750402_98_dialog_content = "Você acha que eles realmente vão contar aos pais deles sobre isso?",
  ui_story_5075_50750402_99_dialog_content = "Provavelmente não.",
  ui_story_5075_50750402_100_dialog_content = "Sei que minhas palavras estão apenas abordando os sintomas do problema, não suas causas subjacentes.",
  ui_story_5075_50750402_101_dialog_content = "Mas os rumores podem ser tão prejudiciais. A ideia de que os fiendlings trazem perigo e infortúnio só surgiu porque muitas pessoas falaram sobre isso.",
  ui_story_5075_50750402_102_dialog_content = "O que eu digo é a verdade, e enquanto eu continuar dizendo a verdade, algo eventualmente surgirá disso.",
  ui_story_5075_50750402_103_dialog_content = "Afinal, a verdade é verdade, e mentiras são mentiras.",
  ui_story_5075_50750402_104_dialog_content = "Você é uma pessoa incrível, Luo Song.",
  ui_story_5075_50750402_105_dialog_content = "Você até ajudou eles a encontrar o melão de açúcar em pouco tempo. Foi como se você tivesse visto pessoalmente todo o acontecimento!",
  ui_story_5075_50750402_106_dialog_content = "Haha, sobre isso...",
  ui_story_5075_50750402_107_dialog_content = "Eu não vi pessoalmente, mas alguém viu.",
  ui_story_5075_50750402_108_dialog_content = "Hmm... Você gostaria de conhecer meu amigo?",
  ui_story_5075_50750402_109_dialog_content = "Roooor!",
  ui_story_5075_50750402_110_dialog_content = "Seu amigo é um demônio?",
  ui_story_5075_50750402_111_dialog_content = "Seu nome é Ah Ding.",
  ui_story_5075_50750402_112_dialog_content = "Ele viu aquelas crianças perderem seu melão açucarado mais cedo e me contou tudo sobre isso.",
  ui_story_5075_50750402_113_dialog_content = "Eu pretendia levá-lo para contar a verdade diretamente às crianças, mas um vendedor de figuras de açúcar me impediu.",
  ui_story_5075_50750402_114_dialog_content = "Ele me disse que as pessoas aqui têm uma visão muito negativa dos demônios agora, e que trazer Ah Ding pode piorar as coisas.",
  ui_story_5075_50750402_115_dialog_content = "Então eu disse ao Ah Ding para me esperar aqui.",
  ui_story_5075_50750402_116_dialog_content = "O vendedor de estatuetas de açúcar é quem me ensinou a abordar essas crianças com a verdade.",
  ui_story_5075_50750402_117_dialog_content = "Quando penso nisso, as opiniões dele são perfeitamente válidas.",
  ui_story_5075_50750402_118_dialog_content = "Devo agradecê-lo e comprar algumas figuras de açúcar para Ah Ding e seus amigos, que estão escondidos em outros lugares.",
  ui_story_5075_50750402_119_dialog_content = "Uh, Luo Song? Eu sei que isso é um pouco forçado, mas... Aquele homem ali é o \"vendedor de figuras de açúcar\" sobre o qual você está falando?",
  ui_story_5075_50750402_120_dialog_content = "Sim, é ele!",
  ui_story_5075_50750402_121_dialog_content = "Você poderia esperar aqui alguns minutos enquanto eu vou cumprimentar meus pequenos amigos? Eu volto logo.",
  ui_story_5075_50750402_122_dialog_content = "...",
  ui_story_5075_50750402_123_dialog_content = "\"Vendedor de estatuetas de açúcar\"?",
  ui_story_5075_50750402_124_dialog_content = "Sim, sou eu mesmo!",
  ui_story_5075_50750500_1_dialog_content = "... Você não deveria ser um adivinho?",
  ui_story_5075_50750500_2_dialog_content = "Não-não. Confira este xarope cristalino.",
  ui_story_5075_50750500_3_dialog_content = "Então olhe para o artesanato realista.",
  ui_story_5075_50750500_4_dialog_content = "É possível apenas com habilidades passadas de geração em geração e anos de experiência.",
  ui_story_5075_50750500_5_dialog_content = "Juro no túmulo do meu ancestral que sou um verdadeiro fabricante de estatuetas de açúcar.",
  ui_story_5075_50750500_6_dialog_content = "Já faz bastante tempo desde que nos separamos no Shadowind.",
  ui_story_5075_50750500_7_dialog_content = "O destino nos trouxe aqui, então por que não te ofereço uma estatueta de açúcar gratuita?",
  ui_story_5075_50750500_8_dialog_content = "Não estou tentando desconfiar de você ou algo do tipo.",
  ui_story_5075_50750500_9_dialog_content = "Mas um presente seu não é algo que eu possa aceitar facilmente.",
  ui_story_5075_50750500_10_dialog_content = "Infelizmente. Não acredito...",
  ui_story_5075_50750500_11_dialog_content = "Apesar de me conhecer por pouco tempo, você já me entende tão bem.",
  ui_story_5075_50750500_12_dialog_content = "Já que você viu através de mim, vou direto ao ponto. Aqui, por favor, pegue isso.",
  ui_story_5075_50750500_13_dialog_content = "Esse é um acessório para meninas, não é?",
  ui_story_5075_50750500_14_dialog_content = "Um cliente meu deixou isso cair acidentalmente logo antes de você aparecer.",
  ui_story_5075_50750500_15_dialog_content = "Mas estou muito ocupado com as vendas para encontrá-la, então é tudo com você.",
  ui_story_5075_50750500_16_dialog_content = "Mas eu também tenho coisas para fazer.",
  ui_story_5075_50750500_17_dialog_content = "Não se preocupe. Descobri através da adivinhação que há um forte vínculo cármico entre vocês dois.",
  ui_story_5075_50750500_18_dialog_content = "Apenas cuide dos seus próprios assuntos, e vocês se encontrarão naturalmente.",
  ui_story_5075_50750500_19_dialog_content = "Acho que você ainda é um adivinho, afinal.",
  ui_story_5075_50750500_20_dialog_content = "Espere, agora que estou olhando mais de perto, isso parece com o que eu encontrei no Templo da Donzela do Dragão.",
  ui_story_5075_50750500_21_dialog_content = "E eu me lembro de ver isso em outra pessoa também.",
  ui_story_5075_50750500_22_dialog_content = "Não é possível...",
  ui_story_5075_50750500_23_dialog_content = "Diga-me, você sabe algo sobre os <color=#FFB400>diabólicos</color>? Li Tianxian?",
  ui_story_5075_50750500_24_dialog_content = "Claro que sim. Você se lembra do especial <color=#FFB400>Hexagrama Celestial de Adivinhação</color> que eu mesmo inventei?",
  ui_story_5075_50750500_25_dialog_content = "Também tem a ver com os mais reverenciados <color=#FFB400>Treze Principais Demônios</color> de Longzhou.",
  ui_story_5075_50750500_26_dialog_content = "Mas esses não são animais?",
  ui_story_5075_50750500_27_dialog_content = "Animais, demônios e deidades variam apenas em suas aparências específicas.",
  ui_story_5075_50750500_28_dialog_content = "Zhong Xu não te contou a história dos protetores demoníacos que eventualmente alcançaram a divindade?",
  ui_story_5075_50750500_29_dialog_content = "Esses treze demônios também são as divindades mais únicas em Longzhou.",
  ui_story_5075_50750500_30_dialog_content = "A <color=#FFB400>Donzela Dragão</color> em <color=#FFB400>Donzela Dragão Sobre Mares Turbulentos</color> que você conhece é uma delas.",
  ui_story_5075_50750500_31_dialog_content = "Embora o tempo tenha feito as pessoas esquecerem que as divindades que adoram são na verdade demônios.",
  ui_story_5075_50750500_32_dialog_content = "Eu divago - de volta à sua pergunta.",
  ui_story_5075_50750500_33_dialog_content = "Fiendlings empunham diferentes Artes da Força também, e para os principais fiendlings - ou deidades...",
  ui_story_5075_50750500_34_dialog_content = "O poder deles é tão avançado, que é chamado de \"sobrenatural\".",
  ui_story_5075_50750500_35_dialog_content = "Dizem que eles podem mudar o claisma, tornar-se invisíveis ou se transformar à vontade.",
  ui_story_5075_50750500_36_dialog_content = "Que invejável.",
  ui_story_5075_50750500_37_dialog_content = "Não me diga que essa garota também é uma... Espere, eu perguntei a você sobre os poderes dos demônios?",
  ui_story_5075_50750500_38_dialog_content = "Claro que você fez!",
  ui_story_5075_50750500_39_dialog_content = "Ah... Estes devem ser alguns Luminatics realmente poderosos. Não tenho certeza se consigo sentir algo neste nível.",
  ui_story_5075_50750500_40_dialog_content = "Receio que você terá que perguntar aos <color=#FFB400>deuses</color> sobre isso por si mesmo.",
  ui_story_5075_50750500_41_dialog_content = "Na verdade, eu tenho um mantra para você, embora não esteja nem perto do nível sobrenatural.",
  ui_story_5075_50750500_42_dialog_content = "Foi passado pelos antigos habitantes de Longzhou e é especialmente útil para esta circunstância.",
  ui_story_5075_50750500_43_dialog_content = "Venha, repita depois de mim.",
  ui_story_5075_50750500_44_dialog_content = "<color=#FFB400>Merry—Ano—Novo.</color>",
  ui_story_5075_50750500_45_dialog_content = "Merry—Ano—Novo.",
  ui_story_5075_50750500_46_dialog_content = "Aí está. Você vai fazer bom uso disso nos próximos dias, garantido.",
  ui_story_5075_50750500_47_dialog_content = "Não importa quais problemas você encontre, apenas repita, e a maioria das coisas ficará bem.",
  ui_story_5075_50750500_48_dialog_content = "Um encantamento tão simples é realmente tão poderoso?",
  ui_story_5075_50750500_49_dialog_content = "Oh, não subestime o poder de um mantra antigo.",
  ui_story_5075_50750500_50_dialog_content = "Na verdade, há quatro partes no mantra, mas o resto provavelmente ainda está além de você agora.",
  ui_story_5075_50750500_51_dialog_content = "Vou ensiná-los a você mais tarde, quando tivermos uma chance.",
  ui_story_5075_50750500_52_dialog_content = "Ok! Muito obrigado!",
  ui_story_5075_50750500_53_dialog_content = "Não fale disso.",
  ui_story_5075_50750500_54_dialog_content = "Quanto aos seus outros problemas, eu adoraria fazer uma leitura para você...",
  ui_story_5075_50750500_55_dialog_content = "Voltei, PlayerName. Desculpe por ter mantido você esperando.",
  ui_story_5075_50750500_56_dialog_content = "Mas eu realmente não tenho tempo agora.",
  ui_story_5075_50750500_57_dialog_content = "Então você não vai ler minha sorte afinal?",
  ui_story_5075_50750500_58_dialog_content = "Sobre qual fortuna você está falando?",
  ui_story_5075_50750500_59_dialog_content = "Isso me lembra! Você disse que é um sacerdote errante, Luo Song? Isso significa que você também pode usar a adivinhação para prever o futuro?",
  ui_story_5075_50750500_60_dialog_content = "O quê? Não deixe os outros te enganarem tão facilmente, PlayerName.",
  ui_story_5075_50750500_61_dialog_content = "Todo esse papo sobre destino, sorte e karma pode parecer convincente, até mesmo milagroso.",
  ui_story_5075_50750500_62_dialog_content = "Mas não é nada além de truques baratos sustentados por mentiras inteligentes.",
  ui_story_5075_50750500_63_dialog_content = "Hã?",
  ui_story_5075_50750500_64_dialog_content = "Contanto que você faça as coisas com a consciência limpa, qualquer resultado que desejar é possível.",
  ui_story_5075_50750500_65_dialog_content = "É sempre melhor tomar o destino em suas próprias mãos, em vez de deixá-lo nas mãos de algum truque mágico de um trapaceiro.",
  ui_story_5075_50750500_66_dialog_content = "(Li Tianxian...)",
  ui_story_5075_50750500_67_dialog_content = "(Não olhe para mim, eu sou apenas um fabricante de estatuetas de açúcar.)",
  ui_story_5075_50750500_68_dialog_content = "Bobo.",
  ui_story_5075_50750500_69_dialog_content = "Mentalidade unilateral.",
  ui_story_5075_50750500_70_dialog_content = "Não sabe nada, não sabe nada.",
  ui_story_5075_50750500_71_dialog_content = "Problema, problema.",
  ui_story_5075_50750500_72_dialog_content = "Que bobagem vocês dois estão falando agora? Tão incoerente, haha.",
  ui_story_5075_50750500_73_dialog_content = "...",
  ui_story_5075_50750500_74_dialog_content = "Ei, sua estatueta de açúcar está pronta.",
  ui_story_5075_50750500_75_dialog_content = "Obrigado... Espere, isso é apenas uma flor de ameixeira! Onde está minha estatueta de açúcar?",
  ui_story_5075_50750500_76_dialog_content = "Ah, desculpe, estou ficando sem xarope.",
  ui_story_5075_50750500_77_dialog_content = "Mas não fique com raiva. Quer dizer, assim como diz o poema...",
  ui_story_5075_50750500_78_dialog_content = "Beleza celestial, minha fonte de felicidade, minha chuva noturna, minha névoa matinal suave, anseio pelo seu toque durante a longa noite solitária. Enquanto as flores de ameixa florescem na minha janela tão brilhante, elas estendem suas pétalas, tão rápidas que parecem, convencendo meu coração de que minha beleza está próxima.",
  ui_story_5075_50750500_79_dialog_content = "Então, por que você não consegue ver esta <color=#FFB400>flor de ameixa</color> como uma doce <color=#FFB400>beleza</color>?",
  ui_story_5075_50750500_80_dialog_content = "Parece uma desculpa bem fraca para mim.",
  ui_story_5075_50750500_81_dialog_content = "Vamos lá, todos nós temos que ser românticos às vezes.",
  ui_story_5075_50750500_82_dialog_content = "Tudo bem, vou te deixar agora. Te vejo mais tarde!",
  ui_story_5075_50750500_83_dialog_content = "Lembre-se do que eu disse. Se estiver hesitante, tente <color=#FFB400>orar para as divindades</color>.",
  ui_story_5075_50750500_84_dialog_content = "Eles devem apresentar Dragon Maiden Over Turbulent Seas na feira mais tarde.",
  ui_story_5075_50750500_85_dialog_content = "Mas a divindade no palco não é uma verdadeira.",
  ui_story_5075_50750500_86_dialog_content = "Huh? Isso é... a névoa preta?",
  ui_story_5075_50750500_87_dialog_content = "Eu preciso ir investigar!",
  ui_story_5075_50750500_88_dialog_content = "Espere, PlayerName, eu vou com você—",
  ui_story_5075_50750500_89_dialog_content = "Finalmente, posso voltar à leitura agora que o irritante se foi.",
  ui_story_5075_50750500_90_dialog_content = "Uh-oh.",
  ui_story_5075_50750500_91_dialog_content = "A divindade naquele palco pode ser de fato real.",
  ui_story_5075_50750601_1_dialog_content = "Rangido, rangido!",
  ui_story_5075_50750601_2_dialog_content = "Fique quieto e tente não chamar muita atenção.",
  ui_story_5075_50750601_3_dialog_content = "Hã? Já está acordado.",
  ui_story_5075_50750601_4_dialog_content = "Quanto mais se aproxima da feira, mais ele luta...",
  ui_story_5075_50750601_5_dialog_content = "Deve ser por causa da proximidade com a névoa negra.",
  ui_story_5075_50750601_6_dialog_content = "Julgando pela sua descrição, eu diria que ele tem algum tipo de capacidade de corromper.",
  ui_story_5075_50750601_7_dialog_content = "Como um veneno que faz os demônios enlouquecerem.",
  ui_story_5075_50750601_8_dialog_content = "Infelizmente, não tenho como expulsá-lo de seus corpos.",
  ui_story_5075_50750601_9_dialog_content = "Eu já vi demônios na selva com os mesmos sintomas, mas eles nunca se recuperaram. Tudo o que podiam fazer era se esconder em algum lugar longe das pessoas.",
  ui_story_5075_50750601_10_dialog_content = "Este pequeno demônio não é diferente...",
  ui_story_5075_50750601_11_dialog_content = "Você mencionou uma garota que poderia remover tal mancha antes. Podemos ir vê-la?",
  ui_story_5075_50750601_12_dialog_content = "Para dizer a verdade, eu só a conheci hoje. Tudo o que sei é que o nome dela é Chen'ni.",
  ui_story_5075_50750601_13_dialog_content = "Ela parece ser uma diabinha especialmente poderosa.",
  ui_story_5075_50750601_14_dialog_content = "Os acessórios que ela deixou para trás são a nossa única pista.",
  ui_story_5075_50750601_15_dialog_content = "Como alguém poderia se dar ao luxo de perder algo tão valioso, muito menos dois deles?",
  ui_story_5075_50750601_16_dialog_content = "Você não está falando sobre uma tornozeleira e uma pulseira de ouro, está?",
  ui_story_5075_50750601_17_dialog_content = "Como você sabia?",
  ui_story_5075_50750601_18_dialog_content = "Porque eu também os vi.",
  ui_story_5075_50750601_19_dialog_content = "Você também tem uma? Uma garotinha acabou de comprar um dumpling de sopa de mim.",
  ui_story_5075_50750601_20_dialog_content = "Ela comprou apenas um dumpling e pagou com isso.",
  ui_story_5075_50750601_21_dialog_content = "É isso ouro? Eu estava prestes a dizer que era demais, e ela de repente desapareceu quando eu olhei para cima.",
  ui_story_5075_50750601_22_dialog_content = "Mesmo aqui, mas eu nem mesmo a vi.",
  ui_story_5075_50750601_23_dialog_content = "Tudo que notei foi uma tigela a menos de taro de açúcar nesta mesa, e tudo que restou foi este pedaço de ouro.",
  ui_story_5075_50750601_24_dialog_content = "Você acha que foi o Deus da Fortuna?",
  ui_story_5075_50750601_25_dialog_content = "Hmm... Ela não parece ser uma deusa da riqueza, não é?",
  ui_story_5075_50750601_26_dialog_content = "Isso é realmente importante agora?",
  ui_story_5075_50750601_27_dialog_content = "A jovem que comprou raízes de lótus recheadas com ouro? Eu a vi. Ela provavelmente entrou.",
  ui_story_5075_50750601_28_dialog_content = "Bem-vindo! Dê uma olhada nos meus cartazes de ano novo! Cada um é cuidadosamente desenhado com a máxima atenção aos detalhes!",
  ui_story_5075_50750601_29_dialog_content = "A garota que pagou com ouro? Sim, eu me lembro dela.",
  ui_story_5075_50750601_30_dialog_content = "Ela realmente gostou dos meus pôsteres de ano novo, especialmente aqueles com o tema da Donzela do Dragão Sobre Mares Turbulentos. Ela pegou vários.",
  ui_story_5075_50750601_31_dialog_content = "Lembro-me que depois que ela comprou os pôsteres, havia gritos vindos do palco.",
  ui_story_5075_50750601_32_dialog_content = "Talvez ela tenha ido lá para ver do que se tratava o alvoroço.",
  ui_story_5075_50750601_33_dialog_content = "Ela disse que tinha algo mais para fazer antes de sair. Acho que ela quis dizer que iria conferir a feira.",
  ui_story_5075_50750601_34_dialog_content = "Parece que ela também fez um trabalho bastante meticuloso.",
  ui_story_5075_50750601_35_dialog_content = "Tudo aqui tem um gosto tão bom!",
  ui_story_5075_50750601_36_dialog_content = "Esses petiscos de arroz não são tão doces quanto os de Astra, mas ainda me fazem querer ainda mais!",
  ui_story_5075_50750601_37_dialog_content = "Concordo! A garota deve ter escolhido a melhor raiz de lótus recheada entre todas estas! São absolutamente incríveis!",
  ui_story_5075_50750601_38_dialog_content = "Você também gosta deles, Ah Ding?",
  ui_story_5075_50750601_39_dialog_content = "*Rugido*",
  ui_story_5075_50750601_40_dialog_content = "Isso me lembra, o que estávamos fazendo aqui de novo?",
  ui_story_5075_50750601_41_dialog_content = "...",
  ui_story_5075_50750601_42_dialog_content = "...",
  ui_story_5075_50750601_43_dialog_content = "A feira realmente tira sua mente das coisas, huh?",
  ui_story_5075_50750601_44_dialog_content = "Verdade, haha...",
  ui_story_5075_50750601_45_dialog_content = "Ainda assim, você notou algo?",
  ui_story_5075_50750601_46_dialog_content = "O demônio que trouxemos parou de lutar assim que chegamos aqui. Parece que ele se acalmou bastante.",
  ui_story_5075_50750601_47_dialog_content = "Deixe-me tentar usar meus poderes novamente...",
  ui_story_5075_50750601_48_dialog_content = "Não há mais névoa negra na área ao redor! Ela simplesmente desapareceu?",
  ui_story_5075_50750601_49_dialog_content = "Existe uma outra possibilidade. Uma ruim.",
  ui_story_5075_50750601_50_dialog_content = "A névoa pode estar se acumulando em outro lugar. Precisamos encontrar a garota antes que alguém se machuque.",
  ui_story_5075_50750601_51_dialog_content = "Ei, PlayerName!",
  ui_story_5075_50750601_52_dialog_content = "Chen'ni! Estou tão feliz que finalmente...",
  ui_story_5075_50750601_53_dialog_content = "Legal, você trouxe um amigo!",
  ui_story_5075_50750601_54_dialog_content = "Bem na hora! Suba no palco agora!",
  ui_story_5075_50750601_55_dialog_content = "Fazer o que agora?",
  ui_story_5075_50750601_56_dialog_content = "Você... Quer dizer, me perdoe, mas esse demônio—",
  ui_story_5075_50750601_57_dialog_content = "Mais um?",
  ui_story_5075_50750601_58_dialog_content = "<color=#e8d9bb>Assim como antes, Chen'ni acena casualmente com a mão, até mesmo de forma um tanto distraída.</color>",
  ui_story_5075_50750601_59_dialog_content = "<color=#e8d9bb>A névoa negra dentro do demônio é extraída e esmagada, como se nunca tivesse existido.</color>",
  ui_story_5075_50750601_60_dialog_content = "Rangido!",
  ui_story_5075_50750601_61_dialog_content = "<color=#e8d9bb>O pequeno demônio salta levemente para os pés de Chen'ni, inclinando a cabeça como se mostrasse gratidão.</color>",
  ui_story_5075_50750601_62_dialog_content = "Então você realmente é—",
  ui_story_5075_50750601_63_dialog_content = "Vamos lá, é a nossa vez!",
  ui_story_5075_50750601_64_dialog_content = "Há tantas pessoas lá embaixo!",
  ui_story_5075_50750601_65_dialog_content = "O que exatamente devemos estar fazendo aqui em cima?",
  ui_story_5075_50750601_66_dialog_content = "Dance a <color=#FFB400>Donzela do Dragão Sobre Mares Turbulentos</color>, claro.",
  ui_story_5075_50750601_67_dialog_content = "Olá, queridos concidadãos. Eu sei que todos vieram aqui hoje para os famosos artistas.",
  ui_story_5075_50750601_68_dialog_content = "Mas tenho certeza de que todos ouviram que a atriz que interpreta a Donzela do Dragão machucou o pé e não pode subir ao palco.",
  ui_story_5075_50750601_69_dialog_content = "Mas não podemos deixar o palco vazio durante a feira, então criamos um novo arranjo.",
  ui_story_5075_50750601_70_dialog_content = "Em seguida, algumas intérpretes da Emp. Dragão se revezarão no palco, cada uma apresentando sua própria versão de Emp. Dragão Sobre Mares Turbulentos.",
  ui_story_5075_50750601_71_dialog_content = "Todos vocês têm a chance de escolher a melhor intérprete Donzela Dragão do Festival da Primavera deste ano. O que vocês acham?",
  ui_story_5075_50750601_72_dialog_content = "Excelente!",
  ui_story_5075_50750601_73_dialog_content = "É uma sorte você ter trazido um amigo, PlayerName, ou não teríamos pessoas suficientes.",
  ui_story_5075_50750601_74_dialog_content = "Seu amigo vai jogar Black Dragon, um encrenqueiro intimidador do mar.",
  ui_story_5075_50750601_75_dialog_content = "Eu sou a Donzela Dragão.",
  ui_story_5075_50750601_76_dialog_content = "E quanto a mim?",
  ui_story_5075_50750601_77_dialog_content = "Esteja pronto, PlayerName, porque você tem a parte mais importante.",
  ui_story_5075_50750601_78_dialog_content = "<size=50>Você será o mar!</size>",
  ui_story_5075_50750601_79_dialog_content = "Isso é necessário?",
  ui_story_5075_50750601_80_dialog_content = "O que você está dizendo? O mar é muito importante.",
  ui_story_5075_50750601_81_dialog_content = "Lá está a música. Comece a dançar.",
  ui_story_5075_50750601_82_dialog_content = "Ahh—",
  ui_story_5075_50750601_83_dialog_content = "\"Abençoada pelo destino, a Donzela do Dragão traz boas novas ao descer sobre o mundo.\"",
  ui_story_5075_50750601_84_dialog_content = "\"As ondas do vasto oceano são obscuras, como se estivessem envoltas em fumaça.\"",
  ui_story_5075_50750601_85_dialog_content = "(Ok, mostre o quão vasto e obscuro você é, mar.)",
  ui_story_5075_50750601_86_dialog_content = "(Piscar para mim não muda nada! D-De qualquer forma, acho que é melhor eu causar algumas ondas.)",
  ui_story_5075_50750601_87_dialog_content = "\"Abençoada seja a Donzela do Dragão...\"",
  ui_story_5075_50750601_88_dialog_content = "...",
  ui_story_5075_50750601_89_dialog_content = "(Oh não... Não me diga que você esqueceu suas falas!)",
  ui_story_5075_50750601_90_dialog_content = "\"Inúmeras bênçãos para todos\"! Essa é a próxima parte!",
  ui_story_5075_50750601_91_dialog_content = "(Não adianta—ela já perdeu. Claramente não podemos esperar que Chen'ni lembre suas falas...)",
  ui_story_5075_50750601_92_dialog_content = "\"Quando o dragão maligno chega, tanto o sol quanto a lua perdem sua luz.\"",
  ui_story_5075_50750601_93_dialog_content = "(Luo Song?)",
  ui_story_5075_50750601_94_dialog_content = "\"O trovão ruge e o relâmpago ilumina.\"",
  ui_story_5075_50750601_95_dialog_content = "(Seus movimentos são rígidos e as linhas estão claramente erradas, mas ele está fazendo! Bom trabalho!)",
  ui_story_5075_50750601_96_dialog_content = "(Espera, por que ele não está se movendo?)",
  ui_story_5075_50750601_97_dialog_content = "(Apresse-se! Trovão e relâmpago!)",
  ui_story_5075_50750601_98_dialog_content = "(Isso também é meu trabalho?)",
  ui_story_5075_50750601_99_dialog_content = "(Seja como for, hora de fazer um pouco de trovão.)",
  ui_story_5075_50750601_100_dialog_content = "Estrondo!",
  ui_story_5075_50750601_101_dialog_content = "\"As pessoas assistem impotentes enquanto espíritos malignos rugem e se enfurecem!\"",
  ui_story_5075_50750601_102_dialog_content = "\"Mas logo, a Donzela Dragão aparece e os livra da destruição.\"",
  ui_story_5075_50750601_103_dialog_content = "\"Com força ilimitada e determinação inabalável,\"",
  ui_story_5075_50750601_104_dialog_content = "\"Ela soca os demônios e os manda voando em todas as direções!\"",
  ui_story_5075_50750601_105_dialog_content = "(Então agora a Dama do Dragão usa seus punhos para lutar?)",
  ui_story_5075_50750601_106_dialog_content = "(Além disso, você deveria ser um dragão malvado! Suas falas não poderiam estar mais confusas!)",
  ui_story_5075_50750601_107_dialog_content = "*Rugido*",
  ui_story_5075_50750601_108_dialog_content = "(De toda a bagunça nesta peça desastrosa, por que você tem que fazer um Eclipsite tão real?)",
  ui_story_5075_50750601_109_dialog_content = "(Espere um minuto!)",
  ui_story_5075_50750601_110_dialog_content = "Este é um verdadeiro Eclipsite!",
  ui_story_5075_50750602_1_dialog_content = "Obrigado a todos por trazerem algo assim...",
  ui_story_5075_50750602_2_dialog_content = "Únicas... interpretações criativas da... Donzela Dragão Sobre Mares Turbulentos.",
  ui_story_5075_50750602_3_dialog_content = "O líder do grupo parece tão derrotado. Devemos ter feito um trabalho realmente terrível.",
  ui_story_5075_50750602_4_dialog_content = "Acho que o ataque do espírito maligno causou o maior dano, sinceramente.",
  ui_story_5075_50750602_5_dialog_content = "Eu pensei que os Eclipsitas de Longzhou raramente apareciam nas cidades?",
  ui_story_5075_50750602_6_dialog_content = "Fiendlings enlouquecidos, uma névoa negra inexplicável e agora também Eclipsitas.",
  ui_story_5075_50750602_7_dialog_content = "Que diabos está acontecendo na cidade de Haojin?",
  ui_story_5075_50750602_8_dialog_content = "Por que vocês dois parecem tão preocupados?",
  ui_story_5075_50750602_9_dialog_content = "Achei que nos saímos bem, até lidamos com o espírito maligno.",
  ui_story_5075_50750602_10_dialog_content = "Especialmente da parte de PlayerName. Eu amo isso!",
  ui_story_5075_50750602_11_dialog_content = "Se você pudesse chamar aquilo de uma performance...",
  ui_story_5075_50750602_12_dialog_content = "Eu não acho que a segunda metade da história tenha algo a ver com a Donzela do Dragão Sobre Mares Turbulentos.",
  ui_story_5075_50750602_13_dialog_content = "Foi assim que a história me foi contada.",
  ui_story_5075_50750602_14_dialog_content = "Oito séculos atrás, o mundo foi assolado por um maléfico dragão negro.",
  ui_story_5075_50750602_15_dialog_content = "Mas um dia, a Donzela Dragão apareceu. Do topo das ondas do oceano, ela derrubou o dragão maligno com seus punhos.",
  ui_story_5075_50750602_16_dialog_content = "Cada soco tinha uma força inimaginável. O dragão cambaleou em choque enquanto o vento de seus punhos o empurrava quilômetros e quilômetros de distância.",
  ui_story_5075_50750602_17_dialog_content = "Antes que pudesse reagir, a Donzela Dragão atacou o dragão com uma saraivada de socos, batendo nele até ficar irreconhecível!",
  ui_story_5075_50750602_18_dialog_content = "Legal! E depois? E depois?",
  ui_story_5075_50750602_19_dialog_content = "Um som alto e zumbido ecoou nos ouvidos do dragão enquanto a raiva se acumulava em seu coração, e ele ferozmente—",
  ui_story_5075_50750602_20_dialog_content = "Bem, acredito que você saiba o que aconteceu em seguida melhor do que ninguém. Afinal de contas—",
  ui_story_5075_50750602_21_dialog_content = "Você é a própria Chen'ni, a Todo-Poderosa Divindade Benevolente do Dragão, não é?",
  ui_story_5075_50750602_22_dialog_content = "Espere um minuto... Depois de ouvir o que Li Tianxian disse sobre demônios, eu não deveria estar surpreso que Chen'ni é uma divindade de algum tipo.",
  ui_story_5075_50750602_23_dialog_content = "Mas essa Chen'ni que temos aqui é a Donzela do Dragão?",
  ui_story_5075_50750602_24_dialog_content = "De fato, sou eu.",
  ui_story_5075_50750602_25_dialog_content = "Sinto-me honrado por estar em sua presença, a Todo-Poderosa Divindade Benevolente do Dragão!",
  ui_story_5075_50750602_26_dialog_content = "Isso não demorou muito!",
  ui_story_5075_50750602_27_dialog_content = "Uma divindade genuína, um ser iluminado, está bem diante de nós. É apenas apropriado que mostremos nossa reverência.",
  ui_story_5075_50750602_28_dialog_content = "Senhora Chen'ni, há algum motivo para sua aparição em Haojin?",
  ui_story_5075_50750602_29_dialog_content = "Alguém quebrou o selo e perturbou meu sono. Estou aqui pela justiça.",
  ui_story_5075_50750602_30_dialog_content = "I-Isso soa como um desastre!",
  ui_story_5075_50750602_31_dialog_content = "Então a aparição de espíritos malignos e demônios agitados é porque o selo do dragão maligno foi quebrado?",
  ui_story_5075_50750602_32_dialog_content = "Então o dragão preto também é real, hein?",
  ui_story_5075_50750602_33_dialog_content = "Isso mesmo, mesmo que existam tantas versões diferentes da Donzela Dragão Sobre Mares Turbulentos, todas são baseadas em um evento histórico real.",
  ui_story_5075_50750602_34_dialog_content = "É por isso que as partes mais importantes da história são na maioria das vezes as mesmas.",
  ui_story_5075_50750602_35_dialog_content = "O dragão maligno causando estragos no mundo, a Donzela do Dragão selando-o no fundo do mar, e as pessoas conhecendo a paz mais uma vez.",
  ui_story_5075_50750602_36_dialog_content = "Mas o evento da história aconteceu há mais de oitocentos anos.",
  ui_story_5075_50750602_37_dialog_content = "Como o dragão preto ainda pode estar vivo depois de todo esse tempo?",
  ui_story_5075_50750602_38_dialog_content = "O dragão preto está morto há muito tempo. Isso não é uma preocupação.",
  ui_story_5075_50750602_39_dialog_content = "Mas o que aconteceu naquela época não foi culpa dos meus parentes.",
  ui_story_5075_50750602_40_dialog_content = "Há um abismo profundo no fundo do mar onde um poderoso demônio foi enterrado junto com seu rancor avassalador.",
  ui_story_5075_50750602_41_dialog_content = "Meu companheiro encontrou por acaso e foi dominado pelo rancor, daí o tumulto no mar.",
  ui_story_5075_50750602_42_dialog_content = "Apesar do selo ter sido removido, meu poder permanece. Embora a mágoa também tenha sido liberada, ela não pode prejudicar o mundo sem um recipiente físico.",
  ui_story_5075_50750602_43_dialog_content = "Mesmo que possua um novo corpo, ainda não pode se mover livremente até estar totalmente aclimatado.",
  ui_story_5075_50750602_44_dialog_content = "(Então a coisa que eu senti brevemente antes era o demônio poderoso?)",
  ui_story_5075_50750602_45_dialog_content = "(Isso não parece certo... Mas eu não dei uma boa olhada nisso. Felizmente, ainda temos tempo de acordo com Chen'ni.)",
  ui_story_5075_50750602_46_dialog_content = "Não importa como você olhe para isso, Chen'ni tem o mesmo objetivo que nós.",
  ui_story_5075_50750602_47_dialog_content = "Se estamos trabalhando juntos por enquanto, posso fazer uma pequena pergunta?",
  ui_story_5075_50750602_48_dialog_content = "Sim.",
  ui_story_5075_50750602_49_dialog_content = "Acredito que a primeira vez que nos encontramos foi no Templo da Donzela Dragão.",
  ui_story_5075_50750602_50_dialog_content = "Mas se você é a própria Donzela do Dragão, então... por que estava roubando suas próprias oferendas?",
  ui_story_5075_50750602_51_dialog_content = "... Isso não foi roubo.",
  ui_story_5075_50750602_52_dialog_content = "Eu estava pegando presentes destinados a mim. Como isso poderia ser roubo? Humph!",
  ui_story_5075_50750602_53_dialog_content = "Haha, foi mal. Você estava apenas aceitando suas ofertas, não roubando-as.",
  ui_story_5075_50750602_54_dialog_content = "Acho que estou apenas acostumado a te ver assim.",
  ui_story_5075_50750602_55_dialog_content = "De qualquer forma, tenho quase certeza de que esses acessórios dourados pertencem a você, Chen'ni?",
  ui_story_5075_50750602_56_dialog_content = "Encontrei um desses no Templo da Donzela do Dragão, e o outro me foi dado por Li Tianxian... quer dizer, um vendedor de figuras de açúcar. Ele queria devolvê-lo para você.",
  ui_story_5075_50750602_57_dialog_content = "Eu só vou levar um de volta.",
  ui_story_5075_50750602_58_dialog_content = "Já que você encontrou o outro no meu templo, PlayerName, você pode ficar com ele.",
  ui_story_5075_50750602_59_dialog_content = "Caso tenha alguma necessidade no futuro, concederei um desejo seu através dela.",
  ui_story_5075_50750602_60_dialog_content = "Um desejo...",
  ui_story_5075_50750602_61_dialog_content = "Desculpe pela interrupção, pessoal.",
  ui_story_5075_50750602_62_dialog_content = "Oi, olá. Desculpe pelo que aconteceu mais cedo.",
  ui_story_5075_50750602_63_dialog_content = "Não, eu que deveria estar agradecendo a você. Não há outro dano além do palco quebrado.",
  ui_story_5075_50750602_64_dialog_content = "Embora a competição tenha que terminar assim, e não possamos distribuir prêmios, ainda assim, por favor, aceite isso.",
  ui_story_5075_50750602_65_dialog_content = "É um lanche caseiro, não tão sofisticado quanto os que são vendidos por aí.",
  ui_story_5075_50750602_66_dialog_content = "Mas é feito com uma receita secreta passada na minha família, não disponível em outro lugar. Vá em frente e experimente.",
  ui_story_5075_50750602_67_dialog_content = "É isso!",
  ui_story_5075_50750602_68_dialog_content = "Inscrevi-me no concurso porque senti o cheiro. Vejo que na verdade não é o prêmio.",
  ui_story_5075_50750602_69_dialog_content = "Você fez tudo isso por um lanche?",
  ui_story_5075_50750602_70_dialog_content = "Não-não.",
  ui_story_5075_50750602_71_dialog_content = "Sim, este é o sabor. Você fez do mesmo jeito que seu avô fazia!",
  ui_story_5075_50750602_72_dialog_content = "Bem, acho que posso chamar minha justa turnê de um estrondoso sucesso.",
  ui_story_5075_50750602_73_dialog_content = "Vamos.",
  ui_story_5075_50750602_74_dialog_content = "É exatamente como o que meu avô fazia... Ele morreu anos atrás, porém, e nunca vendemos algo assim.",
  ui_story_5075_50750602_75_dialog_content = "Espere um segundo...!!!",
  ui_story_5075_50750602_76_dialog_content = "Dê uma mordida também, PlayerName, Luo Song e Ah Ding.",
  ui_story_5075_50750602_77_dialog_content = "Este lanche é simplesmente fantástico. Pena que só a família dele consegue fazer.",
  ui_story_5075_50750602_78_dialog_content = "*Rugido*",
  ui_story_5075_50750602_79_dialog_content = "Obrigado, Senhora Chen'ni!",
  ui_story_5075_50750602_80_dialog_content = "Nós já saímos antes, então apenas me chame de Chen'ni.",
  ui_story_5075_50750602_81_dialog_content = "Seu desejo é uma ordem!",
  ui_story_5075_50750602_82_dialog_content = "Como é que você não está comendo, PlayerName?",
  ui_story_5075_50750602_83_dialog_content = "Isso está realmente bem?",
  ui_story_5075_50750602_84_dialog_content = "Como assim?",
  ui_story_5075_50750602_85_dialog_content = "O líder do grupo é descendente de alguém que você costumava conhecer, certo?",
  ui_story_5075_50750602_86_dialog_content = "Você não tem mais nada para dizer a ele?",
  ui_story_5075_50750602_87_dialog_content = "Bom...",
  ui_story_5075_50750602_88_dialog_content = "Sou um dragão, um grande demônio e uma divindade do mar para todos. Ao contrário das pessoas normais, posso viver muito, muito tempo.",
  ui_story_5075_50750602_89_dialog_content = "Então eu tenho a oportunidade de conhecer muitas, muitas pessoas.",
  ui_story_5075_50750602_90_dialog_content = "Esse líder de trupe é o neto de alguém que costumava me alimentar com lanches o tempo todo.",
  ui_story_5075_50750602_91_dialog_content = "A rua do lado leste é onde a neta de um cara que remava barcos comigo vai se casar.",
  ui_story_5075_50750602_92_dialog_content = "Um beco na extremidade sul do rio é onde o jovem sobrinho do homem que sempre me vencia no cricket está sendo enterrado.",
  ui_story_5075_50750602_93_dialog_content = "O garoto também acontece de ser seu último parente de sangue neste mundo.",
  ui_story_5075_50750602_94_dialog_content = "A vida é muito curta para todos, então eles apressam tudo.",
  ui_story_5075_50750602_95_dialog_content = "Então eles sempre sentem a necessidade de provar seus laços com rituais ou cerimônias.",
  ui_story_5075_50750602_96_dialog_content = "Se eu tiver que conhecer seus descendentes só porque encontrei alguém...",
  ui_story_5075_50750602_97_dialog_content = "Eu passaria todo o meu tempo indo e vindo entre cerimônias.",
  ui_story_5075_50750602_98_dialog_content = "Mas você não se sente sozinho assim?",
  ui_story_5075_50750602_99_dialog_content = "Por causa da sua longevidade, você sempre é o que tem que dizer adeus aos seus amigos.",
  ui_story_5075_50750602_100_dialog_content = "Não, acho que está bom assim.",
  ui_story_5075_50750602_101_dialog_content = "Você também deveria se sentir sortudo, PlayerName.",
  ui_story_5075_50750602_102_dialog_content = "Porque você passa a me conhecer, que vou viver por muito, muito tempo, e eu vou me lembrar de você.",
  ui_story_5075_50750602_103_dialog_content = "Mesmo que você morra, você ainda estará nas minhas memórias, ficando comigo para sempre.",
  ui_story_5075_50750602_104_dialog_content = "(Eu sempre meio que entendo o que ela quer dizer, mas nunca entendo completamente.)",
  ui_story_5075_50750602_105_dialog_content = "(Seja o sorriso alegre no rosto dela, ou os sentimentos que ela expressa.)",
  ui_story_5075_50750602_106_dialog_content = "(Naquele momento, eu de repente entendo—nós realmente não somos iguais.)",
  ui_story_5075_50750701_1_dialog_content = "Nós. Somos. Diferentes.",
  ui_story_5075_50750701_2_dialog_content = "Então.",
  ui_story_5075_50750701_3_dialog_content = "Nós. Somos. Incompatíveis.",
  ui_story_5075_50750701_4_dialog_content = "Ugh...",
  ui_story_5075_50750701_5_dialog_content = "Você está bem? Precisa de uma pausa?",
  ui_story_5075_50750701_6_dialog_content = "Você tem sentido a névoa negra todo esse tempo. Tem certeza de que pode continuar?",
  ui_story_5075_50750701_7_dialog_content = "Claro que posso. Não sou tão fraco assim.",
  ui_story_5075_50750701_8_dialog_content = "Além disso, quanto mais sinto essa névoa negra, mais percebo que ela não é muito diferente do Darkflow.",
  ui_story_5075_50750701_9_dialog_content = "As maiores diferenças são suas propriedades infecciosas e corruptoras, que tornam difícil dissipá-lo usando nossos métodos usuais para combater o Darkflow.",
  ui_story_5075_50750701_10_dialog_content = "Se Chen'ni estiver certa, e a causa raiz dessas propriedades for um rancor, então pode possuir alguma forma de consciência.",
  ui_story_5075_50750701_11_dialog_content = "Se for assim, eu deveria ser capaz de usar meus poderes para interrompê-lo!",
  ui_story_5075_50750701_12_dialog_content = "Depois de algumas tentativas, percebi que poderia usar minhas habilidades psíquicas para isolar o poder corruptor da névoa negra.",
  ui_story_5075_50750701_13_dialog_content = "Se eu continuar praticando, talvez até consiga ajudar os demônios que já foram corrompidos.",
  ui_story_5075_50750701_14_dialog_content = "Na verdade, está tudo bem em deixar tudo comigo.",
  ui_story_5075_50750701_15_dialog_content = "Isso não vai dar. Estamos trabalhando juntos agora, o que significa que eu não posso simplesmente deixar você fazer todo o trabalho.",
  ui_story_5075_50750701_16_dialog_content = "Então, deixarei o trabalho delicado em suas mãos. Se algo exigir um toque mais pesado, meus punhos estão sempre à altura da tarefa!",
  ui_story_5075_50750701_17_dialog_content = "Rugido—",
  ui_story_5075_50750701_18_dialog_content = "O mesmo vale para Ah Ding!",
  ui_story_5075_50750701_19_dialog_content = "*Rugido*",
  ui_story_5075_50750701_20_dialog_content = "Rangido!",
  ui_story_5075_50750701_21_dialog_content = "Não é o mesmo diabinho de antes? O que ele está fazendo aqui?",
  ui_story_5075_50750701_22_dialog_content = "Eu não pedi para você dizer a ele para procurar seus amigos, Ah Ding?",
  ui_story_5075_50750701_23_dialog_content = "Rugido...",
  ui_story_5075_50750701_24_dialog_content = "Não queria ouvir, né?",
  ui_story_5075_50750701_25_dialog_content = "Enquanto eu estava praticando com minhas habilidades psíquicas, notei que ele nos seguia à distância todo esse tempo.",
  ui_story_5075_50750701_26_dialog_content = "Talvez esteja apenas com medo? Ele pode achar que é mais seguro ficar conosco depois de ter sido corrompido.",
  ui_story_5075_50750701_27_dialog_content = "Eu dificilmente consideraria estar ao nosso lado uma escolha segura. Afinal, nós vamos...",
  ui_story_5075_50750701_28_dialog_content = "Espere, esqueci de perguntar para onde estamos indo?",
  ui_story_5075_50750701_29_dialog_content = "Rua Yulin.",
  ui_story_5075_50750701_30_dialog_content = "De onde está vindo essa vibração nojenta.",
  ui_story_5075_50750701_31_dialog_content = "Hã?",
  ui_story_5075_50750701_32_dialog_content = "Isso significa que nossos destinos são realmente diferentes?",
  ui_story_5075_50750701_33_dialog_content = "?",
  ui_story_5075_50750701_34_dialog_content = "Eu não acho. Se fosse esse o caso, teríamos enfrentado problemas há muito tempo.",
  ui_story_5075_50750701_35_dialog_content = "Provavelmente isso não importa.",
  ui_story_5075_50750701_36_dialog_content = "De qualquer forma, estamos no destino de PlayerName.",
  ui_story_5075_50750701_37_dialog_content = "Estou vendo coisas? Por que cada loja parece ainda mais luxuosa que a última?",
  ui_story_5075_50750701_38_dialog_content = "Então esta é a Rua Yulin... Não é tão animada quanto a feira, mas ainda é realmente impressionante.",
  ui_story_5075_50750701_39_dialog_content = "Eu sei. É aqui que todas as pessoas ricas moram.",
  ui_story_5075_50750701_40_dialog_content = "<color=#e8d9bb>O rio claro corta toda a rua, ladeado por prédios altos. Mesmo no inverno, eles são decorados com flores vibrantes de várias cores.</color>",
  ui_story_5075_50750701_41_dialog_content = "<color=#e8d9bb>Fitas coloridas flutuam entre os prédios, e quando o vento sopra, desencadeia um coro de sinos prateados a tinir.</color>",
  ui_story_5075_50750701_42_dialog_content = "<color=#e8d9bb>Em torres altas e baixas, três mil donzelas dançam, sua beleza resplandece. De leste a oeste, nas águas que concedem, navios carregados de ouro em fila incessante.</color>",
  ui_story_5075_50750701_43_dialog_content = "O que é aquela estátua ao lado da rua?",
  ui_story_5075_50750701_44_dialog_content = "Um cardume de peixes cercando um barco. Há algo familiar sobre o barco e as caudas desses peixes...",
  ui_story_5075_50750701_45_dialog_content = "Onde eu já vi isso antes?",
  ui_story_5075_50750701_46_dialog_content = "São peixes-serpente. Eles sempre nadam para frente e para trás em escolas.",
  ui_story_5075_50750701_47_dialog_content = "Mas não importa o quão longe eles vão, eles retornarão à costa de Longzhou para botar ovos no inverno.",
  ui_story_5075_50750701_48_dialog_content = "Então, muitos marinheiros implorariam a eles para guiar seus navios.",
  ui_story_5075_50750701_49_dialog_content = "Pedindo ajuda aos peixes?",
  ui_story_5075_50750701_50_dialog_content = "Claro. As pessoas sempre fazem oferendas para animais ou demônios em busca de ajuda.",
  ui_story_5075_50750701_51_dialog_content = "Não tem sido assim desde os tempos antigos?",
  ui_story_5075_50750701_52_dialog_content = "Isso não parece ser o caso, pelo menos não agora...",
  ui_story_5075_50750701_53_dialog_content = "Esta estátua deve ter muitos anos agora, e está coberta de arranhões e sujeira. Acho que ninguém cuidou dela por muito tempo.",
  ui_story_5075_50750701_54_dialog_content = "Mesmo que eles estivessem em bons termos antes, receio que esse tempo...",
  ui_story_5075_50750701_55_dialog_content = "Esse tempo já acabou há muito tempo.",
  ui_story_5075_50750701_56_dialog_content = "Yuebai! Você finalmente voltou para Haojin.",
  ui_story_5075_50750701_57_dialog_content = "Retornei há alguns dias, mas assuntos urgentes com a família Lin me impediram de vê-lo antes.",
  ui_story_5075_50750701_58_dialog_content = "Então é uma boa coisa que nos encontramos aqui!",
  ui_story_5075_50750701_59_dialog_content = "Que tipo de problema a Família Lin está lidando agora?",
  ui_story_5075_50750701_60_dialog_content = "Eu não chamaria exatamente isso de um problema.",
  ui_story_5075_50750701_61_dialog_content = "É mais um erro.",
  ui_story_5075_50750701_62_dialog_content = "Um erro cometido pela Família Lin em relação ao peixe-serpente.",
  ui_story_5075_50750701_63_dialog_content = "É por isso que você disse: \"Aquele tempo já acabou há muito tempo\"?",
  ui_story_5075_50750701_64_dialog_content = "Sim.",
  ui_story_5075_50750701_65_dialog_content = "Por favor, evite tocar na minha cauda.",
  ui_story_5075_50750701_66_dialog_content = "M-Mas eu não toquei na sua cauda!",
  ui_story_5075_50750701_67_dialog_content = "Eu não estava falando sobre você, PlayerName.",
  ui_story_5075_50750701_68_dialog_content = "Opa, parte culpada.",
  ui_story_5075_50750701_69_dialog_content = "Raramente vejo um Auroriano com herança de peixe-serpente, então simplesmente não pude me conter.",
  ui_story_5075_50750701_70_dialog_content = "Dada a teoria de que os peixes-serpente e os dragões são parentes distantes, nós estamos na verdade de certa forma relacionados.",
  ui_story_5075_50750701_71_dialog_content = "Então, é minha honra.",
  ui_story_5075_50750701_72_dialog_content = "Não é à toa que eu achei que esses peixes pareciam familiares. Eles me lembraram de você, Yuebai.",
  ui_story_5075_50750701_73_dialog_content = "E, após uma olhada mais de perto, este barco parece exatamente com o Shadowind!",
  ui_story_5075_50750701_74_dialog_content = "Isso é porque é uma versão inicial dele.",
  ui_story_5075_50750701_75_dialog_content = "Foi também o primeiro dos navios da Família Lin a cruzar o mar e chegar a Astra muitos anos atrás.",
  ui_story_5075_50750701_76_dialog_content = "Entendo. Mas o que uma escultura de um navio da família Lin está fazendo aqui?",
  ui_story_5075_50750701_77_dialog_content = "Você não sabe?",
  ui_story_5075_50750701_78_dialog_content = "Esta rua de compras já pertenceu à Família Lin.",
  ui_story_5075_50750701_79_dialog_content = "Th-A rua inteira?",
  ui_story_5075_50750701_80_dialog_content = "Infelizmente, devido a uma série de negócios recentes, bem como ao último incidente da Família Lin, grande parte da rua foi dividida.",
  ui_story_5075_50750701_81_dialog_content = "Neste momento, apenas metade da rua ainda está sob o nome da Família Lin.",
  ui_story_5075_50750701_82_dialog_content = "Quanto ao destino final desta metade restante, tudo depende de como as coisas progridem.",
  ui_story_5075_50750701_83_dialog_content = "Metade de uma rua inteira ainda é bastante impressionante, sabe.",
  ui_story_5075_50750701_84_dialog_content = "Rangido!",
  ui_story_5075_50750701_85_dialog_content = "Ai!",
  ui_story_5075_50750701_86_dialog_content = "<color=#e8d9bb>Enquanto você é derrubado de repente pelo demônio saltador, um Fluxo Escuro negro como breu atinge o chão bem ao lado de seus pés.</color>",
  ui_story_5075_50750701_87_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5075_50750701_88_dialog_content = "PlayerName! Você está bem?",
  ui_story_5075_50750701_89_dialog_content = "Estou bem. Aquele pequeno demônio me salvou agora mesmo.",
  ui_story_5075_50750701_90_dialog_content = "Rangido...",
  ui_story_5075_50750701_91_dialog_content = "O que há de errado com ele? Parece estar com muita dor.",
  ui_story_5075_50750701_92_dialog_content = "... Espere, quando foi que ele se infectou com a névoa negra de novo?",
  ui_story_5075_50750701_93_dialog_content = "Ah Ding?",
  ui_story_5075_50750701_94_dialog_content = "Rugido...",
  ui_story_5075_50750701_95_dialog_content = "<color=#e8d9bb>Ah Ding solta um rosnado baixo e doloroso, e a Lumina anteriormente estável ao seu redor começa a flutuar.</color>",
  ui_story_5075_50750701_96_dialog_content = "Não me diga que esses sintomas são...",
  ui_story_5075_50750701_97_dialog_content = "Aumento de Força!",
  ui_story_5075_50750701_98_dialog_content = "Consegui isolar o poder corruptor da névoa por enquanto, mas precisamos encontrar sua fonte o mais rápido possível.",
  ui_story_5075_50750701_99_dialog_content = "De onde veio essa gigante nuvem de névoa negra?",
  ui_story_5075_50750701_100_dialog_content = "Estou procurando quem quebrou o selo, não você. Fique tranquilo e não se deixe levar pelo nariz.",
  ui_story_5075_50750701_101_dialog_content = "Hã? Com quem você está falando, Chen'ni?",
  ui_story_5075_50750701_102_dialog_content = "O peixe.",
  ui_story_5075_50750701_103_dialog_content = "O peixe... Você quer dizer a estátua?",
  ui_story_5075_50750701_104_dialog_content = "Varredura Psíquica!",
  ui_story_5075_50750701_105_dialog_content = "Isto é embaixo do mar?",
  ui_story_5075_50750701_106_dialog_content = "Quem. Vai. Lá.",
  ui_story_5075_50750701_107_dialog_content = "Uma cauda de peixe-serpente?",
  ui_story_5075_50750701_108_dialog_content = "Você é parente da Família Lin?",
  ui_story_5075_50750701_109_dialog_content = "Os. Lins.",
  ui_story_5075_50750701_110_dialog_content = "Des—prezível.",
  ui_story_5075_50750701_111_dialog_content = "De—testável!",
  ui_story_5075_50750701_112_dialog_content = "!",
  ui_story_5075_50750701_113_dialog_content = "Tá doendo...",
  ui_story_5075_50750701_114_dialog_content = "Mantenha-se forte, PlayerName.",
  ui_story_5075_50750701_115_dialog_content = "Estou bem. O poder corruptor da névoa negra era apenas muito mais forte no lugar que eu senti.",
  ui_story_5075_50750701_116_dialog_content = "Eu vi outra pessoa lá também. Ele parecia... estar de alguma forma ligado à família Lin.",
  ui_story_5075_50750701_117_dialog_content = "É Yoh.",
  ui_story_5075_50750701_118_dialog_content = "Você o conhece, Yuebai?",
  ui_story_5075_50750701_119_dialog_content = "Yoh é um demônio que já foi um aliado da Família Lin.",
  ui_story_5075_50750701_120_dialog_content = "Não muito tempo atrás, o mestre da guilda o enviou em uma missão para a costa marítima. Ele estava investigando a razão por trás dos movimentos estranhos dos espíritos malignos, mas ele nunca retornou.",
  ui_story_5075_50750701_121_dialog_content = "... Ele deve ter se tornado o \"vaso físico\" que Chen'ni mencionou anteriormente! Parece que o pior cenário aconteceu afinal.",
  ui_story_5075_50750701_122_dialog_content = "O poder que foi selado encontrou um novo hospedeiro.",
  ui_story_5075_50750701_123_dialog_content = "Rangido!",
  ui_story_5075_50750701_124_dialog_content = "<color=#e8d9bb>O pequeno diabólico salta de repente e morde com força o pulso de um estranho no canto.</color>",
  ui_story_5075_50750701_125_dialog_content = "Urgh... Maldita criatura!",
  ui_story_5075_50750701_126_dialog_content = "Desapareça!",
  ui_story_5075_50750701_127_dialog_content = "<color=#e8d9bb>O pequeno demônio é jogado à força para o lado, deslizando longe no chão, imóvel.</color>",
  ui_story_5075_50750701_128_dialog_content = "Essa não!",
  ui_story_5075_50750701_129_dialog_content = "Humph.",
  ui_story_5075_50750701_130_dialog_content = "Aquele homem... Seu corpo também está coberto pela névoa preta! O que ele está segurando nos braços?",
  ui_story_5075_50750701_131_dialog_content = "Quem é você!",
  ui_story_5075_50750701_132_dialog_content = "Você não precisa saber.",
  ui_story_5075_50750701_133_dialog_content = "Isso não é bom! Alguém o detenha!",
  ui_story_5075_50750701_134_dialog_content = "É tarde demais!",
  ui_story_5075_50750701_135_dialog_content = "<color=#e8d9bb>O estranho estilhaça o objeto que segura no chão e libera uma enorme névoa negra.</color>",
  ui_story_5075_50750701_136_dialog_content = "(É exatamente como o poder que senti no oceano!)",
  ui_story_5075_50750701_137_dialog_content = "<color=#e8d9bb>Desta vez, você pode ver sem mesmo tentar usar suas habilidades psíquicas.</color>",
  ui_story_5075_50750701_138_dialog_content = "<color=#e8d9bb>Desta vez, você pode ver sem sequer tentar usar suas habilidades psíquicas.</color>",
  ui_story_5075_50750701_139_dialog_content = "<color=#e8d9bb>Uma névoa negra sem fim carrega um intenso Fluxo Escuro, fervendo e crescendo como água aquecida.</color>",
  ui_story_5075_50750701_140_dialog_content = "<color=#e8d9bb>Todos esses fluxos instáveis de energia convergem em um só, e então...</color>",
  ui_story_5075_50750701_141_dialog_content = "<color=#e8d9bb>Eles explodem de repente!</color>",
  ui_story_5075_50750701_142_dialog_content = "Não, você não precisa!",
  ui_story_5075_50750701_143_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_5075_50750701_144_dialog_content = "<color=#e8d9bb>Uma figura dourada salta com um raio e bloqueia as marés escuras da detonação, mas a névoa restante ainda se dispersa.</color>",
  ui_story_5075_50750701_145_dialog_content = "Vocês são os que quebraram o selo? Venham pagar pelo seu erro!",
  ui_story_5075_50750701_146_dialog_content = "*tosse*",
  ui_story_5075_50750701_147_dialog_content = "O que está acontecendo? Onde está a Chen'ni?",
  ui_story_5075_50750701_148_dialog_content = "Depois que entramos na névoa negra, ela saiu correndo atrás dele.",
  ui_story_5075_50750701_149_dialog_content = "Isso é muito imprudente!",
  ui_story_5075_50750701_150_dialog_content = "Felizmente, eu não acho que alguém possa realmente machucá-la.",
  ui_story_5075_50750701_151_dialog_content = "Mas não somos nada como ela. Não parece que nenhum de nós tenha se machucado, no entanto.",
  ui_story_5075_50750701_152_dialog_content = "Não nos machucamos... Mas Ah Ding e o outro pequeno se machucaram!",
  ui_story_5075_50750701_153_dialog_content = "Rugido...",
  ui_story_5075_50750701_154_dialog_content = "A explosão de agora há pouco fez a névoa negra voar em todas as direções. A corrupção deles parece estar se intensificando também.",
  ui_story_5075_50750701_155_dialog_content = "Não só isso, parece que a névoa também está atraindo os Eclipsitas.",
  ui_story_5075_50750701_156_dialog_content = "Prepare-se para a batalha!",
  ui_story_5075_50750701_157_dialog_content = "Graah!",
  ui_story_5075_50750702_1_dialog_content = "Não vou deixar vocês, espíritos malignos, profanarem o local ancestral da Família Lin!",
  ui_story_5075_50750702_2_dialog_content = "Graah—",
  ui_story_5075_50750702_3_dialog_content = "Que bom que você está aqui para eliminar esses Eclipsitas, Yuebai.",
  ui_story_5075_50750702_4_dialog_content = "Mas a névoa parece ter se espalhado por toda a cidade. Estou preocupado que algo realmente ruim esteja prestes a acontecer.",
  ui_story_5075_50750702_5_dialog_content = "Não há nada que possamos fazer sobre isso?",
  ui_story_5075_50750702_6_dialog_content = "Há.",
  ui_story_5075_50750702_7_dialog_content = "A situação pode estar muito pior do que antes, mas a Família Lin ainda tem planos de contingência em vigor.",
  ui_story_5075_50750702_8_dialog_content = "Assumirei a responsabilidade de escoltar todos com segurança até a propriedade da família Lin.",
  ui_story_5075_50750702_9_dialog_content = "Depois, vou convencer o Guildmaster a alocar seus recursos na cidade para ajudar com este assunto.",
  ui_story_5075_50750702_10_dialog_content = "Parece bom para mim! Mas você não está curioso para saber o que está acontecendo antes de nos ajudar, Yuebai?",
  ui_story_5075_50750702_11_dialog_content = "O assunto está intimamente relacionado com a Família Lin...",
  ui_story_5075_50750702_12_dialog_content = "Além disso, eu não preciso de um motivo para ajudar um amigo como você.",
  ui_story_5075_50750702_13_dialog_content = "Espere, PlayerName.",
  ui_story_5075_50750702_14_dialog_content = "O que é, Luo Song?",
  ui_story_5075_50750702_15_dialog_content = "Posso deixar este pequeno diabinho aos seus cuidados por enquanto?",
  ui_story_5075_50750702_16_dialog_content = "Claro. Não vamos esquecer o Ah Ding também.",
  ui_story_5075_50750702_17_dialog_content = "Chen'ni ainda não retornou, então tudo que posso fazer é tentar isolar a corrupção da névoa negra.",
  ui_story_5075_50750702_18_dialog_content = "Rugido...",
  ui_story_5075_50750702_19_dialog_content = "Ah Ding?",
  ui_story_5075_50750702_20_dialog_content = "É aqui que nos separamos.",
  ui_story_5075_50750702_21_dialog_content = "Você também, Luo Song?",
  ui_story_5075_50750702_22_dialog_content = "Com a névoa negra se espalhando por Haojin, certamente haverá ainda mais demônios infectados.",
  ui_story_5075_50750702_23_dialog_content = "Eles não são ruins, estão apenas seguindo seus instintos. Afinal, ainda são espíritos animais nascidos na natureza selvagem.",
  ui_story_5075_50750702_24_dialog_content = "Como está, as opiniões das pessoas em relação aos demônios estão apenas piorando.",
  ui_story_5075_50750702_25_dialog_content = "Se alguém se machucar por causa de um demônio como resultado da infecção da névoa negra, receio que o relacionamento entre nós será irreparável.",
  ui_story_5075_50750702_26_dialog_content = "É por isso que preciso subjugar os demônios infectados antes que seja tarde demais.",
  ui_story_5075_50750702_27_dialog_content = "É verdade que tivemos nossas diferenças com os demônios.",
  ui_story_5075_50750702_28_dialog_content = "Mas isso não dá a ninguém o direito de decidir seu lugar no mundo ou seu destino, aliás.",
  ui_story_5075_50750702_29_dialog_content = "Não é mesmo, Ah Ding?",
  ui_story_5075_50750702_30_dialog_content = "Eu te elogio quando você faz o bem, e te repreendo quando você faz o mal.",
  ui_story_5075_50750702_31_dialog_content = "Mas no final, a escolha de fazer qualquer coisa é sempre sua.",
  ui_story_5075_50750702_32_dialog_content = "Você quer vir comigo?",
  ui_story_5075_50750702_33_dialog_content = "<color=#e8d9bb>Luo Song se inclina, olhando para Ah Ding.</color>",
  ui_story_5075_50750702_34_dialog_content = "<color=#e8d9bb>Ah Ding, de cara no chão, se levanta e cambaleia até ficar de pé.</color>",
  ui_story_5075_50750702_35_dialog_content = "*Rugido*",
  ui_story_5075_50750702_36_dialog_content = "Esse é o meu parceiro para você.",
  ui_story_5075_50750702_37_dialog_content = "Mas Ah Ding não está em condições de...",
  ui_story_5075_50750702_38_dialog_content = "Ah, se ao menos a Donzela Dragão estivesse aqui.",
  ui_story_5075_50750702_39_dialog_content = "Você está pedindo um pouco demais, você não acha?",
  ui_story_5075_50750702_40_dialog_content = "As divindades não aparecem diante de nós só porque pedimos, sabe?",
  ui_story_5075_50750702_41_dialog_content = "Sua família te repreenderia por pedir ajuda o tempo todo, e com as divindades não é diferente.",
  ui_story_5075_50750702_42_dialog_content = "Sim, você tem razão.",
  ui_story_5075_50750702_43_dialog_content = "Para dizer a verdade, adoração e oração não são nada mais do que pensamento positivo.",
  ui_story_5075_50750702_44_dialog_content = "Se as divindades escolhem intervir, é porque têm suas próprias razões para fazê-lo.",
  ui_story_5075_50750702_45_dialog_content = "Mas aqui no reino mortal, nossos punhos são nosso método mais confiável de alcançar nossos objetivos!",
  ui_story_5075_50750702_46_dialog_content = "Não importa quão difícil seja o caminho, sempre podemos seguir em frente, desde que ainda tenhamos força em nossos punhos.",
  ui_story_5075_50750702_47_dialog_content = "*Rugido*",
  ui_story_5075_50750702_48_dialog_content = "Hora de irmos!",
  ui_story_5075_50750702_49_dialog_content = "Boa sorte, vocês dois.",
  ui_story_5075_50750702_50_dialog_content = "Devemos ir também.",
  ui_story_5075_50750702_51_dialog_content = "Venha, eu vou te levar até a propriedade da família Lin.",
  ui_story_5075_50750801_1_dialog_content = "<color=#e8d9bb>Palácio Real do Reino Ji</color>",
  ui_story_5075_50750801_2_dialog_content = "Meu Senhor, há notícias do Reino Ye novamente.",
  ui_story_5075_50750801_3_dialog_content = "Sobre os <color=#FFB400>canhões costeiros</color> que encomendamos do Reino Ye? Eles já chegaram?",
  ui_story_5075_50750801_4_dialog_content = "Não... ainda não...",
  ui_story_5075_50750801_5_dialog_content = "Não? Eles não começaram a enviar depois de aumentar o preço da última vez?",
  ui_story_5075_50750801_6_dialog_content = "A mensagem do Reino diz isso.",
  ui_story_5075_50750801_7_dialog_content = "Mas já se passou meio mês e as mercadorias ainda não chegaram. Enviamos cartas instando-os, mas do lado deles...",
  ui_story_5075_50750801_8_dialog_content = "Deixe-me adivinhar, eles estão aumentando o preço de novo?",
  ui_story_5075_50750801_9_dialog_content = "... Sim.",
  ui_story_5075_50750801_10_dialog_content = "A carta diz que a equipe de entrega desapareceu nas montanhas.",
  ui_story_5075_50750801_11_dialog_content = "E considerando que são algo que nosso Reino Ji precisa urgentemente, eles podem ceder algumas pessoas para nos ajudar na busca.",
  ui_story_5075_50750801_12_dialog_content = "Mas precisamos cobrir os custos da busca.",
  ui_story_5075_50750801_13_dialog_content = "Claro, eles propõem que esse custo possa ser compensado pelo empréstimo que o Reino Ye nos pediu há cinco anos atrás.",
  ui_story_5075_50750801_14_dialog_content = "Então, acho que eles estão apenas usando isso como desculpa para aumentar o preço.",
  ui_story_5075_50750801_15_dialog_content = "Se não concordarmos em pagar, eles continuarão alegando que os canhões costeiros estão perdidos.",
  ui_story_5075_50750801_16_dialog_content = "E a busca pode continuar... para sempre.",
  ui_story_5075_50750801_17_dialog_content = "Ridículo!",
  ui_story_5075_50750801_18_dialog_content = "Fizemos o pedido assim que os espíritos malignos começaram a agir, mas foi adiado novamente e novamente.",
  ui_story_5075_50750801_19_dialog_content = "É a equipe de entrega que está desaparecendo desta vez. Qual será a próxima desculpa deles? Canhões desaparecendo misteriosamente no ar?",
  ui_story_5075_50750801_20_dialog_content = "Na resposta, deixe claro que se eles tentarem se aproveitar, todas as transações entre nossos reinos serão canceladas!",
  ui_story_5075_50750801_21_dialog_content = "Mas, meu Senhor, espíritos malignos têm estado à solta por toda parte ultimamente.",
  ui_story_5075_50750801_22_dialog_content = "Especialmente ao longo da costa, todas as regiões estão buscando apoio do palácio.",
  ui_story_5075_50750801_23_dialog_content = "Se os canhões costeiros do Reino Ye não chegarem logo, pode ser difícil manter a linha de defesa por mais tempo.",
  ui_story_5075_50750801_24_dialog_content = "Difícil manter a linha de defesa?",
  ui_story_5075_50750801_25_dialog_content = "O Reino Ye é o único fornecedor restante em Longzhou?",
  ui_story_5075_50750801_26_dialog_content = "Nosso Reino de Ji prospera com abundância de mercadorias e bandos de comerciantes, e os lucros diários são incalculáveis.",
  ui_story_5075_50750801_27_dialog_content = "Se o transporte marítimo está desafiador agora, podemos recorrer ao transporte fluvial. Como o Reino Ye se recusa a fazer comércio justo, procuraremos outra pessoa.",
  ui_story_5075_50750801_28_dialog_content = "O dinheiro torna tudo possível. Desde que o preço seja justo, até as poderosas forças de Yangjing estarão ao meu comando.",
  ui_story_5075_50750801_29_dialog_content = "E quanto às exigências do Reino Ye?",
  ui_story_5075_50750801_30_dialog_content = "Rejeite todos eles.",
  ui_story_5075_50750801_31_dialog_content = "Sim, meu Senhor.",
  ui_story_5075_50750801_32_dialog_content = "Humph, agora até mesmo o Reino Ye se atreve a brincar comigo.",
  ui_story_5075_50750801_33_dialog_content = "Eles podem ter convenientemente esquecido o constrangimento quando imploraram por um empréstimo do nosso Reino Ji anos atrás.",
  ui_story_5075_50750801_34_dialog_content = "Falando nisso, aquele ano também foi quando Zhuohua veio para o Reino Ji.",
  ui_story_5075_50750801_35_dialog_content = "Conselheiro Chefe, o que você acha? Se Zhuohua realmente se tornar minha nora, esse dinheiro pode ser negociável.",
  ui_story_5075_50750801_36_dialog_content = "Meu Senhor, não brinque. Zhuohua é uma mulher aspirante e determinada. Este assunto não é brincadeira.",
  ui_story_5075_50750801_37_dialog_content = "Humph, estou bem ciente disso.",
  ui_story_5075_50750801_38_dialog_content = "É apenas raro encontrar alguém que possa manter o príncipe herdeiro tão bem comportado...",
  ui_story_5075_50750801_39_dialog_content = "Não vamos nos ater a questões triviais de crianças. Meu Senhor, você já considerou uma estratégia para a atual situação turbulenta?",
  ui_story_5075_50750801_40_dialog_content = "Ao longo dos anos, nosso Reino de Ji tem dado grande ênfase ao comércio. Necessidades como comida e maquinário dependem todos do comércio com outros reinos.",
  ui_story_5075_50750801_41_dialog_content = "Se houver mais situações como o incidente de hoje com o Reino Ye...",
  ui_story_5075_50750801_42_dialog_content = "O Reino de Ji tem sido centrado no comércio por séculos. Elaborar uma nova estratégia não é uma tarefa fácil.",
  ui_story_5075_50750801_43_dialog_content = "Além disso, a ameaça dos espíritos malignos pode não durar.",
  ui_story_5075_50750801_44_dialog_content = "Vamos falar sobre isso outro dia.",
  ui_story_5075_50750801_45_dialog_content = "Estou cansado. Vou voltar para descansar agora.",
  ui_story_5075_50750801_46_dialog_content = "... Entendido.",
  ui_story_5075_50750801_47_dialog_content = "Senhor? Você está aqui.",
  ui_story_5075_50750801_48_dialog_content = "Ouvi dizer que os espíritos malignos na baía aumentaram em poder, e o caso do demônio ainda é um mistério.",
  ui_story_5075_50750801_49_dialog_content = "Além disso, após nos separarmos no palácio, não tive notícias de PlayerName desde então!",
  ui_story_5075_50750801_50_dialog_content = "Que insight você pode me dar, senhor?",
  ui_story_5075_50750801_51_dialog_content = "Não se preocupe. Esse jovem está seguro e saudável, e as tarefas atribuídas a ele estão indo bem.",
  ui_story_5075_50750801_52_dialog_content = "Mas eu imagino que há mais coisas que você deseja perguntar, certo?",
  ui_story_5075_50750801_53_dialog_content = "Não vou fazer rodeios e serei direto com você então.",
  ui_story_5075_50750801_54_dialog_content = "Você aconselhou PlayerName a permanecer oculto e não alertar ninguém no tribunal.",
  ui_story_5075_50750801_55_dialog_content = "Foi porque você suspeitou de possível jogo sujo ou malícia?",
  ui_story_5075_50750801_56_dialog_content = "Para a sua pergunta, em vez de me perguntar, por que não verificar com o seu guarda?",
  ui_story_5075_50750801_57_dialog_content = "<color=#FFB400>Jiu</color>? Ela está em...",
  ui_story_5075_50750801_58_dialog_content = "Não precisa me dizer. Sou um velhote e não consigo entender os jogos de vocês, jovens moças.",
  ui_story_5075_50750801_59_dialog_content = "Veja por si mesmos.",
  ui_story_5075_50750801_60_dialog_content = "... Entendi. Obrigado pela instrução.",
  ui_story_5075_50750801_61_dialog_content = "Ah, aqui está mais uma coisa. Permita-me pedir desculpas a você.",
  ui_story_5075_50750801_62_dialog_content = "Quando você ver o jovem mais tarde, por favor, transmita minhas desculpas a ele também.",
  ui_story_5075_50750801_63_dialog_content = "Mais cedo, passei algo para o garoto em seu nome.",
  ui_story_5075_50750801_64_dialog_content = "Espero que se prove útil no devido tempo.",
  ui_story_5075_50750801_65_dialog_content = "(Ele é realmente muito cauteloso com alguém no tribunal.)",
  ui_story_5075_50750801_66_dialog_content = "(Mas quem poderia ser para deixá-lo tão cauteloso?)",
  ui_story_5075_50750801_67_dialog_content = "(Eu me pergunto se tem algo a ver com o caso que Jiu está investigando...)",
  ui_story_5075_50750801_68_dialog_content = "(Falando nisso, por que o palácio está quieto em relação à espionagem na cidade?)",
  ui_story_5075_50750801_69_dialog_content = "(Somente Jiu conseguiu descobrir? Ou, alguém deixou ela descobrir intencionalmente?)",
  ui_story_5075_50750801_70_dialog_content = "(Mas ela é apenas uma guarda para uma princesa refém, e ela está fazendo isso apenas por mim.)",
  ui_story_5075_50750801_71_dialog_content = "(Não é necessário que ninguém no tribunal faça isso, mesmo que tenham segundas intenções, a menos que...)",
  ui_story_5075_50750801_72_dialog_content = "(O mentor por trás do enredo não está trabalhando para o Reino Ji, mas...)",
  ui_story_5075_50750801_73_dialog_content = "Bip.",
  ui_story_5075_50750801_74_dialog_content = "Um pássaro mensageiro da <color=#FFB400>Ministra Armilla</color>?",
  ui_story_5075_50750801_75_dialog_content = "Ela citou que eles não funcionavam bem o suficiente para evitar os guardas como a razão pela qual ela nunca me enviou nada.",
  ui_story_5075_50750801_76_dialog_content = "Eu sabia que era apenas uma desculpa.",
  ui_story_5075_50750801_77_dialog_content = "...",
  ui_story_5075_50750801_78_dialog_content = "Que audácia da sua parte, Xuan Ji!",
  ui_story_5075_50750801_79_dialog_content = "Eu preciso sair do palácio agora.",
  ui_story_5075_50750801_80_dialog_content = "Conselheiro Chefe, conforme suas instruções, removemos os guardas dos arredores.",
  ui_story_5075_50750801_81_dialog_content = "A princesa Zhuohua também recebeu a carta.",
  ui_story_5075_50750801_82_dialog_content = "Ótimo.",
  ui_story_5075_50750902_1_dialog_content = "Aqui estamos. Bem-vindo à propriedade da Família Lin na Rua Yulin.",
  ui_story_5075_50750902_2_dialog_content = "Hã? Não é este o mesmo endereço que estava escrito naquele bilhete?",
  ui_story_5075_50750902_3_dialog_content = "Nota?",
  ui_story_5075_50750902_4_dialog_content = "Recebi uma caixa de comida do palácio mais cedo hoje, e continha um pequeno mapa com este endereço marcado nele.",
  ui_story_5075_50750902_5_dialog_content = "Também veio com esta insígnia, mas não tenho certeza do que devo fazer com ela.",
  ui_story_5075_50750902_6_dialog_content = "Isto é... uma insígnia do Escritório de Inspeção.",
  ui_story_5075_50750902_7_dialog_content = "Jovem, você sabia que além da marinha, o Reino de Ji não mantém nenhum exército regular em terra?",
  ui_story_5075_50750902_8_dialog_content = "Proteger rotas vitais, investigar traições e eliminar espíritos malignos - tudo isso está sob a responsabilidade do Escritório de Inspeção.",
  ui_story_5075_50750902_9_dialog_content = "E a insígnia em sua mão permite que você mobilize as forças do Escritório de Inspeção.",
  ui_story_5075_50750902_10_dialog_content = "Além da guarda do palácio real, o que você está segurando é o comando da força mais poderosa em Haojin.",
  ui_story_5075_50750902_11_dialog_content = "Você quer dizer que eu estive carregando algo tão importante todo esse tempo?",
  ui_story_5075_50750902_12_dialog_content = "Hã? Espere, quem é você?",
  ui_story_5075_50750902_13_dialog_content = "Guildmaster, não há necessidade de você sair para nos cumprimentar.",
  ui_story_5075_50750902_14_dialog_content = "Ouvi alguma perturbação lá fora, então saí para ver o que estava acontecendo.",
  ui_story_5075_50750902_15_dialog_content = "Não esperava que você tivesse convidados.",
  ui_story_5075_50750902_16_dialog_content = "Você deve ser PlayerName, certo?",
  ui_story_5075_50750902_17_dialog_content = "Já ouvi falar muito de você através de Zhong Xu, Liqing e Yuebai. É minha sorte finalmente conhecê-lo hoje.",
  ui_story_5075_50750902_18_dialog_content = "Mas agora não é hora para conversinha.",
  ui_story_5075_50750902_19_dialog_content = "Jovem, pode me dizer por que você pareceu tão surpreso quando me viu?",
  ui_story_5075_50750902_20_dialog_content = "Ah, desculpe por isso. Ainda assim, sinto que já te vi em algum lugar antes.",
  ui_story_5075_50750902_21_dialog_content = "Acho que estava no fundo do oceano... nas memórias do demônio que está controlando a névoa negra.",
  ui_story_5075_50750902_22_dialog_content = "É Yoh?",
  ui_story_5075_50750902_23_dialog_content = "Acredito que sim.",
  ui_story_5075_50750902_24_dialog_content = "Então você está ciente de Yoh e seu rancor contra a família Lin. O que exatamente aconteceu entre vocês?",
  ui_story_5075_50750902_25_dialog_content = "É uma longa história.",
  ui_story_5075_50750902_26_dialog_content = "Vamos conversar lá dentro.",
  ui_story_5075_50750902_27_dialog_content = "Tenho alguns assuntos para tratar. Yuebai, por favor, entretenha nosso convidado por enquanto.",
  ui_story_5075_50750902_28_dialog_content = "Muito bem.",
  ui_story_5075_50750902_29_dialog_content = "Gostaria de um chá?",
  ui_story_5075_50750902_30_dialog_content = "Ah, não, obrigado.",
  ui_story_5075_50750902_31_dialog_content = "Entendido. Talvez outra hora.",
  ui_story_5075_50750902_32_dialog_content = "Hahaha... Quase me esqueci do seu jeito usual de fazer as coisas.",
  ui_story_5075_50750902_33_dialog_content = "?",
  ui_story_5075_50750902_34_dialog_content = "Não é nada. Eu apenas acho que não precisamos mais dessas formalidades enfadonhas.",
  ui_story_5075_50750902_35_dialog_content = "Vamos ao que interessa. Qual é a história entre Yoh e os Lins?",
  ui_story_5075_50750902_36_dialog_content = "Veja, a história compartilhada entre a Família Lin e os demônios remonta a um passado distante.",
  ui_story_5075_50750902_37_dialog_content = "Na época, a Família Lin era apenas uma pequena guilda, que estava à beira da falência devido a anos de negócios ruins.",
  ui_story_5075_50750902_38_dialog_content = "Em um ato final de desespero, o mestre da guilda trocou a riqueza restante da família por um navio mercante, na esperança de encontrar um meio melhor de sobreviver através do mar.",
  ui_story_5075_50750902_39_dialog_content = "Não é necessário dizer, ele teve sucesso.",
  ui_story_5075_50750902_40_dialog_content = "Esse foi o início das negociações comerciais da Família Lin com Astra.",
  ui_story_5075_50750902_41_dialog_content = "Lembro-me de Carleen me contando essa história. Twin Pavilions Bay também começou a prosperar naquela época.",
  ui_story_5075_50750902_42_dialog_content = "Então, parece que você sabe o resto.",
  ui_story_5075_50750902_43_dialog_content = "Mais importante para a nossa situação atual, no entanto, é o que aconteceu depois. Na sua viagem de volta para Longzhou, o navio do mestre da guilda acidentalmente navegou para águas calmas.",
  ui_story_5075_50750902_44_dialog_content = "A Família Lin não tinha esferas armilares na época, nem tinham artesãos habilidosos como Xuan Ji para resgatá-los.",
  ui_story_5075_50750902_45_dialog_content = "O mestre da guilda e sua tripulação passaram uma quinzena à deriva no mar, e eles chegaram perigosamente perto de esgotar seus estoques de comida.",
  ui_story_5075_50750902_46_dialog_content = "Foi quando eles encontraram um cardume de peixes-serpente.",
  ui_story_5075_50750902_47_dialog_content = "Chen'ni disse que o peixe-serpente retorna a Longzhou em grandes cardumes todos os invernos para depositar seus ovos.",
  ui_story_5075_50750902_48_dialog_content = "Então o peixe-serpente resgatou o mestre da guilda?",
  ui_story_5075_50750902_49_dialog_content = "Exatamente.",
  ui_story_5075_50750902_50_dialog_content = "Eles seguiram o cardume de peixes-serpente, que viram como um bom presságio, e isso os levou para fora das águas calmas e de volta às margens de Longzhou.",
  ui_story_5075_50750902_51_dialog_content = "Por esse motivo, ele só fretava viagens de retorno de Astra nos meses de inverno.",
  ui_story_5075_50750902_52_dialog_content = "Em troca de ofertas generosas de comida, o peixe-serpente guiou os navios da Família Lin com segurança pelo mar.",
  ui_story_5075_50750902_53_dialog_content = "E assim o peixe-serpente se tornou uma espécie de totem para a Família Lin.",
  ui_story_5075_50750902_54_dialog_content = "Também é o homônimo de toda esta rua.",
  ui_story_5075_50750902_55_dialog_content = "Mas após a morte do antigo mestre da guilda, a Guilda Lin só cresceu em escala a cada geração que passava.",
  ui_story_5075_50750902_56_dialog_content = "Em breve, as crescentes demandas da guilda não poderiam ser atendidas com apenas uma única viagem de retorno no inverno.",
  ui_story_5075_50750902_57_dialog_content = "Nesse ponto, o mestre da guilda na época começou a pedir ao peixe-serpente cada vez mais escoltas pelo mar.",
  ui_story_5075_50750902_58_dialog_content = "Espere, ele negociou... com peixe?",
  ui_story_5075_50750902_59_dialog_content = "Mesmo eu estando bem na sua frente, você ainda não percebeu, não é?",
  ui_story_5075_50750902_60_dialog_content = "Naquela época, o líder do peixe-serpente era um <color=#FFB400>demônio</color>.",
  ui_story_5075_50750902_61_dialog_content = "A linhagem de peixe-serpente da Família Lin também começou naquela época.",
  ui_story_5075_50750902_62_dialog_content = "Mas, ao exigir mais escoltas dos peixes-serpentes sem considerar suas tendências naturais, a Família Lin falhou em honrar seu acordo original.",
  ui_story_5075_50750902_63_dialog_content = "Como resultado, os laços entre eles começaram a se deteriorar gradualmente.",
  ui_story_5075_50750902_64_dialog_content = "Em um determinado momento, um navio da família Lin até destruiu um habitat de peixe-serpente.",
  ui_story_5075_50750902_65_dialog_content = "Este incidente enfureceu o atual líder do peixe-serpente, e ele decidiu terminar completamente a cooperação com a Família Lin.",
  ui_story_5075_50750902_66_dialog_content = "Ainda me lembro de como o recém-transformado Yoh invadiu meu pátio e gritou o quanto me desprezava.",
  ui_story_5075_50750902_67_dialog_content = "Bem-vindo de volta, Guildmaster.",
  ui_story_5075_50750902_68_dialog_content = "Desculpe, você...",
  ui_story_5075_50750902_69_dialog_content = "Haha, eu ouvi o que você disse agora mesmo.",
  ui_story_5075_50750902_70_dialog_content = "Esse tipo de coisa deve ser difícil para um jovem como você aceitar.",
  ui_story_5075_50750902_71_dialog_content = "Não vou justificar as ações da Família Lin. O que nossos antecessores fizeram foi realmente infiel.",
  ui_story_5075_50750902_72_dialog_content = "No entanto, como empresário, estou bem ciente de que a Família Lin acabou se beneficiando disso, tornando-se a principal player no setor de negócios de Haojin.",
  ui_story_5075_50750902_73_dialog_content = "Se eu fosse o responsável por tomar as decisões naquela época, provavelmente teria feito a mesma coisa.",
  ui_story_5075_50750902_74_dialog_content = "Se não tivéssemos recebido informações sobre a esfera armilar antecipadamente, a família Lin não o teria libertado tão facilmente.",
  ui_story_5075_50750902_75_dialog_content = "Eles podem tê-lo mantido cativo, usando-o como um peão.",
  ui_story_5075_50750902_76_dialog_content = "Ele me odeia, odeia a família Lin, e com razão.",
  ui_story_5075_50750902_77_dialog_content = "Quebrar promessas e trair a confiança - de fato, a Família Lin cometeu tais atos no passado.",
  ui_story_5075_50750902_78_dialog_content = "Agora, a Família Lin está colhendo o que plantou.",
  ui_story_5075_50750902_79_dialog_content = "Espíritos malignos perambulam pelas áreas costeiras, mas o Reino de Ji ainda é incapaz de estabelecer uma linha de defesa estável.",
  ui_story_5075_50750902_80_dialog_content = "Os canhões costeiros que encomendamos do Reino Ye ainda não chegaram, pelo que ouvi.",
  ui_story_5075_50750902_81_dialog_content = "Os navios comerciais da família Lin há muito tempo não conseguem navegar, e os negócios costeiros estão estagnados. Quando chove, é sempre torrencial.",
  ui_story_5075_50750902_82_dialog_content = "Assim que me retirei dos Escritórios de Comércio Marítimo, fui descaradamente direto para Yoh, desconsiderando o bom senso de Zhong.",
  ui_story_5075_50750902_83_dialog_content = "Eu esperava que ele pudesse ajudar a família Lin a explorar as rotas aquáticas e proteger os navios comerciais. Claro, fui expulso.",
  ui_story_5075_50750902_84_dialog_content = "De acordo com PlayerName, ele foi investigar a situação no mar afinal de contas...",
  ui_story_5075_50750902_85_dialog_content = "Mas então ele foi corrompido pela influência do dragão maligno, fazendo com que ele perdesse o controle e infectasse todos os demônios próximos com seu rancor.",
  ui_story_5075_50750902_86_dialog_content = "... A Família Lin assume a responsabilidade por este incidente, e cabe a nós corrigi-lo.",
  ui_story_5075_50750902_87_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5075_50750902_88_dialog_content = "Expulse esses demônios!",
  ui_story_5075_50750902_89_dialog_content = "O que está acontecendo lá fora?",
  ui_story_5075_50751001_1_dialog_content = "<color=#e8d9bb>Luo Song enfrenta uma multidão de cidadãos furiosos no centro da rua, protegendo vários demônios inconscientes no chão.</color>",
  ui_story_5075_50751001_2_dialog_content = "Acalmem-se, todos! Esses demônios nunca tiveram a intenção de prejudicar ninguém!",
  ui_story_5075_50751001_3_dialog_content = "Eu já os subjuguei. Tudo o que resta é remover a corrupção de seus corpos e—",
  ui_story_5075_50751001_4_dialog_content = "<color=#e8d9bb>Pimba!</color>",
  ui_story_5075_50751001_5_dialog_content = "<color=#e8d9bb>Uma pedra voa da multidão, atingindo Luo Song.</color>",
  ui_story_5075_50751001_6_dialog_content = "*Rugido*",
  ui_story_5075_50751001_7_dialog_content = "Ah Ding! Você também precisa se acalmar!",
  ui_story_5075_50751001_8_dialog_content = "Estou bem, eu prometo. Não podemos nos dar ao luxo de lutar com eles, não agora.",
  ui_story_5075_50751001_9_dialog_content = "As pessoas já estão feridas. Quem se importa se eles tinham a intenção ou não!",
  ui_story_5075_50751001_10_dialog_content = "Eu te disse que esses demônios não prestam! Roubar coisas é uma coisa, mas agora eles estão matando pessoas!",
  ui_story_5075_50751001_11_dialog_content = "Haojin tem sido pacífica por séculos, mas hoje há até espíritos malignos na cidade!",
  ui_story_5075_50751001_12_dialog_content = "E você ainda afirma que não são os demônios causando problemas? Eles são obviamente iguais! Igualmente maléficos!",
  ui_story_5075_50751001_13_dialog_content = "Vocês conhecem a magia, então é fácil para vocês conversarem sem sentir medo.",
  ui_story_5075_50751001_14_dialog_content = "Você não tem medo deles, mas nós temos!",
  ui_story_5075_50751001_15_dialog_content = "Não podemos deixar essas coisas sinistras permanecerem na cidade. Expulse todos eles!",
  ui_story_5075_50751001_16_dialog_content = "Expulse-os! EXPULSE-OS!",
  ui_story_5075_50751001_17_dialog_content = "Eu tenho que ajudá-lo—",
  ui_story_5075_50751001_18_dialog_content = "Espere. Se você sair lá fora despreparado, só vai piorar as coisas.",
  ui_story_5075_50751001_19_dialog_content = "Uma multidão enfurecida não vai ouvir a razão, não importa se está certa ou errada.",
  ui_story_5075_50751001_20_dialog_content = "Além de uma demonstração de força ainda mais poderosa, a única maneira de acalmá-los é oferecendo-lhes uma garantia inegável de que as coisas vão melhorar.",
  ui_story_5075_50751001_21_dialog_content = "Eu tenho essa insígnia! Isso não significa que posso chamar o Escritório de Inspeção para nos ajudar?",
  ui_story_5075_50751001_22_dialog_content = "O Escritório de Inspeção deve estar lidando com os Eclipsitas espalhados pela cidade neste exato momento.",
  ui_story_5075_50751001_23_dialog_content = "Além disso, se eles interviessem... Tenho medo que essas pessoas só ficariam mais agitadas.",
  ui_story_5075_50751001_24_dialog_content = "Mas tem que haver algo que possamos fazer...",
  ui_story_5075_50751001_25_dialog_content = "Eu já disse que tem, não disse? Mais especificamente, a Família Lin tem uma solução.",
  ui_story_5075_50751001_26_dialog_content = "Guildmaster, eu tenho um favor para lhe pedir.",
  ui_story_5075_50751001_27_dialog_content = "Eu solicito formalmente a autoridade para <color=#FFB400>agir em nome do Lin Guildmaster</color> de Haojin.",
  ui_story_5075_50751001_28_dialog_content = "Por favor, conceda-me o direito de alocar as pessoas e recursos da Família Lin para resolver este incidente.",
  ui_story_5075_50751001_29_dialog_content = "Qual é o seu plano?",
  ui_story_5075_50751001_30_dialog_content = "Apesar da diminuição da proeminência da Guilda Lin nos últimos anos, o fato permanece que ainda somos uma organização de longa data com laços estreitos com as pessoas.",
  ui_story_5075_50751001_31_dialog_content = "Desejo oferecer às pessoas desta cidade uma promessa de segurança em nome da guilda e enviar nossos médicos para tratar os feridos.",
  ui_story_5075_50751001_32_dialog_content = "Você entende o que está em jogo com suas palavras ditas casualmente?",
  ui_story_5075_50751001_33_dialog_content = "Sim, a Família Lin possui uma riqueza considerável, mas não a ponto de podermos assumir o bem-estar de toda a população de uma cidade.",
  ui_story_5075_50751001_34_dialog_content = "Além disso, a Família Lin esteve envolvida em um caso de contrabando antes, e levou muito esforço para limpar nosso nome.",
  ui_story_5075_50751001_35_dialog_content = "O mundo dos negócios é como um campo de batalha - é aceitável jogar sujo nos bastidores, mas nossa imagem pública precisa permanecer limpa.",
  ui_story_5075_50751001_36_dialog_content = "Você está usando o nome da Família Lin para garantir os demônios. Qualquer erro, e a Família Lin se tornará um alvo público.",
  ui_story_5075_50751001_37_dialog_content = "Estou bem ciente disso.",
  ui_story_5075_50751001_38_dialog_content = "Mas Yoh está por trás da ameaça demônio, e os Lins são a causa do rancor em primeiro lugar.",
  ui_story_5075_50751001_39_dialog_content = "Os Lins devem ser responsabilizados.",
  ui_story_5075_50751001_40_dialog_content = "Os tempos realmente mudaram.",
  ui_story_5075_50751001_41_dialog_content = "O Reino de Ji valoriza o comércio, e os comerciantes sempre priorizam os lucros.",
  ui_story_5075_50751001_42_dialog_content = "Quando eu era jovem, todos brigavam pelo menor ganho, cobiçando até mesmo uma tigela de arroz na mão de um mendigo.",
  ui_story_5075_50751001_43_dialog_content = "E os Lins até sacrificariam o peixe-serpente que eles tinham consagrado por gerações para servir aos seus interesses.",
  ui_story_5075_50751001_44_dialog_content = "Então agora você quer que eu arrisque tudo pelo que trabalhei duro apenas por causa de \"responsabilidade\"?",
  ui_story_5075_50751001_45_dialog_content = "Minhas palavras estão longe de serem vazias, Guildmaster. Eu sei que posso torná-las realidade.",
  ui_story_5075_50751001_46_dialog_content = "Esperem, vocês dois! Agora não é hora para discutir...",
  ui_story_5075_50751001_47_dialog_content = "Tenho um mantra para você aprender.",
  ui_story_5075_50751001_48_dialog_content = "Não importa quais problemas você encontre, apenas repita, e a maioria das coisas ficará bem.",
  ui_story_5075_50751001_49_dialog_content = "(Mesmo duvidando que vá ajudar, não saberei a menos que eu tente!)",
  ui_story_5075_50751001_50_dialog_content = "<color=#FFB400>Merry... <size=45>Merry Ano Novo!</size></color>",
  ui_story_5075_50751001_51_dialog_content = "...",
  ui_story_5075_50751001_52_dialog_content = "...",
  ui_story_5075_50751001_53_dialog_content = "Hahaha... É um ano novo.",
  ui_story_5075_50751001_54_dialog_content = "Diga adeus ao velho e dê as boas-vindas ao novo - hora de um novo começo.",
  ui_story_5075_50751001_55_dialog_content = "Depois de todas as preparações, o dia oficial do Festival da Primavera é amanhã, não é?",
  ui_story_5075_50751001_56_dialog_content = "De fato.",
  ui_story_5075_50751001_57_dialog_content = "Está tudo pronto? E o jantar de Ano Novo Eve?",
  ui_story_5075_50751001_58_dialog_content = "A maioria dos nossos ingredientes foi colocada em armazenamento frio, e vegetais frescos serão entregues a nós nesse dia.",
  ui_story_5075_50751001_59_dialog_content = "As contas da guilda foram acertadas há dois dias. Um resumo foi colocado em seu estudo para que você possa ler quando for conveniente.",
  ui_story_5075_50751001_60_dialog_content = "O negócio da nossa guilda sofreu novamente este ano, mas ainda assim achei adequado recompensar os guardas e trabalhadores com um adicional de dois meses de salários.",
  ui_story_5075_50751001_61_dialog_content = "Você certamente tem uma mente própria.",
  ui_story_5075_50751001_62_dialog_content = "Ao navegar pelo mar sempre caprichoso, um capitão deve responder de maneira rápida e decisiva.",
  ui_story_5075_50751001_63_dialog_content = "Um vento a favor ou uma corrente ascendente podem ser totalmente perdidos se eu não conseguir aproveitá-los a tempo.",
  ui_story_5075_50751001_64_dialog_content = "Você acha que o que estamos enfrentando agora é um vento a favor para a Família Lin?",
  ui_story_5075_50751001_65_dialog_content = "Se você tem certeza disso, eu concordo com o seu pedido.",
  ui_story_5075_50751001_66_dialog_content = "Graças a Deus... você está bem...",
  ui_story_5075_50751001_67_dialog_content = "<size=45>Eu não posso.</size>",
  ui_story_5075_50751001_68_dialog_content = "Ei—",
  ui_story_5075_50751001_69_dialog_content = "Eu sei muito bem que qualquer esquema ou cálculo pode ser instantaneamente levado embora por uma onda grande o suficiente.",
  ui_story_5075_50751001_70_dialog_content = "Quando isso acontecer, a única coisa que impedirá o navio de virar é uma quilha forte e estável.",
  ui_story_5075_50751001_71_dialog_content = "A espinha dorsal de um navio nunca deve dobrar ou quebrar.",
  ui_story_5075_50751001_72_dialog_content = "...",
  ui_story_5075_50751001_73_dialog_content = "Talvez sua avaliação sobre a situação atual esteja correta, mas eu continuo sendo um produto da era antiga.",
  ui_story_5075_50751001_74_dialog_content = "Do meu ponto de vista, suas ações são muito radicais e arriscadas.",
  ui_story_5075_50751001_75_dialog_content = "Guildmaster—",
  ui_story_5075_50751001_76_dialog_content = "No entanto, você é o capitão do Shadowind, responsável pelas rotas de navegação cruciais para a família Lin.",
  ui_story_5075_50751001_77_dialog_content = "Aos olhos dos outros, o que você diz representa toda a família Lin.",
  ui_story_5075_50751001_78_dialog_content = "Isso significa...",
  ui_story_5075_50751001_79_dialog_content = "Posso ser antiquado, mas acima de tudo, sou um homem de negócios que considera vários fatores e pesa prós e contras.",
  ui_story_5075_50751001_80_dialog_content = "Você é um capitão capaz de dominar os complexos navios modernos e certamente é livre para fazer o que quiser.",
  ui_story_5075_50751001_81_dialog_content = "Se você tiver sucesso, será um herói para a Lin Guild, e eu o colocarei no comando das rotas marítimas perto de Longzhou também.",
  ui_story_5075_50751001_82_dialog_content = "Se não der certo, você será alguém que violou o comando do mestre da guilda, agindo sem permissão.",
  ui_story_5075_50751001_83_dialog_content = "A família pode deserdar você em breve, e você pode até perder seu sobrenome.",
  ui_story_5075_50751001_84_dialog_content = "Você pode aceitar essas condições?",
  ui_story_5075_50751001_85_dialog_content = "<size=45>Eu aceito.</size>",
  ui_story_5075_50751001_86_dialog_content = "Vamos, PlayerName.",
  ui_story_5075_50751001_87_dialog_content = "Claro... Ah, mas só um segundo.",
  ui_story_5075_50751001_88_dialog_content = "Você pode guardar essa insígnia em segurança para mim por enquanto, Guildmaster?",
  ui_story_5075_50751001_89_dialog_content = "Você confiaria em mim com algo tão importante?",
  ui_story_5075_50751001_91_dialog_content = "Não se esqueça de que sou uma pessoa desonesta e sem escrúpulos.",
  ui_story_5075_50751001_92_dialog_content = "Haha... Estaria mentindo se dissesse que estou completamente tranquilo com essa decisão.",
  ui_story_5075_50751001_93_dialog_content = "Mas eu não vejo nenhuma oportunidade de usá-lo tão cedo, e o mapa que veio com ele também me apontou para o seu caminho.",
  ui_story_5075_50751001_94_dialog_content = "Você continua insistindo que não é confiável, mas Yuebai e Zhong Xu ainda acreditam em você.",
  ui_story_5075_50751001_95_dialog_content = "E eu confio no julgamento deles.",
  ui_story_5075_50751001_96_dialog_content = "Minhas habilidades psíquicas também me dizem que, mesmo que você tente fazer algo ruim com isso, alguém aqui vai te impedir.",
  ui_story_5075_50751001_97_dialog_content = "Bem, nesse caso, eu vou levar.",
  ui_story_5075_50751001_98_dialog_content = "Obrigado.",
  ui_story_5075_50751001_99_dialog_content = "Vamos lá, Yuebai, vamos—",
  ui_story_5075_50751001_100_dialog_content = "Haha, a geração mais jovem.",
  ui_story_5075_50751001_101_dialog_content = "Sempre se dirigindo a lugares arriscados, eles ainda são muito impulsivos. É difícil se sentir tranquilo sobre o futuro da Família Lin.",
  ui_story_5075_50751001_102_dialog_content = "Bem, sua expressão diz o contrário.",
  ui_story_5075_50751001_103_dialog_content = "Praticamente grita, \"Os Lins têm muitos sucessores esperando na reserva.\"",
  ui_story_5075_50751001_104_dialog_content = "Hahaha, Zhong Xu, você realmente tem olhos aguçados.",
  ui_story_5075_50751001_105_dialog_content = "Eu esperava resolver lentamente os problemas do passado e deixar tudo limpo para a próxima geração.",
  ui_story_5075_50751001_106_dialog_content = "Não esperava que ela estivesse um passo à frente de mim e que já tivesse assumido essa responsabilidade antes que eu pudesse intervir.",
  ui_story_5075_50751001_107_dialog_content = "Mas Zhong Xu, você esteve observando das sombras. Por que não dar uma mão?",
  ui_story_5075_50751001_108_dialog_content = "PlayerName já notou seu envolvimento.",
  ui_story_5075_50751001_109_dialog_content = "Então você fez.",
  ui_story_5075_50751001_110_dialog_content = "Nosso jovem amigo até trouxe o distintivo do Escritório de Inspeção aqui, mas você ainda se recusou a falar sobre seu acordo com o Conselheiro Chefe.",
  ui_story_5075_50751001_111_dialog_content = "É óbvio que você prometeu a ele que ajudaria. Assim que nosso jovem amigo chegou aqui, fui instado a mobilizar os guardas Lin.",
  ui_story_5075_50751001_112_dialog_content = "Então por que fazer esse teatro?",
  ui_story_5075_50751001_113_dialog_content = "A maneira como enrolamos, é difícil para nós, mais velhos, nos comunicarmos com os jovens.",
  ui_story_5075_50751001_114_dialog_content = "Apenas pense nisso como minha preparação para o Festival da Primavera, uma cerimônia de despedida do velho e boas-vindas ao novo.",
  ui_story_5075_50751001_115_dialog_content = "Viu? Ainda nem é o Festival da Primavera e já estamos ouvindo tantas palavras agradáveis.",
  ui_story_5075_50751001_116_dialog_content = "Isso é um bom presságio, não é?",
  ui_story_5075_50751001_117_dialog_content = "Pare de falar bobagens! Esse cara está defendendo o demônio. Ele definitivamente não é bom.",
  ui_story_5075_50751001_118_dialog_content = "Saia da frente agora e nos deixe expulsar esse ser maligno antes que seja tarde demais.",
  ui_story_5075_50751001_119_dialog_content = "Caso contrário, mesmo que você tenha magia, não seremos fáceis com você.",
  ui_story_5075_50751001_120_dialog_content = "Eu sei que todos vocês estão com medo, mas temos que ser razoáveis sobre isso—",
  ui_story_5075_50751001_121_dialog_content = "Expulse todos eles!",
  ui_story_5075_50751001_122_dialog_content = "Expulse-os!",
  ui_story_5075_50751001_123_dialog_content = "*Rugido*",
  ui_story_5075_50751001_124_dialog_content = "Isso é ruim. Não consegui reunir todos os pequenos demônios...",
  ui_story_5075_50751001_125_dialog_content = "Constrição da Serpente!",
  ui_story_5075_50751002_1_dialog_content = "<color=#e8d9bb>Mu Yuebai corta rapidamente o grupo de demônios como uma adaga afiada como uma navalha.</color>",
  ui_story_5075_50751002_2_dialog_content = "<color=#e8d9bb>O público mal tem tempo para reagir. O demônio que estava enfurecido há apenas um segundo já perdeu a consciência, desabando no chão.</color>",
  ui_story_5075_50751002_3_dialog_content = "Quem... Quem é aquele? Que incrível!",
  ui_story_5075_50751002_4_dialog_content = "Eu sei! Esse é o Capitão Mu da Guilda Lin.",
  ui_story_5075_50751002_5_dialog_content = "Mas a cauda dela... Ela tem sangue de demônio nela, não tem...",
  ui_story_5075_50751002_6_dialog_content = "Como você pode dizer isso? Ela acabou de nos salvar!",
  ui_story_5075_50751002_7_dialog_content = "Todos, por favor, ouçam o que eu tenho a dizer.",
  ui_story_5075_50751002_8_dialog_content = "Sei que hoje foi um dia aterrorizante. Alguns se feriram enquanto outros sofreram perdas.",
  ui_story_5075_50751002_9_dialog_content = "Eu compartilho das frustrações de todos.",
  ui_story_5075_50751002_10_dialog_content = "Mas esses demônios não são responsáveis pelos problemas que temos enfrentado. Eles são apenas marionetes de um culpado ainda mais sinistro.",
  ui_story_5075_50751002_11_dialog_content = "Ao lutar apenas contra os demônios, estamos caindo direto em suas armadilhas.",
  ui_story_5075_50751002_12_dialog_content = "Você compartilha a linhagem deles, e é por isso que você diria isso!",
  ui_story_5075_50751002_13_dialog_content = "Mas eu sou mais Auroriano do que peixe-serpente, isso sempre foi verdade. Além disso, a Família Lin faz negócios com pessoas, não com demônios.",
  ui_story_5075_50751002_14_dialog_content = "Por que eu prejudicaria as perspectivas da nossa guilda trabalhando contra você?",
  ui_story_5075_50751002_15_dialog_content = "...",
  ui_story_5075_50751002_16_dialog_content = "As palavras são frequentemente infundadas, e eu sei que não tenho o direito de pedir que você acredite nas minhas palavras.",
  ui_story_5075_50751002_17_dialog_content = "Mas, em nome da Guilda Lin, prometo fornecer a todos vocês evidências inegáveis da verdade por trás deste incidente.",
  ui_story_5075_50751002_18_dialog_content = "Não podemos nos permitir ser enganados e explorados pelo nosso inimigo. Fazer isso só permitirá que eles operem com total impunidade.",
  ui_story_5075_50751002_19_dialog_content = "Mesmo que você diga isso...",
  ui_story_5075_50751002_20_dialog_content = "(Eles ainda não estão totalmente convencidos, mas o que podemos oferecer como prova? ... Espere, eu entendi!)",
  ui_story_5075_50751002_21_dialog_content = "Aumento de Força!",
  ui_story_5075_50751002_22_dialog_content = "(Por favor, mesmo que seja apenas um pouco, deixe-me mostrar a todos o que eu vejo...)",
  ui_story_5075_50751002_23_dialog_content = "Todos! Por favor, deem uma olhada mais de perto nestes fiendlings!",
  ui_story_5075_50751002_24_dialog_content = "Que raios é isso?",
  ui_story_5075_50751002_25_dialog_content = "É isso que o verdadeiro culpado está usando para controlar esses demônios.",
  ui_story_5075_50751002_26_dialog_content = "Enquanto eles ainda estiverem infectados com esse poder, expulsar os fiendlings da cidade não mudará nada.",
  ui_story_5075_50751002_27_dialog_content = "Eles... na verdade não parecem estar mentindo.",
  ui_story_5075_50751002_28_dialog_content = "Os Lins realmente fizeram muito por todos ao longo dos anos, mas...",
  ui_story_5075_50751002_29_dialog_content = "<color=#e8d9bb>Eles se agrupam e, após uma breve discussão sussurrada, enviam um representante.</color>",
  ui_story_5075_50751002_30_dialog_content = "Tudo bem, vamos confiar em você por enquanto.",
  ui_story_5075_50751002_31_dialog_content = "Está ficando tarde e não queremos perder tempo aqui.",
  ui_story_5075_50751002_32_dialog_content = "Mas ainda há alguns demônios à espreita na cidade. Quem sabe o que eles podem fazer enquanto você está investigando?",
  ui_story_5075_50751002_33_dialog_content = "Então, temos uma condição.",
  ui_story_5075_50751002_34_dialog_content = "Você precisa resolver isso antes do Festival da Primavera, para que todos possamos aproveitar um bom feriado.",
  ui_story_5075_50751002_35_dialog_content = "Entendi.",
  ui_story_5075_50751002_36_dialog_content = "Isso mesmo! É o Ano Novo! Todos querem que esse problema seja resolvido o mais rápido possível!",
  ui_story_5075_50751002_37_dialog_content = "<color=#e8d9bb>Mu Yuebai envia pessoas para acalmar o público, que eventualmente se dispersa.</color>",
  ui_story_5075_50751002_38_dialog_content = "Obrigado pela sua ajuda.",
  ui_story_5075_50751002_39_dialog_content = "Enfrentar tantas pessoas sozinho teria sido realmente exaustivo.",
  ui_story_5075_50751002_40_dialog_content = "Quando você diz \"assumir\", você não quer dizer...",
  ui_story_5075_50751002_41_dialog_content = "Não se preocupe. O Festival da Primavera está a apenas um dia de distância, então é melhor nos apressarmos.",
  ui_story_5075_50751002_42_dialog_content = "Felizmente, conseguimos desenterrar muitas pistas.",
  ui_story_5075_50751002_43_dialog_content = "Para começar, alguém destruiu o selo de Chen'ni, permitindo que o poder do dragão negro surgisse do mar.",
  ui_story_5075_50751002_44_dialog_content = "Embora esse poder tenha uma série de propriedades únicas, no final do dia, ainda é apenas um tipo de Fluxo Escuro.",
  ui_story_5075_50751002_45_dialog_content = "Esse Darkflow, por sua vez, atraiu muitos Eclipsitas para as margens de Haojin, impedindo que os navios da Família Lin partissem e efetivamente parando seus negócios.",
  ui_story_5075_50751002_46_dialog_content = "Isso forçou o Mestre da Guilda Lin a procurar Yoh, o demônio com quem trabalhava, e pedir-lhe para encontrar o motivo da congregação dos Eclipsitas.",
  ui_story_5075_50751002_47_dialog_content = "Apenas para Yoh ser contaminado pela névoa escura durante a investigação e ficar com nada além de ódio pela Família Lin.",
  ui_story_5075_50751002_48_dialog_content = "E depois de adquirir um recipiente físico, a névoa negra se tornou ainda mais ativa e começou a afetar os demônios na área.",
  ui_story_5075_50751002_49_dialog_content = "Sua influência eventualmente se infiltrou na cidade de Haojin.",
  ui_story_5075_50751002_50_dialog_content = "Portanto, temos que encontrar Yoh primeiro e remover a corrupção dele.",
  ui_story_5075_50751002_51_dialog_content = "Depois disso, precisamos encontrar uma maneira de selar a névoa negra, assim como Chen'ni fez no passado.",
  ui_story_5075_50751002_52_dialog_content = "Então o que estamos esperando?",
  ui_story_5075_50751002_53_dialog_content = "Rangido!",
  ui_story_5075_50751002_54_dialog_content = "Guardião Flamejante Diabrete!",
  ui_story_5075_50751002_55_dialog_content = "Argh, a névoa negra se espalhou pela maior parte da cidade! Cada vez mais criaturas estão sucumbindo aos seus efeitos.",
  ui_story_5075_50751002_56_dialog_content = "Você deveria ficar aqui, Luo Song.",
  ui_story_5075_50751002_57_dialog_content = "Eles precisam da sua ajuda.",
  ui_story_5075_50751002_58_dialog_content = "Tudo bem. Mas antes de você ir, aqui—",
  ui_story_5075_50751002_59_dialog_content = "O que é isso?!",
  ui_story_5075_50751002_60_dialog_content = "Um soco de punho.",
  ui_story_5075_50751002_61_dialog_content = "Isso nos tornará amigos em uma luta comum.",
  ui_story_5075_50751002_62_dialog_content = "Quando você voltar, vou te oferecer algumas das castanhas d'água mais frescas do mundo.",
  ui_story_5075_50751002_63_dialog_content = "Vamos!",
  ui_story_5075_50751002_64_dialog_content = "Estou indo procurar mais demônios corrompidos. Faça o seu melhor lá fora!",
  ui_story_5075_50751002_65_dialog_content = "Eu vou! Agora para encontrar Yuebai... Hã?",
  ui_story_5075_50751002_66_dialog_content = "Excelência, finalmente conseguimos encontrá-lo novamente.",
  ui_story_5075_50751002_67_dialog_content = "Você realmente sabe como... andar por aí.",
  ui_story_5075_50751002_68_dialog_content = "É o mordomo... O-O que o traz aqui, senhor?",
  ui_story_5075_50751002_69_dialog_content = "Dado o aumento de seres malignos na cidade, é nosso dever garantir a sua segurança.",
  ui_story_5075_50751002_70_dialog_content = "Por favor, siga-nos de volta para a Casa de Hóspedes Real.",
  ui_story_5075_50751002_71_dialog_content = "Desculpe, mas não posso voltar agora. Ainda tenho algo importante para fazer.",
  ui_story_5075_50751002_72_dialog_content = "Por favor, não torne as coisas difíceis para nós. Você é um convidado distinto que veio de longe para o nosso Reino Ji.",
  ui_story_5075_50751002_73_dialog_content = "Se algo acontecer com você, podemos acabar perdendo nossas cabeças. Por favor, entenda nossa situação.",
  ui_story_5075_50751002_74_dialog_content = "Escolte o estimado emissário de volta à casa de hóspedes!",
  ui_story_5075_50751002_75_dialog_content = "Espere! Solte-me—",
  ui_story_5075_50751002_76_dialog_content = "Voltei, PlayerName.",
  ui_story_5075_50751002_77_dialog_content = "... PlayerName?",
  ui_story_5075_50751101_1_dialog_content = "Flores, Desabrochando Infinitamente!",
  ui_story_5075_50751101_2_dialog_content = "Hum...",
  ui_story_5075_50751101_3_dialog_content = "Todos vocês parecem ser assassinos habilidosos, mas nenhum de seus movimentos é letal.",
  ui_story_5075_50751101_4_dialog_content = "A intenção é me distrair e atrasar?",
  ui_story_5075_50751101_5_dialog_content = "...",
  ui_story_5075_50751101_6_dialog_content = "Mesmo quando fingi golpes nos pontos vitais, você não revidou.",
  ui_story_5075_50751101_7_dialog_content = "Vários estão feridos enquanto eu permaneço ileso.",
  ui_story_5075_50751101_8_dialog_content = "Heheh. Acho que finalmente entendi o que PlayerName quis dizer agora.",
  ui_story_5075_50751101_9_dialog_content = "É estranho ser tratado com tanta gentileza de repente.",
  ui_story_5075_50751101_10_dialog_content = "Mas há uma razão por trás de cada peculiaridade no mundo.",
  ui_story_5075_50751101_11_dialog_content = "O que a Ministra Armilla escreveu em sua mensagem, o que Jiu mencionou antes de partir, e o conselho do meu mentor.",
  ui_story_5075_50751101_12_dialog_content = "Apenas um idiota não conseguiria descobrir com tantas pistas.",
  ui_story_5075_50751101_13_dialog_content = "Você são espiões para o Reino Ye, certo?",
  ui_story_5075_50751101_14_dialog_content = "!",
  ui_story_5075_50751101_15_dialog_content = "Sua Alteza, você adivinhou certo. Agora você deve saber que não pretendemos prejudicá-lo.",
  ui_story_5075_50751101_16_dialog_content = "As coisas estão ficando complicadas na cidade de Haojin. Então, por favor, Alteza, volte para o palácio para sua segurança.",
  ui_story_5075_50751101_17_dialog_content = "Minha saída do palácio agora vai estragar seus planos?",
  ui_story_5075_50751101_18_dialog_content = "Entre dois reinos, os conflitos de vai e vem, tanto abertos quanto nos bastidores, são uma ocorrência comum.",
  ui_story_5075_50751101_19_dialog_content = "Alteza, você é bondoso, e <color=#FFB400>nosso senhor</color> não quer vê-lo em uma situação difícil. Então, por favor, volte.",
  ui_story_5075_50751101_20_dialog_content = "... <color=#FFB400>Seu senhor</color>.",
  ui_story_5075_50751101_21_dialog_content = "Alteza, se insistir em ir contra o nosso conselho, teremos que recorrer à força.",
  ui_story_5075_50751101_22_dialog_content = "Vá pegá-la!",
  ui_story_5075_50751101_23_dialog_content = "Levante-se como o Vento!",
  ui_story_5075_50751101_24_dialog_content = "<color=#e8d9bb>Swish—</color>",
  ui_story_5075_50751101_25_dialog_content = "Está ferido, Alteza?",
  ui_story_5075_50751101_26_dialog_content = "Jiu? Pensei que estivessem te ocupando, e que você não voltaria por um tempo.",
  ui_story_5075_50751101_27_dialog_content = "Meu dever é proteger você.",
  ui_story_5075_50751101_28_dialog_content = "Enquanto você precisar de mim, estarei de volta ao seu lado, onde quer que eu esteja.",
  ui_story_5075_50751101_29_dialog_content = "<color=#e8d9bb>De repente, uma mão agarra o tornozelo de Jiu.</color>",
  ui_story_5075_50751101_30_dialog_content = "Gelo... Lâmina... Você não pode...",
  ui_story_5075_50751101_31_dialog_content = "<color=#e8d9bb>Swish—</color>",
  ui_story_5075_50751101_32_dialog_content = "Tenho a sensação de que vou pedir muito a você mais tarde.",
  ui_story_5075_50751101_33_dialog_content = "Mas temos um problema urgente em mãos. Venha comigo ver PlayerName imediatamente.",
  ui_story_5075_50751101_34_dialog_content = "Você sabe onde PlayerName está, Sua Alteza?",
  ui_story_5075_50751101_35_dialog_content = "Eu estava com muita pressa para perguntar...",
  ui_story_5075_50751101_36_dialog_content = "Posso te interessar em uma pequena adivinhação?",
  ui_story_5075_50751101_37_dialog_content = "... Li Tianxian.",
  ui_story_5075_50751101_38_dialog_content = "Você esteve observando todo esse tempo?",
  ui_story_5075_50751101_39_dialog_content = "O que você está dizendo? Acabei de vender todas as minhas estatuetas de açúcar e tenho um palpite.",
  ui_story_5075_50751101_40_dialog_content = "Eu tinha a sensação de que encontraria alguém importante assim, então aqui estou, tentando a minha sorte.",
  ui_story_5075_50751101_41_dialog_content = "Mas eu não vi nada que não deveria ver. Juro.",
  ui_story_5075_50751101_42_dialog_content = "Deixa pra lá. Esquece.",
  ui_story_5075_50751101_43_dialog_content = "Vejo que é difícil conseguir novos clientes. PlayerName ainda é o melhor por acreditar em tudo o que eu digo.",
  ui_story_5075_50751101_44_dialog_content = "... Você viu PlayerName?",
  ui_story_5075_50751101_45_dialog_content = "Com certeza. Recebeu um doce de flor de ameixa e um poema meu também.",
  ui_story_5075_50751101_46_dialog_content = "Mas não precisa me agradecer.",
  ui_story_5075_50751101_47_dialog_content = "Isso é absurdo. Por que eu deveria te agradecer?",
  ui_story_5075_50751101_48_dialog_content = "Mas se você pudesse me dizer onde PlayerName está, eu ficaria grato.",
  ui_story_5075_50751101_49_dialog_content = "Lá na Rua Yulin, mas é melhor você se apressar.",
  ui_story_5075_50751101_50_dialog_content = "Ou alguém vai te superar.",
  ui_story_5075_50751101_51_dialog_content = "... Vamos, Jiu.",
  ui_story_5075_50751101_52_dialog_content = "Só um minuto. Estou eufórico por ter vendido todas as estatuetas de açúcar hoje.",
  ui_story_5075_50751101_53_dialog_content = "Então, vou te dar uma leitura de graça.",
  ui_story_5075_50751101_54_dialog_content = "Pelo que eu posso dizer, você estará indo para o sudeste para encontrar alguém importante.",
  ui_story_5075_50751101_55_dialog_content = "É onde fica a Rua Yulin. Você mesmo me disse a localização.",
  ui_story_5075_50751101_56_dialog_content = "Mas você não pode simplesmente seguir o fluxo e admitir que é para onde está indo?",
  ui_story_5075_50751101_57_dialog_content = "Não tenho tempo para suas bobagens.",
  ui_story_5075_50751101_58_dialog_content = "Esse é o destino que concluí a partir da sua leitura.",
  ui_story_5075_50751101_59_dialog_content = "Princesa Dantang, nós consultamos os espíritos e deidades na maioria das adivinhações.",
  ui_story_5075_50751101_60_dialog_content = "Mas a adivinhação mais precisa é consultar a si mesmo.",
  ui_story_5075_50751101_61_dialog_content = "Seus pensamentos e suas ações determinam o seu destino.",
  ui_story_5075_50751101_62_dialog_content = "Ops, desculpe por tomar mais do seu tempo. Terminei e não vou te segurar.",
  ui_story_5075_50751101_63_dialog_content = "...",
  ui_story_5075_50751101_64_dialog_content = "Muito obrigado.",
  ui_story_5075_50751101_65_dialog_content = "Não mencione isso, embora eu aprecie futuros negócios.",
  ui_story_5075_50751101_66_dialog_content = "Não se preocupe, eu não planejo.",
  ui_story_5075_50751102_1_dialog_content = "Ugh...",
  ui_story_5075_50751102_2_dialog_content = "Isto... não parece a pousada.",
  ui_story_5075_50751102_3_dialog_content = "Apesar de todo o seu discurso sobre hospitalidade, esta é a primeira vez que vejo alguém desmaiar e sequestrar seu convidado.",
  ui_story_5075_50751102_4_dialog_content = "Se você tivesse apenas cooperado, eu nunca pretendia aparecer diante de você assim.",
  ui_story_5075_50751102_5_dialog_content = "Afinal, o papel de mordomo da Pousada Real é bastante conveniente, e eu não queria mudá-lo.",
  ui_story_5075_50751102_6_dialog_content = "Eu não achei que você causaria tanto problema, até mesmo conseguindo que os Lins te dessem uma mão.",
  ui_story_5075_50751102_7_dialog_content = "No pior cenário, você pode realmente resolver a bagunça que provocamos intencionalmente.",
  ui_story_5075_50751102_8_dialog_content = "Então vocês estão por trás disso?",
  ui_story_5075_50751102_9_dialog_content = "Quebrando o selo do dragão, espalhando a névoa negra por toda a cidade, colocando pessoas e demônios uns contra os outros.",
  ui_story_5075_50751102_10_dialog_content = "O que exatamente você está procurando?",
  ui_story_5075_50751102_11_dialog_content = "Isso não é algo com que você deveria se preocupar.",
  ui_story_5075_50751102_12_dialog_content = "Apenas faça uma pausa neste esconderijo por enquanto. Assim que tudo se acalmar, <color=#FFB400>nós</color> vamos deixar você ir.",
  ui_story_5075_50751102_13_dialog_content = "Por <color=#FFB400>\"nós,\"</color> você quer dizer seus aliados dentro do governo do Reino Ji?",
  ui_story_5075_50751102_14_dialog_content = "O Conselheiro Chefe te disse isso, não disse?",
  ui_story_5075_50751102_15_dialog_content = "Aquele velho intrometido mexeu com muitas de nossas ações mesmo antes de perceber nossa presença.",
  ui_story_5075_50751102_16_dialog_content = "Mas ele não vai estar por aqui por muito tempo.",
  ui_story_5075_50751102_17_dialog_content = "E isso é tudo graças a você.",
  ui_story_5075_50751102_18_dialog_content = "Eu?",
  ui_story_5075_50751102_19_dialog_content = "Ouvi sua conversa com o Conselheiro Chefe e Sua Alteza no dia em que você chegou ao palácio.",
  ui_story_5075_50751102_20_dialog_content = "Não se deixe enganar pelas altas paredes do palácio. Lá dentro, é o lugar com menos segredos do mundo.",
  ui_story_5075_50751102_21_dialog_content = "Ele provavelmente percebeu que nosso agente estava se infiltrando lentamente no governo, mas não conseguiu identificar quem.",
  ui_story_5075_50751102_22_dialog_content = "É por isso que ele quer usar alguém como você, um forasteiro.",
  ui_story_5075_50751102_23_dialog_content = "Mas a jogada dele me deu uma brecha.",
  ui_story_5075_50751102_24_dialog_content = "Eu sei que o velhote te passou o distintivo do Escritório de Inspeção através daquela caixa de refeição.",
  ui_story_5075_50751102_25_dialog_content = "Se você realmente usou a força do Escritório de Inspeção para resolver o atual predicamento, sua ação seria apenas considerada como conveniência.",
  ui_story_5075_50751102_26_dialog_content = "Há espaço para justificativa mesmo que alguém investigue.",
  ui_story_5075_50751102_27_dialog_content = "Mas se alguém descobrir que o distintivo está com você antes que possa fazer algo com ele...",
  ui_story_5075_50751102_28_dialog_content = "Sendo o Conselheiro Chefe e entregando um item tão vital a um estrangeiro, especialmente alguém de outro continente...",
  ui_story_5075_50751102_29_dialog_content = "Alguém cujos movimentos são envoltos em mistério nos tempos mais tumultuados de Haojin.",
  ui_story_5075_50751102_30_dialog_content = "Quem poderia acreditar que você não está conspirando, tramando contra o Reino Ji?",
  ui_story_5075_50751102_31_dialog_content = "Todos no governo certamente o condenarão por traição.",
  ui_story_5075_50751102_32_dialog_content = "Deixe-me ver, onde você escondeu o emblema? No seu bolso? Manga?",
  ui_story_5075_50751102_33_dialog_content = "Você pode parar de procurar. Eu não tenho mais isso comigo.",
  ui_story_5075_50751102_34_dialog_content = "Quando o Conselheiro Chefe me pediu para operar em segredo, tive a sensação de que era por causa das pessoas ao meu redor.",
  ui_story_5075_50751102_35_dialog_content = "Depois que recebi aquela caixa de comida, fiquei ainda mais convencido de que alguém na Pousada Real não podia ser confiável.",
  ui_story_5075_50751102_36_dialog_content = "Se esse é o caso, então era apenas uma questão de tempo até você descobrir.",
  ui_story_5075_50751102_37_dialog_content = "É por isso que eu tinha que sair de lá o mais rápido possível.",
  ui_story_5075_50751102_38_dialog_content = "Qual o ponto? Você ainda não encontrou a oportunidade de mobilizar o Escritório de Inspeção.",
  ui_story_5075_50751102_39_dialog_content = "Além disso, como alguém de uma terra distante, o número de pessoas que você conhece em Longzhou é extremamente limitado.",
  ui_story_5075_50751102_40_dialog_content = "Mesmo que você seja conhecido da Princesa Zhuohua, ela está no palácio, e eu ordenei que espiões a monitorassem o tempo todo, não deixando você ter a chance de se comunicar com ela.",
  ui_story_5075_50751102_41_dialog_content = "Quem quer que você dê a insígnia pode ser revelado com uma simples investigação.",
  ui_story_5075_50751102_42_dialog_content = "Ah, entendi. É a família Lin, certo?",
  ui_story_5075_50751102_43_dialog_content = "O Mestre da Guilda Lin assumiria qualquer risco, desde que fosse lucrativo.",
  ui_story_5075_50751102_44_dialog_content = "Mas dar o comando do Escritório de Inspeção a um comerciante com um histórico manchado... Hahaha!",
  ui_story_5075_50751102_45_dialog_content = "Mesmo no Reino de Ji, onde o comércio e os comerciantes são valorizados, a absurdidade de sua ação é sem precedentes, tornando fácil atribuir um crime.",
  ui_story_5075_50751102_46_dialog_content = "Por um segundo, eu realmente pensei que você tinha algumas cartas na manga, mas parece que você é apenas uma criança ingênua.",
  ui_story_5075_50751102_47_dialog_content = "Preciso ficar de olho na minha tripulação. Não há tempo a perder com você.",
  ui_story_5075_50751102_48_dialog_content = "Quem disse que eu dei o distintivo para a família Lin?",
  ui_story_5075_50751102_49_dialog_content = "Se não forem os Lins, provavelmente são aqueles dois que estavam com você mais cedo.",
  ui_story_5075_50751102_50_dialog_content = "Plebeus ou comerciantes, não há muita diferença aí—",
  ui_story_5075_50751102_51_dialog_content = "Não era um plebeu.",
  ui_story_5075_50751102_52_dialog_content = "<size=45>Foi a <color=#FFB400>Princesa Zhuohua</color>.</size>",
  ui_story_5075_50751102_53_dialog_content = "Você não ouviu? Eu disse que há espiões ao redor da princesa, e ela não pode possivelmente...",
  ui_story_5075_50751102_54_dialog_content = "<size=45>Ela estará aqui em breve.</size>",
  ui_story_5075_50751102_55_dialog_content = "O emblema é um símbolo do Escritório de Inspeção, o endereço pertence à família Lin e quem me orientou é seu mentor.",
  ui_story_5075_50751102_56_dialog_content = "E todas elas são unidas por begônias.",
  ui_story_5075_50751102_57_dialog_content = "Dantang é o único que poderia fazer uso total de ambos!",
  ui_story_5075_50751102_58_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5075_50751102_59_dialog_content = "Não se mexa ou você perderá a cabeça.",
  ui_story_5075_50751102_60_dialog_content = "Você tá bem, PlayerName?",
  ui_story_5075_50751102_61_dialog_content = "Dantang! Jiu!",
  ui_story_5075_50751102_62_dialog_content = "Você... Como você... Ah!",
  ui_story_5075_50751102_63_dialog_content = "<color=#e8d9bb>Dantang puxa de repente o rosto do mordomo da Pousada Real.</color>",
  ui_story_5075_50751102_64_dialog_content = "<color=#e8d9bb>Uma máscara, fina como a asa de uma cigarra, é descascada, revelando um estranho novo rosto por baixo.</color>",
  ui_story_5075_50751102_65_dialog_content = "Você realmente não é o verdadeiro mordomo da Casa de Hóspedes Real, mas um impostor.",
  ui_story_5075_50751102_66_dialog_content = "... E daí se você me pegar? Não vai mudar nada.",
  ui_story_5075_50751102_67_dialog_content = "A sabedoria do nosso senhor é incomparável. Nós, os <color=#FFB400>Cavaleiros do Destino</color>, estamos em todos os lugares.",
  ui_story_5075_50751102_68_dialog_content = "Nosso plano está quase concluído. O selo no fundo do mar foi quebrado, e o pesadelo adormecido já despertou!",
  ui_story_5075_50751102_69_dialog_content = "Quando Haojin cair no caos, nós entraremos em ação e tomaremos o Reino Ji sem nem suar.",
  ui_story_5075_50751102_70_dialog_content = "A não ser que você tenha uma divindade ao seu lado, caso contrário—urgh!",
  ui_story_5075_50751102_71_dialog_content = "Alguém pediu ajuda?",
  ui_story_5075_50751102_72_dialog_content = "Grr! Pff-urgh!",
  ui_story_5075_50751102_73_dialog_content = "Chen'ni? O que você está fazendo aqui?",
  ui_story_5075_50751102_74_dialog_content = "Eu estava perseguindo o culpado que quebrou o selo, mas acabei perdendo o malandro eventualmente.",
  ui_story_5075_50751102_75_dialog_content = "Então decidi seguir o rastro, investigando todos os lugares por onde o cara passou e todas as pessoas que tiveram contato com ele.",
  ui_story_5075_50751102_76_dialog_content = "Incluindo aqui!",
  ui_story_5075_50751102_77_dialog_content = "Grr! Urgh!",
  ui_story_5075_50751102_78_dialog_content = "E eu até conheci o vendedor de estatuetas de açúcar.",
  ui_story_5075_50751102_79_dialog_content = "Aquele vendedor de figuras de açúcar que fez doces de flor de ameixa?",
  ui_story_5075_50751102_80_dialog_content = "É esse mesmo! Ele é tão generoso e me ofereceu um monte de miniaturas.",
  ui_story_5075_50751102_81_dialog_content = "Ele só queria uma coisa - que eu plantasse um galho de flor de ameixa por onde eu fosse.",
  ui_story_5075_50751102_82_dialog_content = "Então você fez isso?",
  ui_story_5075_50751102_83_dialog_content = "Claro. Recebi minhas ofertas, então tenho que cumprir minhas promessas.",
  ui_story_5075_50751102_84_dialog_content = "Também plantei uma do lado de fora desta casa.",
  ui_story_5075_50751102_85_dialog_content = "Graças a Deus... Dantang!",
  ui_story_5075_50751102_86_dialog_content = "Tô aqui.",
  ui_story_5075_50751102_87_dialog_content = "Consegui a insígnia do Lin Guildmaster e a assistência do Guarda da Família.",
  ui_story_5075_50751102_88_dialog_content = "Os guardas estão prontos para a ordem de Zhong Xu para suprimir os Eclipsitas e os demônios frenéticos na cidade.",
  ui_story_5075_50751102_89_dialog_content = "Uma vez que o Escritório de Inspeção tenha lidado com os chamados Cavaleiros do Destino, eles também entrarão na briga.",
  ui_story_5075_50751102_90_dialog_content = "Obrigado... por lembrar da flor que eu amo.",
  ui_story_5075_50751102_91_dialog_content = "Haha, estou apenas feliz que deu certo! Como estão as coisas lá fora?",
  ui_story_5075_50751102_92_dialog_content = "Ainda estamos resistindo na cidade, mas depende de Yuebai para as áreas periféricas.",
  ui_story_5075_50751102_93_dialog_content = "Bom. Quanto ao exterior da cidade, o mordomo da Casa de Hóspedes Real... Esse homem acabou de dizer que o plano deles está quase concluído.",
  ui_story_5075_50751102_94_dialog_content = "É possível que Yoh tenha se fundido completamente com a névoa negra até agora.",
  ui_story_5075_50751102_95_dialog_content = "Precisamos encontrá-lo e acabar com isso imediatamente!",
  ui_story_5075_50751102_96_dialog_content = "Então, venha comigo.",
  ui_story_5075_50751102_97_dialog_content = "Eu organizei para que uma pequena embarcação nos leve diretamente à baía.",
  ui_story_5075_50751102_98_dialog_content = "Dantang tem a cidade. Eu vou com Yuebai para encontrar Yoh... Hã?",
  ui_story_5075_50751102_99_dialog_content = "Uh... Empregada Dragão?",
  ui_story_5075_50751102_100_dialog_content = "Eu não entendi muito bem, mas alguém puniu o cara que quebrou o selo por mim, certo?",
  ui_story_5075_50751102_101_dialog_content = "Eu irei com você para a beira-mar!",
  ui_story_5075_50751102_102_dialog_content = "A miragem criada por Yoh pode ser muito formidável para os poderes de um Caelestite conquistar sozinho.",
  ui_story_5075_50751201_1_dialog_content = "<color=#e8d9bb>Respingo</color>",
  ui_story_5075_50751201_2_dialog_content = "Hmm... Desculpe, devo ter adormecido. Já chegamos, Yue...",
  ui_story_5075_50751201_3_dialog_content = "Hã?",
  ui_story_5075_50751201_4_dialog_content = "De quem era o nome que eu estava tentando dizer agora mesmo?",
  ui_story_5075_50751201_5_dialog_content = "Mais importante, o que estou fazendo neste navio?",
  ui_story_5075_50751201_6_dialog_content = "Urgh... Minha cabeça dói.",
  ui_story_5075_50751201_7_dialog_content = "Ei, você está sonhando acordado de novo? Mexa-se e continue movendo essa carga! Estamos zarpando em breve.",
  ui_story_5075_50751201_8_dialog_content = "C-Carregar a carga? Eu?",
  ui_story_5075_50751201_9_dialog_content = "Não tem mais ninguém aqui.",
  ui_story_5075_50751201_10_dialog_content = "Não foi você quem disse que seu parente, Soroz ou algo assim, ficou doente, e você precisava trabalhar para juntar dinheiro para o remédio rapidamente?",
  ui_story_5075_50751201_11_dialog_content = "Quem sabe se essa viagem ultramarina de que falam será de um retorno seguro.",
  ui_story_5075_50751201_12_dialog_content = "Ainda bem que a Guilda Lin pode ser pequena, mas eles estão dispostos a pagar muito por essa viagem, até mesmo dando metade adiantado.",
  ui_story_5075_50751201_13_dialog_content = "Com esse dinheiro, finalmente posso comprar uma boa comida para minha esposa e filhos.",
  ui_story_5075_50751201_14_dialog_content = "Sua família não precisará se preocupar com o dinheiro do remédio por um tempo, certo?",
  ui_story_5075_50751201_15_dialog_content = "(Algo não está certo sobre isso, mas o que ele está dizendo faz sentido...)",
  ui_story_5075_50751201_16_dialog_content = "(Argh... Minha cabeça está doendo novamente.)",
  ui_story_5075_50751201_17_dialog_content = "(É melhor eu apenas carregar essa carga.)",
  ui_story_5075_50751201_18_dialog_content = "<color=#e8d9bb>Respingo</color>",
  ui_story_5075_50751201_19_dialog_content = "Hã? O que está acontecendo?",
  ui_story_5075_50751201_20_dialog_content = "De onde está vindo toda essa névoa?",
  ui_story_5075_50751201_21_dialog_content = "Perdeu a cabeça de fome? Estamos presos nessa névoa há quase duas semanas, apenas andando em círculos.",
  ui_story_5075_50751201_22_dialog_content = "Parece que todos nós neste navio podemos encontrar nosso fim aqui.",
  ui_story_5075_50751201_23_dialog_content = "Tenho minha esposa e filhos me esperando em casa, não posso morrer agora...",
  ui_story_5075_50751201_24_dialog_content = "<color=#e8d9bb>Seu suspiro provoca uma onda de choros dolorosos.</color>",
  ui_story_5075_50751201_25_dialog_content = "<color=#e8d9bb>A tripulação e os comerciantes estão espalhados pelo convés, seus suspiros tingidos de desespero cansado.</color>",
  ui_story_5075_50751201_26_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5075_50751201_27_dialog_content = "(Alguma coisa acabou de se chocar contra o navio?)",
  ui_story_5075_50751201_28_dialog_content = "Rápido... Venha aqui e olhe!",
  ui_story_5075_50751201_29_dialog_content = "Esses peixes, esses peixes estão empurrando o navio por baixo!",
  ui_story_5075_50751201_30_dialog_content = "São peixes-serpente! Estamos com sorte! É inverno, e eles sempre voltam para Longzhou nesta época do ano!",
  ui_story_5075_50751201_31_dialog_content = "Siga-os, e podemos sair daqui!",
  ui_story_5075_50751201_32_dialog_content = "Está vendo isso? É uma bênção divina! As divindades devem ter nos ouvido!",
  ui_story_5075_50751201_33_dialog_content = "(Estou alucinando ou algo assim? Aquele peixe-serpente bem na frente... Por que parece tão familiar?)",
  ui_story_5075_50751201_34_dialog_content = "<color=#e8d9bb>Respingo</color>",
  ui_story_5075_50751201_35_dialog_content = "Eu sou... um peixe-serpente.",
  ui_story_5075_50751201_36_dialog_content = "Eu caço minha comida enquanto viajo pelos mares e, ocasionalmente, procuro o conselho de outros usuários de Luminatics.",
  ui_story_5075_50751201_37_dialog_content = "Todo inverno, retornamos a Longzhou, o lugar do nosso nascimento.",
  ui_story_5075_50751201_38_dialog_content = "Um dia, descobrimos um navio perdido no mar.",
  ui_story_5075_50751201_39_dialog_content = "Ele nos seguiu de volta às margens de Longzhou, onde seu líder fez um pacto com o nosso.",
  ui_story_5075_50751201_40_dialog_content = "Todos os invernos desde então, escoltamos aquele navio em nossas viagens para Longzhou.",
  ui_story_5075_50751201_41_dialog_content = "Nós orientamos seu curso e, em troca, eles nos ofereceram comida.",
  ui_story_5075_50751201_42_dialog_content = "Foi uma troca agradável, que deveria ter nos deixado felizes.",
  ui_story_5075_50751201_43_dialog_content = "<color=#e8d9bb>Respingo</color>",
  ui_story_5075_50751201_44_dialog_content = "Chefe, chefe? Se desligando de novo no peixe-serpente?",
  ui_story_5075_50751201_45_dialog_content = "Desculpe, mas por algum motivo, um desses peixes-serpente parece muito familiar.",
  ui_story_5075_50751201_46_dialog_content = "Todos parecem iguais. O que há para ver? Aqui, veja isso.",
  ui_story_5075_50751201_47_dialog_content = "Aqui está o seu corte da viagem ao exterior.",
  ui_story_5075_50751201_48_dialog_content = "Isso é muito demais!",
  ui_story_5075_50751201_49_dialog_content = "Desde que os Lins começaram a rota oceânica, temos ganhado cada vez mais. Isso é apenas uma ninharia.",
  ui_story_5075_50751201_50_dialog_content = "Interessado em ganhar mais dinheiro?",
  ui_story_5075_50751201_51_dialog_content = "E-Eu posso fazer ainda mais?",
  ui_story_5075_50751201_52_dialog_content = "Eu conversei com os outros antes de vir para cá. Os negócios da Guilda Lin estão se expandindo.",
  ui_story_5075_50751201_53_dialog_content = "Há cada vez mais necessidade de comércio com lugares como Astra. Apenas uma viagem por ano nem chega perto de atender à demanda!",
  ui_story_5075_50751201_54_dialog_content = "Que tal nos unirmos e conversar com o Guildmaster sobre adicionar outra corrida?",
  ui_story_5075_50751201_55_dialog_content = "Duas viagens por ano, o que acha disso?",
  ui_story_5075_50751201_56_dialog_content = "Mas eu acho que o peixe-serpente só retorna a Longzhou no inverno?",
  ui_story_5075_50751201_57_dialog_content = "Eles estão apenas vagando pelo mar na maior parte do tempo. Uma viagem adicional de volta a Longzhou não deve importar muito.",
  ui_story_5075_50751201_58_dialog_content = "Com o dinheiro extra que ganhamos, podemos comprar mais comida para peixes para eles, certo?",
  ui_story_5075_50751201_59_dialog_content = "Eu não acho que os peixes-serpente realmente se importam com isso.",
  ui_story_5075_50751201_60_dialog_content = "Tsk, parece impossível te convencer disso. Deixa pra lá então. Todos os outros estão a bordo, então você não ir não é um grande problema.",
  ui_story_5075_50751201_61_dialog_content = "Espere, eu não sou—",
  ui_story_5075_50751201_62_dialog_content = "<color=#e8d9bb>Respingo</color>",
  ui_story_5075_50751201_63_dialog_content = "Depois, nosso líder nos disse que também teríamos que voltar para Longzhou no verão.",
  ui_story_5075_50751201_64_dialog_content = "As águas do verão estão quentes e desagradáveis.",
  ui_story_5075_50751201_65_dialog_content = "Mas nossos amigos a bordo do navio precisavam de nossa ajuda.",
  ui_story_5075_50751201_66_dialog_content = "Então nós concordamos.",
  ui_story_5075_50751201_67_dialog_content = "Mesmo que a viagem tenha sido longa e cansativa, concordamos.",
  ui_story_5075_50751201_68_dialog_content = "<color=#e8d9bb>Respingo</color>",
  ui_story_5075_50751201_69_dialog_content = "Hoje, reuni todos aqui para fazer um anúncio.",
  ui_story_5075_50751201_70_dialog_content = "Conseguimos um negócio com Yangjing, e para atender à demanda, devemos fazer outra longa viagem este ano.",
  ui_story_5075_50751201_71_dialog_content = "Mas espere, nosso acordo com o peixe-serpente cobre apenas uma viagem por ano.",
  ui_story_5075_50751201_72_dialog_content = "Pedir a eles para nos guiar até Longzhou no verão já é uma violação do contrato, sem mencionar—",
  ui_story_5075_50751201_73_dialog_content = "Este é um negócio de Yangjing, algo que muitas guildas sonham.",
  ui_story_5075_50751201_74_dialog_content = "Você tem ideia de quanto lucro esse negócio trará para os Lins?",
  ui_story_5075_50751201_75_dialog_content = "Entendo que essa decisão é injusta para o peixe-serpente, e eu pessoalmente pedirei desculpas ao demônio depois.",
  ui_story_5075_50751201_76_dialog_content = "Esse é o nosso plano agora.",
  ui_story_5075_50751201_77_dialog_content = "<color=#e8d9bb>Respingo</color>",
  ui_story_5075_50751201_78_dialog_content = "Naquele ano, retornamos a Longzhou três vezes.",
  ui_story_5075_50751201_79_dialog_content = "Nosso líder disse que era apenas temporário e que nossos amigos estavam em apuros.",
  ui_story_5075_50751201_80_dialog_content = "Mas o próximo ano também teve três viagens. O ano seguinte não foi diferente.",
  ui_story_5075_50751201_81_dialog_content = "Vários dos nossos já haviam desaparecido.",
  ui_story_5075_50751201_82_dialog_content = "Depois disso, nosso líder faleceu inesperadamente.",
  ui_story_5075_50751201_83_dialog_content = "E assim, me tornei o novo líder do peixe-serpente.",
  ui_story_5075_50751201_84_dialog_content = "Nossos amigos a bordo do navio apareceram um dia. Eles me trouxeram para a terra e me colocaram em um tanque dentro de um prédio de madeira.",
  ui_story_5075_50751201_85_dialog_content = "O tanque era tão pequeno e apertado.",
  ui_story_5075_50751201_86_dialog_content = "Era insuportável.",
  ui_story_5075_50751201_87_dialog_content = "O quarto ano viu mais três viagens para Longzhou.",
  ui_story_5075_50751201_88_dialog_content = "Mas mesmo durante nossas viagens, eles se recusaram a me deixar nadar no oceano.",
  ui_story_5075_50751201_89_dialog_content = "Eles trouxeram meu tanque para bordo de sua nave e me mantiveram bem alimentado. Eles disseram que minha única preocupação era instruir minha espécie de lá de cima.",
  ui_story_5075_50751201_90_dialog_content = "Eles chamavam isso de \"adoração\", uma maneira de mostrar seu respeito aos demônios.",
  ui_story_5075_50751201_91_dialog_content = "Já consegue mudar sua forma, hein?",
  ui_story_5075_50751201_92_dialog_content = "...",
  ui_story_5075_50751201_93_dialog_content = "Mas você ainda não consegue falar, não é?",
  ui_story_5075_50751201_94_dialog_content = "Gostaria de aprender? Eu posso te ensinar. Considere isso uma compensação...",
  ui_story_5075_50751201_95_dialog_content = "Deixa pra lá, você não consegue entender o que eu estou dizendo mesmo.",
  ui_story_5075_50751201_96_dialog_content = "Além disso, os erros que cometi contra você não são algo que algumas pequenas ações possam consertar.",
  ui_story_5075_50751201_97_dialog_content = "(Eu sabia que ele era o líder deles.)",
  ui_story_5075_50751201_98_dialog_content = "(Ele me ensinou a falar e ler a língua deles.)",
  ui_story_5075_50751201_99_dialog_content = "(Mas eu também sabia que ele era um homem muito, muito malvado.)",
  ui_story_5075_50751201_100_dialog_content = "<color=#e8d9bb>Respingo</color>",
  ui_story_5075_50751201_101_dialog_content = "Quatro viagens?",
  ui_story_5075_50751201_102_dialog_content = "A Família Qi tem cobiçado o título de Comerciante Imperial, querendo desafiar nossa Guilda Lin.",
  ui_story_5075_50751201_103_dialog_content = "Sem mais realizações notáveis, podemos estar fora do jogo.",
  ui_story_5075_50751201_104_dialog_content = "Não podemos deixar que a glória centenária da Família Lin seja manchada sob nossa vigilância.",
  ui_story_5075_50751201_105_dialog_content = "Nos últimos anos, os peixes-serpente têm morrido em números cada vez maiores! Não finja que você não sabe!",
  ui_story_5075_50751201_106_dialog_content = "E? E daí?",
  ui_story_5075_50751201_107_dialog_content = "Como assim, \"E daí?\" O que você planeja fazer a respeito?",
  ui_story_5075_50751201_108_dialog_content = "Quando precisamos enviar mais mercadorias, começamos a fazer duas viagens. Após receber um pedido urgente, aumentou para três.",
  ui_story_5075_50751201_109_dialog_content = "A Família Lin deve seu imenso sucesso ao peixe-serpente!",
  ui_story_5075_50751201_110_dialog_content = "Eles nos salvaram de uma morte certa e até concordaram em nos ajudar, e é assim que os recompensamos?",
  ui_story_5075_50751201_111_dialog_content = "Pare de tentar esconder sua ganância com desculpas tão nobres!",
  ui_story_5075_50751201_112_dialog_content = "PlayerName...",
  ui_story_5075_50751201_113_dialog_content = "Urgh... Quem era aquela pessoa agora há pouco?",
  ui_story_5075_50751201_114_dialog_content = "Você recebe pagamento da nossa Guilda Lin, mas parece mais devotado ao peixe-serpente, hein?",
  ui_story_5075_50751201_115_dialog_content = "Não temos utilidade para alguém como você. Você está dispensado.",
  ui_story_5075_50751201_116_dialog_content = "Tenho que participar de uma reunião sobre a quarta viagem. Você vai resolver seu pagamento mensal com o mordomo sozinho.",
  ui_story_5075_50751201_117_dialog_content = "... Tem certeza de que quer seguir em frente com isso?",
  ui_story_5075_50751201_118_dialog_content = "O que você quer?",
  ui_story_5075_50751201_119_dialog_content = "Vou devolver o líder do peixe-serpente para o mar.",
  ui_story_5075_50751201_120_dialog_content = "Ali! Eu encontrei o tanque!",
  ui_story_5075_50751201_121_dialog_content = "Desculpe, mas para te devolver ao oceano, terei que te tirar da água por um tempo.",
  ui_story_5075_50751201_122_dialog_content = "Pare-o!",
  ui_story_5075_50751201_123_dialog_content = "De onde todas essas pessoas vieram? Eu tenho que encontrar uma maneira de passar por elas...",
  ui_story_5075_50751201_124_dialog_content = "Aumento de Força!",
  ui_story_5075_50751201_125_dialog_content = "Ugh!",
  ui_story_5075_50751201_126_dialog_content = "... Huh? Que poder é esse?",
  ui_story_5075_50751201_127_dialog_content = "PlayerName!",
  ui_story_5075_50751201_128_dialog_content = "... Chen'ni?",
  ui_story_5075_50751201_129_dialog_content = "Já era hora de você me notar.",
  ui_story_5075_50751201_130_dialog_content = "Assim que nosso navio entrou na baía, você e Yuebai adormeceram. Eu não conseguia acordá-los, não importa o que eu tentasse.",
  ui_story_5075_50751201_131_dialog_content = "Estava tão entediado e queria que vocês dois se levantassem.",
  ui_story_5075_50751201_132_dialog_content = "Eu me lembro agora! No momento em que navegamos para a baía, uma enorme onda de névoa negra veio direto para nós!",
  ui_story_5075_50751201_133_dialog_content = "Esse poder deve ser o que nos prendeu neste sonho... Ou será algum tipo de ilusão?",
  ui_story_5075_50751201_134_dialog_content = "De qualquer forma.",
  ui_story_5075_50751201_135_dialog_content = "Você está muito calmo com isso!",
  ui_story_5075_50751201_136_dialog_content = "Isso não é o que é importante.",
  ui_story_5075_50751201_137_dialog_content = "É melhor você ir verificar Yuebai agora.",
  ui_story_5075_50751201_138_dialog_content = "Ela parece estar sofrendo muito.",
  ui_story_5075_50751201_139_dialog_content = "Essa é a corrupção da névoa negra? Chen'ni, você não pode...",
  ui_story_5075_50751201_140_dialog_content = "Eu posso, mas não desta vez.",
  ui_story_5075_50751201_141_dialog_content = "Mas por que-",
  ui_story_5075_50751201_142_dialog_content = "Não é bom confiar em divindades para tudo.",
  ui_story_5075_50751201_143_dialog_content = "Você tem que cuidar dos seus próprios negócios.",
  ui_story_5075_50751201_144_dialog_content = "... Entendo.",
  ui_story_5075_50751201_145_option_content = "Varredura Psíquica!",
  ui_story_5075_50751201_146_dialog_content = "Yuebai! Onde você está?",
  ui_story_5075_50751201_147_dialog_content = "PlayerName.",
  ui_story_5075_50751201_148_dialog_content = "Esse peixe-serpente... É você, Yuebai?",
  ui_story_5075_50751201_149_dialog_content = "Pare!",
  ui_story_5075_50751201_150_dialog_content = "Não isso de novo!",
  ui_story_5075_50751201_151_dialog_content = "... Vamos, temos que ir para a praia!",
  ui_story_5075_50751201_152_dialog_content = "Ufa... Nós... Nós conseguimos.",
  ui_story_5075_50751201_153_dialog_content = "Por que eu tenho que me esgotar até mesmo em um sonho?",
  ui_story_5075_50751201_154_dialog_content = "Vamos apenas colocar você na água por agora, Yuebai. Depois disso, nós vamos...",
  ui_story_5075_50751201_155_dialog_content = "Yuebai?",
  ui_story_5075_50751201_156_dialog_content = "(Perdi a visão dela assim que ela entrou...)",
  ui_story_5075_50751201_157_dialog_content = "(A água... Está cheia de névoa preta!)",
  ui_story_5075_50751201_158_dialog_content = "...",
  ui_story_5075_50751201_159_dialog_content = "(Líder, estou cansado. Líder, estou com fome. Líder, está doendo.)",
  ui_story_5075_50751201_160_dialog_content = "(Eu odeio isso. Eu quero voltar. Líder, por favor, me salve.)",
  ui_story_5075_50751201_161_dialog_content = "(Nos salve. Líder... Nos salve.)",
  ui_story_5075_50751201_162_dialog_content = "(Os outros estão me chamando.)",
  ui_story_5075_50751201_163_dialog_content = "(Tão confuso. Tão caótico. Essas vozes... Os corações dos peixes-serpente estão clamando.)",
  ui_story_5075_50751201_164_dialog_content = "Aquelas. Vozes.",
  ui_story_5075_50751201_165_dialog_content = "Eles. Chamam. Todos. Os dias.",
  ui_story_5075_50751201_166_dialog_content = "Sempre. Sempre.",
  ui_story_5075_50751201_167_dialog_content = "Eles. Odeiam.",
  ui_story_5075_50751201_168_dialog_content = "Yoh.",
  ui_story_5075_50751201_169_dialog_content = "Agora eu vejo.",
  ui_story_5075_50751201_170_dialog_content = "O que eu vivenciei agora foram suas próprias memórias.",
  ui_story_5075_50751201_171_dialog_content = "Os. Lins.",
  ui_story_5075_50751201_172_dialog_content = "Traidores. Eles.",
  ui_story_5075_50751201_173_dialog_content = "Pessoas. Não. Podem. Ser. Confiáveis.",
  ui_story_5075_50751201_174_dialog_content = "Você. É. Peixe. Também.",
  ui_story_5075_50751201_175_dialog_content = "Deveria. Detestar!",
  ui_story_5075_50751201_176_dialog_content = "Yuebai! Você consegue me ouvir?",
  ui_story_5075_50751201_177_dialog_content = "Estou indo te encontrar!",
  ui_story_5075_50751201_178_dialog_content = "Não é necessário, PlayerName.",
  ui_story_5075_50751201_179_dialog_content = "Hã?",
  ui_story_5075_50751201_180_dialog_content = "A Família Lin fez isso com Yoh.",
  ui_story_5075_50751201_181_dialog_content = "E como hoje me foi dada total autoridade sobre a família Lin, Yoh está totalmente justificado em exercer sua vingança contra mim.",
  ui_story_5075_50751201_182_dialog_content = "...",
  ui_story_5075_50751201_183_dialog_content = "A névoa preta está parando?",
  ui_story_5075_50751201_184_dialog_content = "Não... Não está certo...",
  ui_story_5075_50751201_185_dialog_content = "Eu... Não...",
  ui_story_5075_50751201_186_dialog_content = "O que há de errado com Yoh? Ele parece estar com muita dor...",
  ui_story_5075_50751201_187_dialog_content = "Isso é porque não é isso que ele realmente quer.",
  ui_story_5075_50751201_188_dialog_content = "O Yoh que eu conheço se importa tanto com seus amigos quanto com os de sua própria espécie. Ele não gostaria que seu ódio machucasse eles ou qualquer outro demônio.",
  ui_story_5075_50751201_189_dialog_content = "Além disso, nem todos nós somos tão perversos quanto nossos antecessores.",
  ui_story_5075_50751201_190_dialog_content = "Tenho certeza de que você viu o que PlayerName tentou fazer.",
  ui_story_5075_50751201_191_dialog_content = "Se ele fosse parte da família Lin naquela época... Tenho certeza de que teria feito exatamente o mesmo.",
  ui_story_5075_50751201_192_dialog_content = "...",
  ui_story_5075_50751201_193_dialog_content = "A Família Lin te manteve preso tempo suficiente.",
  ui_story_5075_50751201_194_dialog_content = "Não vou permitir que mais ninguém te mantenha acorrentado pelo ódio.",
  ui_story_5075_50751201_195_dialog_content = "Também consigo ouvir as vozes dos peixes-serpente.",
  ui_story_5075_50751201_196_dialog_content = "É por isso que vou te salvar.",
  ui_story_5075_50751201_197_dialog_content = "Não!",
  ui_story_5075_50751201_198_dialog_content = "Eu. Odeio!",
  ui_story_5075_50751201_199_dialog_content = "Você. É. Demais.",
  ui_story_5075_50751201_200_dialog_content = "<size=45>Traidor!</size>",
  ui_story_5075_50751202_1_dialog_content = "Ótimo! Você finalmente acordou. Sabe, crianças que dormem demais prejudicam o próprio crescimento.",
  ui_story_5075_50751202_2_dialog_content = "Sério? Então se eu começar a ir para a cama e acordar mais cedo... Eu ainda posso ficar um pouco mais alto?",
  ui_story_5075_50751202_3_dialog_content = "Você pode tentar rezar para mim!",
  ui_story_5075_50751202_4_dialog_content = "E Yuebai também.",
  ui_story_5075_50751202_5_dialog_content = "Eu não sou mais uma criança.",
  ui_story_5075_50751202_6_dialog_content = "Ah, você é um comparado a mim.",
  ui_story_5075_50751202_7_dialog_content = "Então não franza a testa o tempo todo. Afinal, Yoh simplesmente não queria lutar contra você e fugiu.",
  ui_story_5075_50751202_8_dialog_content = "Enquanto ele ainda estiver lá, é moleza tirá-lo do mar.",
  ui_story_5075_50751202_9_dialog_content = "<color=#e8d9bb>De repente, Chen'ni levanta a mão e lança um feixe de luz dourada no mar.</color>",
  ui_story_5075_50751202_10_dialog_content = "Provavelmente eu não deveria perguntar sobre o que você acabou de fazer, certo?",
  ui_story_5075_50751202_11_dialog_content = "Bem, isso não importa mais para mim, então pode muito bem quebrar o resto dos selos.",
  ui_story_5075_50751202_12_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5075_50751202_13_dialog_content = "<color=#e8d9bb>A anteriormente calma superfície do mar de repente se agita violentamente, com ondas gigantes se erguendo.</color>",
  ui_story_5075_50751202_14_dialog_content = "<color=#e8d9bb>Uma figura surge do oceano para o meio do ar.</color>",
  ui_story_5075_50751202_15_dialog_content = "<color=#e8d9bb>Inúmeros redemoinhos rasgam a superfície do mar, de onde surge uma névoa negra sem limites.</color>",
  ui_story_5075_50751202_16_dialog_content = "É esse o Yoh ao qual você estava se referindo? Ele é bem jovem.",
  ui_story_5075_50751202_17_dialog_content = "Eu. Conheço. Você.",
  ui_story_5075_50751202_18_dialog_content = "Chen. Dragão.",
  ui_story_5075_50751202_19_dialog_content = "Ele me conhece pela raiva que o possui? Isso é muito tempo para guardar rancor.",
  ui_story_5075_50751202_20_dialog_content = "Eu. Quero. Vingança.",
  ui_story_5075_50751202_21_dialog_content = "Não. Você. Interfira.",
  ui_story_5075_50751202_22_dialog_content = "Ou. Senão.",
  ui_story_5075_50751202_23_dialog_content = "Inundação. Cidade.",
  ui_story_5075_50751202_24_dialog_content = "Ah, não me diga que você é...",
  ui_story_5075_50751202_25_dialog_content = "(Esta é a primeira vez que vejo Chen'ni tão sério.)",
  ui_story_5075_50751202_26_dialog_content = "(Ela realmente não pode fazer nada por Yoh?)",
  ui_story_5075_50751202_27_dialog_content = "Então, ele quer dizer que se Chen'ni intervir, ele vai inundar todo o Haojin?",
  ui_story_5075_50751202_28_dialog_content = "Ele está mantendo a cidade inteira como refém.",
  ui_story_5075_50751202_29_dialog_content = "Então você está...",
  ui_story_5075_50751202_30_dialog_content = "Ameaçando-me?",
  ui_story_5075_50751202_31_dialog_content = "Hã?",
  ui_story_5075_50751202_32_dialog_content = "Isso é legal! Ninguém me ameaça há alguns séculos!",
  ui_story_5075_50751202_33_dialog_content = "Mas, pensando bem, realmente não tenho nada a ver com isso.",
  ui_story_5075_50751202_34_dialog_content = "Os eventos parecem complicados, e eu não entendo muito bem.",
  ui_story_5075_50751202_35_dialog_content = "Mas vocês, mortais, quebraram o selo, e a animosidade de Yoh também é um problema entre mortais e demônios.",
  ui_story_5075_50751202_36_dialog_content = "Então, isso deve ser resolvido entre mortais e demônios.",
  ui_story_5075_50751202_37_dialog_content = "Sim, eu faço muito sentido!",
  ui_story_5075_50751202_38_dialog_content = "Definitivamente não é a hora para você ser \"lógico\"!",
  ui_story_5075_50751202_39_dialog_content = "No entanto, por mais arrumado que possa ser, não gosto de ser ameaçado.",
  ui_story_5075_50751202_40_dialog_content = "Então-",
  ui_story_5075_50751202_41_dialog_content = "(Chen'ni acabou de decolar e voou até Yoh!)",
  ui_story_5075_50751202_42_dialog_content = "Tum, tum!",
  ui_story_5075_50751202_43_dialog_content = "<color=#e8d9bb>Chen'ni levanta o punho, batendo levemente na cabeça de Yoh.</color>",
  ui_story_5075_50751202_44_dialog_content = "Estou fazendo uma jogada. E você, o que vai fazer a respeito?",
  ui_story_5075_50751202_45_dialog_content = "Chen'ni?",
  ui_story_5075_50751202_46_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5075_50751202_47_dialog_content = "<color=#e8d9bb>Como se para expressar a raiva de Yoh, a superfície do mar se abre.</color>",
  ui_story_5075_50751202_48_dialog_content = "<color=#e8d9bb>Camadas sucessivas de ondas massivas se erguem. Em vez de diminuir, elas continuam crescendo ainda mais alto em meio ao tumulto ecoante do mar.</color>",
  ui_story_5075_50751202_49_dialog_content = "<color=#e8d9bb>A praia onde estamos está sendo rapidamente inundada.</color>",
  ui_story_5075_50751202_50_dialog_content = "Nesse ritmo, todos nós vamos nos afogar!",
  ui_story_5075_50751202_51_dialog_content = "Não se preocupe, sou bastante ágil na água. Eu vou te salvar se você começar a se afogar.",
  ui_story_5075_50751202_52_dialog_content = "Prefiro não começar esse processo em primeiro lugar!",
  ui_story_5075_50751202_53_dialog_content = "Ops, quase esqueci de vocês dois.",
  ui_story_5075_50751202_54_dialog_content = "(Estamos voando?)",
  ui_story_5075_50751202_55_dialog_content = "Meu poder sobrenatural é útil, não é?",
  ui_story_5075_50751202_56_dialog_content = "E quanto a Yoh?",
  ui_story_5075_50751202_57_dialog_content = "Ele não disse algo sobre <color=#FFB400>inundar a cidade</color>? Ele está a caminho de Haojin agora mesmo.",
  ui_story_5075_50751202_58_dialog_content = "I-Isso não é um acontecimento ainda pior?",
  ui_story_5075_50751202_59_dialog_content = "Por que você teve que provocá-lo dessa maneira?",
  ui_story_5075_50751202_60_dialog_content = "Não seja tão nervoso, PlayerName.",
  ui_story_5075_50751202_61_dialog_content = "Vivi por muito tempo e também tenho observado as criaturas em Longzhou por muito tempo.",
  ui_story_5075_50751202_62_dialog_content = "Seja Yoh ou você.",
  ui_story_5075_50751202_63_dialog_content = "Nem deveríamos subestimá-los.",
  ui_story_5075_50751301_1_dialog_content = "Vontade do céu—",
  ui_story_5075_50751301_2_dialog_content = "*Rugido*",
  ui_story_5075_50751301_3_dialog_content = "Urgh, derrube um e outro se levanta.",
  ui_story_5075_50751301_4_dialog_content = "A névoa negra na cidade está ficando ainda mais espessa. Estou começando a sentir falta do tempo em que não conseguia vê-la.",
  ui_story_5075_50751301_5_dialog_content = "Até mesmo uma corda não é suficiente para amarrar esses demônios frenéticos. Se ao menos eu tivesse uma maneira de expulsar o rancor de seus corpos...",
  ui_story_5075_50751301_6_dialog_content = "Abra caminhos! Eu tenho a cura!",
  ui_story_5075_50751301_7_dialog_content = "V-Você está dando remédio para os demônios?",
  ui_story_5075_50751301_8_dialog_content = "Não é óbvio?",
  ui_story_5075_50751301_9_dialog_content = "Mas a perda de controle deles não está sendo causada por uma doença, mas pela corrupção nascida do rancor—",
  ui_story_5075_50751301_10_dialog_content = "Então para você, médicos só podem tratar doenças?",
  ui_story_5075_50751301_11_dialog_content = "Já que essa energia precisa entrar em um fiendling para surtir efeito, ela pode ser equiparada a uma toxina.",
  ui_story_5075_50751301_12_dialog_content = "E existe uma cura para cada toxina.",
  ui_story_5075_50751301_13_dialog_content = "A névoa escura invadiu a cidade. Até o Tinytail... meu irmão está afetado.",
  ui_story_5075_50751301_14_dialog_content = "Mas eu consegui uma poção para equilibrar a Lumina interna do meu professor para ele. Ele melhorou muito depois de tomá-la.",
  ui_story_5075_50751301_15_dialog_content = "É por isso que eu corro ao ar livre e tento ajudar.",
  ui_story_5075_50751301_16_dialog_content = "Ha!",
  ui_story_5075_50751301_17_dialog_content = "Seu irmão... É isso mesmo? Então isso deve significar que você também é um <color=#FFB400>diabólico</color>.",
  ui_story_5075_50751301_18_dialog_content = "O que, você tem algo contra os demônios?",
  ui_story_5075_50751301_19_dialog_content = "De maneira nenhuma! Eu estava apenas pensando que você é um médico incrível.",
  ui_story_5075_50751301_20_dialog_content = "Você realmente acha isso? Bem, pelo menos você reconhece talento quando vê.",
  ui_story_5075_50751301_21_dialog_content = "Mas, na verdade, eu não sou tão especial...",
  ui_story_5075_50751301_22_dialog_content = "Eu tenho a cura comigo, mas os demônios estão à solta, e é difícil para mim administrá-la a eles.",
  ui_story_5075_50751301_23_dialog_content = "Deixe isso comigo!",
  ui_story_5075_50751301_24_dialog_content = "Vou nocautear cada demônio que eu ver e trazê-los até você para tratamento!",
  ui_story_5075_50751301_25_dialog_content = "Quieto, não tão alto!",
  ui_story_5075_50751301_26_dialog_content = "Escapamos sozinhos. Estaremos em apuros se formos pegos.",
  ui_story_5075_50751301_27_dialog_content = "Ah, entendi! Eu também fazia coisas assim quando era criança.",
  ui_story_5075_50751301_28_dialog_content = "Não se preocupe, vou ficar de olho e garantir que ninguém te veja.",
  ui_story_5075_50751301_29_dialog_content = "Meu nome é Luo Song, e este é meu parceiro, Ah Ding.",
  ui_story_5075_50751301_30_dialog_content = "*Rugido*",
  ui_story_5075_50751301_31_dialog_content = "Eu sou Liqing, e este é Tinytail, meu irmão mais velho.",
  ui_story_5075_50751301_32_dialog_content = "Ha!",
  ui_story_5075_50751301_33_dialog_content = "Um prazer trabalhar com você!",
  ui_story_5075_50751301_34_dialog_content = "Ha-uivo!",
  ui_story_5075_50751301_35_dialog_content = "Rangido!",
  ui_story_5075_50751301_36_dialog_content = "Apenas espere aqui por mim, Dr. Liqing. Eu vou dar uma olhada à frente!",
  ui_story_5075_50751301_37_dialog_content = "Ei, espere!",
  ui_story_5075_50751301_38_dialog_content = "Você não tem paciência?",
  ui_story_5075_50751301_39_dialog_content = "Ajuda... Eu preciso de ajuda!",
  ui_story_5075_50751301_40_dialog_content = "Fique atrás! O bastão na minha mão não é enfeite!",
  ui_story_5075_50751301_41_dialog_content = "Rangido!",
  ui_story_5075_50751301_42_dialog_content = "Vocês monstros, não pensem que somos fáceis de intimidar! Ha-ah!",
  ui_story_5075_50751301_43_dialog_content = "Parem, todos vocês! Urgh—",
  ui_story_5075_50751301_44_dialog_content = "Luo Song!",
  ui_story_5075_50751301_45_dialog_content = "O que você está fazendo? Quem mandou você se jogar no meio deles?",
  ui_story_5075_50751301_46_dialog_content = "Ótimo, agora você levou um golpe no ombro e um soco na barriga.",
  ui_story_5075_50751301_47_dialog_content = "Haha, isso é uma emergência, não é?",
  ui_story_5075_50751301_48_dialog_content = "Estou bem, então apenas dê a este demônio seu remédio enquanto eu o seguro.",
  ui_story_5075_50751301_49_dialog_content = "... Eu não consigo decidir se você é cuidadoso ou descuidado.",
  ui_story_5075_50751301_50_dialog_content = "Eu, quero dizer, desculpe... por atingir você...",
  ui_story_5075_50751301_51_dialog_content = "Não se preocupe com isso. Fui eu quem pulou entre vocês de repente.",
  ui_story_5075_50751301_52_dialog_content = "Mas, mas isso é um demônio! Por que você estava defendendo isso?",
  ui_story_5075_50751301_53_dialog_content = "Na verdade, ele estava defendendo você!",
  ui_story_5075_50751301_54_dialog_content = "Ai...",
  ui_story_5075_50751301_55_dialog_content = "É normal alguém reagir se um demônio os ataca. Mas saiba que não é intenção dos demônios atacar pessoas.",
  ui_story_5075_50751301_56_dialog_content = "Eles são todos vítimas inocentes, assim como você.",
  ui_story_5075_50751301_57_dialog_content = "E já que ninguém é culpado aqui, ninguém deve se machucar.",
  ui_story_5075_50751301_58_dialog_content = "Não é assim que as coisas deveriam ser?",
  ui_story_5075_50751301_59_dialog_content = "Tudo bem, este fiendling está muito melhor após a cura.",
  ui_story_5075_50751301_60_dialog_content = "Devemos ter coberto a maior parte de Haojin e curado a maioria dos demônios até agora.",
  ui_story_5075_50751301_61_dialog_content = "Grr.",
  ui_story_5075_50751301_62_dialog_content = "Está vendo isso? Eles estão sendo manipulados para atacar pessoas, e ficam perfeitamente dóceis uma vez que retornam ao normal.",
  ui_story_5075_50751301_63_dialog_content = "... Se isso for de outra pessoa, eu não vou comprar.",
  ui_story_5075_50751301_64_dialog_content = "Mas, já que está vindo de você, acho que é verdade.",
  ui_story_5075_50751301_65_dialog_content = "Obrigado por salvar minha vida! Vou espalhar a palavra e dizer a eles para procurar sua ajuda se um demônio prejudicar alguém.",
  ui_story_5075_50751301_66_dialog_content = "Sério? Isso seria muito apreciado, obrigado!",
  ui_story_5075_50751301_67_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5075_50751301_68_dialog_content = "O que está acontecendo? Por que o céu ficou tão escuro de repente?",
  ui_story_5075_50751301_69_dialog_content = "<color=#e8d9bb>Pitter-patter.</color>",
  ui_story_5075_50751301_70_dialog_content = "Está chovendo?",
  ui_story_5075_50751301_71_dialog_content = "Espere, isso não é chuva.",
  ui_story_5075_50751301_72_dialog_content = "<size=45>A noite também não está caindo. Uma enorme onda de maré está cobrindo o céu.</size>",
  ui_story_5075_50751301_73_dialog_content = "<size=45>O Haojin está sendo inundado?</size>",
  ui_story_5075_50751302_1_dialog_content = "<color=#e8d9bb>As ruas estão cheias de pessoas fugindo em pânico.</color>",
  ui_story_5075_50751302_2_dialog_content = "Espíritos malignos! Os espíritos malignos estão trazendo uma inundação para nos afogar a todos!",
  ui_story_5075_50751302_3_dialog_content = "CORRE—",
  ui_story_5075_50751302_4_dialog_content = "Donzela do Dragão, por favor, nos proteja. Donzela do Dragão, por favor, nos ajude...",
  ui_story_5075_50751302_5_dialog_content = "Isso não é mais um problema que podemos resolver sozinhos.",
  ui_story_5075_50751302_6_dialog_content = "Nos coloque no chão, Chen'ni! Pelo menos nos deixe ajudar essas pessoas a chegar em segurança!",
  ui_story_5075_50751302_7_dialog_content = "Senhora Chen'ni.",
  ui_story_5075_50751302_8_dialog_content = "Eu não acho que seja necessário.",
  ui_story_5075_50751302_9_dialog_content = "Mas…",
  ui_story_5075_50751302_10_dialog_content = "Ouça com atenção, PlayerName.",
  ui_story_5075_50751302_11_dialog_content = "Ai! Tropecei em um tijolo... Dói muito.",
  ui_story_5075_50751302_12_dialog_content = "Que lugar é esse... Onde estão mamãe e papai?",
  ui_story_5075_50751302_13_dialog_content = "*chora*",
  ui_story_5075_50751302_14_dialog_content = "Graah!",
  ui_story_5075_50751302_15_dialog_content = "Ajuda! Alguém me salve!",
  ui_story_5075_50751302_16_dialog_content = "Rangido!",
  ui_story_5075_50751302_17_dialog_content = "<color=#e8d9bb>Justo antes do golpe do Eclipsite acertar, o demônio corre e o afasta.</color>",
  ui_story_5075_50751302_18_dialog_content = "<color=#e8d9bb>O ataque desvia um pouco do curso e erra.</color>",
  ui_story_5075_50751302_19_dialog_content = "Espere, você é...",
  ui_story_5075_50751302_20_dialog_content = "Este não está alto o suficiente. Pegue outro!",
  ui_story_5075_50751302_21_dialog_content = "Fogos de artifício estouram, afugentando os demônios, banindo a má sorte de uma maneira alegre!",
  ui_story_5075_50751302_22_dialog_content = "Rangido...",
  ui_story_5075_50751302_23_dialog_content = "Você é daquela época...",
  ui_story_5075_50751302_24_dialog_content = "Graah!",
  ui_story_5075_50751302_25_dialog_content = "Cuidado!",
  ui_story_5075_50751302_26_dialog_content = "<color=#e8d9bb>O menino avança rapidamente, agarra o pequeno demônio e rola no chão coberto de lama.</color>",
  ui_story_5075_50751302_27_dialog_content = "Ah Ding! Ataque agora!",
  ui_story_5075_50751302_28_dialog_content = "Grr...",
  ui_story_5075_50751302_29_dialog_content = "Hã? Você não é aquele garoto de antes?",
  ui_story_5075_50751302_30_dialog_content = "Água... Está caindo aos montes!",
  ui_story_5075_50751302_31_dialog_content = "Rangido!",
  ui_story_5075_50751302_32_dialog_content = "Espere, não me deixe para trás!",
  ui_story_5075_50751302_33_dialog_content = "<color=#e8d9bb>É como se o céu estivesse desabando.</color>",
  ui_story_5075_50751302_34_dialog_content = "<color=#e8d9bb>Com um barulho estrondoso, ondas massivas finalmente estão se quebrando vindo de cima.</color>",
  ui_story_5075_50751302_35_dialog_content = "<color=#e8d9bb>Diante do poder avassalador, a pequena cidade construída pelos Aurorianos no chão é totalmente impotente.</color>",
  ui_story_5075_50751302_36_dialog_content = "Ahhhhhhh!",
  ui_story_5075_50751302_37_dialog_content = "...",
  ui_story_5075_50751302_38_dialog_content = "Eu, eu não estou morto? O que aconteceu?",
  ui_story_5075_50751302_39_dialog_content = "... Olhe lá em cima.",
  ui_story_5075_50751302_40_dialog_content = "Rangido!",
  ui_story_5075_50751302_41_dialog_content = "<color=#e8d9bb>O pequeno diabólico paira no ar, criando uma barreira invisível acima.</color>",
  ui_story_5075_50751302_42_dialog_content = "<color=#e8d9bb>Está segurando a onda bem na frente.</color>",
  ui_story_5075_50751302_43_dialog_content = "<color=#e8d9bb>Sob pressão, o fiendling treme, mas ainda levanta suas pequenas garras, mantendo aquele barreira protetora.</color>",
  ui_story_5075_50751302_44_dialog_content = "<color=#e8d9bb>Então, outra barreira aparece não muito longe.</color>",
  ui_story_5075_50751302_45_dialog_content = "*Rugido*",
  ui_story_5075_50751302_46_dialog_content = "<color=#e8d9bb>E então, mais um.</color>",
  ui_story_5075_50751302_47_dialog_content = "<color=#e8d9bb>As barreiras criadas pelos demônios se entrelaçam para cobrir uma vasta extensão.</color>",
  ui_story_5075_50751302_48_dialog_content = "<color=#e8d9bb>As ondas, pesadas como mil toneladas, pressionam a cidade de Haojin, mas não conseguem avançar um centímetro.</color>",
  ui_story_5075_50751302_49_dialog_content = "Isso...",
  ui_story_5075_50751302_50_dialog_content = "Esta terra nunca pertenceu apenas aos Aurorianos.",
  ui_story_5075_50751302_51_dialog_content = "Os demônios também têm que proteger sua casa.",
  ui_story_5075_50751302_52_dialog_content = "Mesmo que aquele velho Lin não tivesse procurado, Yoh teria verificado o selo para seus amigos.",
  ui_story_5075_50751302_53_dialog_content = "A maioria dos Aurorianos não quer admitir, mas os demônios também têm direito à terra.",
  ui_story_5075_50751302_54_dialog_content = "Está ouvindo, PlayerName?",
  ui_story_5075_50751302_55_dialog_content = "Sim, eu ouvi isso.",
  ui_story_5075_50751302_56_dialog_content = "E eu acho que todos deveriam ouvir isso também.",
  ui_story_5075_50751302_57_dialog_content = "Bem, eu certamente posso ajudar a divulgar a palavra.",
  ui_story_5075_50751302_58_dialog_content = "Vamos nessa!",
  ui_story_5075_50751302_59_option_content = "Varredura Psíquica!",
  ui_story_5075_50751302_60_dialog_content = "Esses bípedes, eles são ruins, sempre nos chutando quando nos veem.",
  ui_story_5075_50751302_61_dialog_content = "Mas esses bípedes também são bons, porque podem capturar presas deliciosas.",
  ui_story_5075_50751302_62_dialog_content = "Eles às vezes compartilham sua comida conosco.",
  ui_story_5075_50751302_63_dialog_content = "Espera, o que é isso?",
  ui_story_5075_50751302_64_dialog_content = "É essa a voz... dos demônios?",
  ui_story_5075_50751302_65_dialog_content = "Explodido por coisas aquecidas, assustador.",
  ui_story_5075_50751302_66_dialog_content = "Ser expulso, assustador.",
  ui_story_5075_50751302_67_dialog_content = "Este lugar também é a nossa casa.",
  ui_story_5075_50751302_68_dialog_content = "Mas nós também estamos assustados! Você sempre rouba coisas e estraga nossa comida.",
  ui_story_5075_50751302_69_dialog_content = "E você até usa magia que nós não podemos! N-Nós não sabemos como lidar com você!",
  ui_story_5075_50751302_70_dialog_content = "Esses de duas pernas, idiotas. Eles deixam coisas no canto, não conseguem encontrar, e nos culpam.",
  ui_story_5075_50751302_71_dialog_content = "Esses de duas pernas, tão burros. Eles deixam comida no quintal, mas não deixam um sinal, e acaba sendo comida por outros.",
  ui_story_5075_50751302_72_dialog_content = "Mas aqueles com duas pernas também são inteligentes. Da última vez que machuquei minha perna, eles usaram uma tábua para imobilizá-la, e ela melhorou.",
  ui_story_5075_50751302_73_dialog_content = "Estamos sendo muito rudes com eles...",
  ui_story_5075_50751302_74_dialog_content = "Sim, eles são chamados de demônios, mas na verdade, são apenas criaturas selvagens que recentemente pegaram o jeito das coisas.",
  ui_story_5075_50751302_75_dialog_content = "Eles são tanto bobos quanto inteligentes. São malvados, mas gentis. Eles nos atingem e pedem desculpas. Esses bípedes são realmente estranhos.",
  ui_story_5075_50751302_76_dialog_content = "Mas não há nada que possamos fazer.",
  ui_story_5075_50751302_77_dialog_content = "Nada que possamos fazer.",
  ui_story_5075_50751302_78_dialog_content = "Afinal, compartilhamos uma casa.",
  ui_story_5075_50751302_79_dialog_content = "A água está vindo, e eles não podem escapar.",
  ui_story_5075_50751302_80_dialog_content = "A água está vindo, e a casa não pode escapar também.",
  ui_story_5075_50751302_81_dialog_content = "A água é ruim. Vá embora—",
  ui_story_5075_50751302_82_dialog_content = "Fique longe de—",
  ui_story_5075_50751302_83_dialog_content = "<size=45>Nossa CASA!</size>",
  ui_story_5075_50751302_84_dialog_content = "<color=#e8d9bb>Na barreira que envolve toda a cidade, um brilho dourado repentino se agita, e as ondas que não conseguiam cair são dispersas pela força explosiva.</color>",
  ui_story_5075_50751302_85_dialog_content = "<color=#e8d9bb>Eles se transformam em uma chuva amarga, caindo silenciosamente sobre Haojin.</color>",
  ui_story_5075_50751302_86_dialog_content = "A chuva de agora... Foi você que fez isso, Chen'ni?",
  ui_story_5075_50751302_87_dialog_content = "O quê?",
  ui_story_5075_50751302_88_dialog_content = "Uh... Não importa.",
  ui_story_5075_50751302_89_dialog_content = "Esses pequenos demônios são realmente impressionantes.",
  ui_story_5075_50751302_90_dialog_content = "Agora tudo o que resta é lidar com Yoh.",
  ui_story_5075_50751302_91_dialog_content = "...",
  ui_story_5075_50751302_92_dialog_content = "Você também ouviu, certo? Os corações de todas essas pessoas e criaturas malignas?",
  ui_story_5075_50751302_93_dialog_content = "Eles podem cometer erros e discutir de vez em quando, ou até mesmo se machucar por todos os tipos de razões.",
  ui_story_5075_50751302_94_dialog_content = "Mas eles também trabalham juntos e se ajudam, para que possam coexistir no mundo.",
  ui_story_5075_50751302_95_dialog_content = "Todos eles são criaturas vivas nascidas em Longzhou. Eles não têm nenhum motivo para se odiarem, seja natural ou não.",
  ui_story_5075_50751302_96_dialog_content = "É por isso que, pelo menos, nenhum deles deveria ter que morrer para que o outro viva.",
  ui_story_5075_50751302_97_dialog_content = "Ah, uma coisinha...",
  ui_story_5075_50751302_98_dialog_content = "Entre todas aquelas vozes agora há pouco, ouvi um pedido de desculpas destinado apenas a você.",
  ui_story_5075_50751302_99_dialog_content = "Yoh.",
  ui_story_5075_50751302_100_dialog_content = "Desculpe.",
  ui_story_5075_50751401_1_dialog_content = "Peça desculpas.",
  ui_story_5075_50751401_2_dialog_content = "Por quê.",
  ui_story_5075_50751401_3_dialog_content = "Claro que é!",
  ui_story_5075_50751401_4_dialog_content = "Não. Remorso.",
  ui_story_5075_50751401_5_dialog_content = "Não... Urgh!",
  ui_story_5075_50751401_6_dialog_content = "Ele está voando de volta para a baía! Depois dele!",
  ui_story_5075_50751401_7_dialog_content = "Yoh!",
  ui_story_5075_50751401_8_dialog_content = "Abalado por uma ou duas palavras... Que covarde!",
  ui_story_5075_50751401_9_dialog_content = "Não... Argh!",
  ui_story_5075_50751401_10_dialog_content = "Se este é o nível de ódio que você é capaz, você pode muito bem me dar seu corpo!",
  ui_story_5075_50751401_11_dialog_content = "Yoh... Ele está resistindo ao controle da névoa negra!",
  ui_story_5075_50751401_12_dialog_content = "(Isso significa que podemos ter uma chance agora!)",
  ui_story_5075_50751401_13_dialog_content = "Humph. O corpo é decente, mas muito fraco em vontade.",
  ui_story_5075_50751401_14_dialog_content = "Que vergonha é para um demônio ser manipulado com facilidade pelos Aurorianos.",
  ui_story_5075_50751401_15_dialog_content = "Já faz muito tempo, Chen'ni.",
  ui_story_5075_50751401_16_dialog_content = "Na verdade, não. Foram apenas dois cochilos.",
  ui_story_5075_50751401_17_dialog_content = "Você ainda é seu velho eu.",
  ui_story_5075_50751401_18_dialog_content = "É bastante difícil para nós mudar, mesmo que queiramos.",
  ui_story_5075_50751401_19_dialog_content = "Por outro lado, o mundo mortal mudou muito, o que você definitivamente perdeu ficando no mar todo esse tempo.",
  ui_story_5075_50751401_20_dialog_content = "Eles têm pássaros mecânicos com rastreamento automático, pinturas ocidentais vibrantes e navios que podem atravessar o oceano.",
  ui_story_5075_50751401_21_dialog_content = "Humph. Não importa o quão bem eles criem, eles ainda não são mais do que criaturas inferiores.",
  ui_story_5075_50751401_22_dialog_content = "Você julga isso com base na expectativa de vida?",
  ui_story_5075_50751401_23_dialog_content = "Você não acha isso estranho?",
  ui_story_5075_50751401_24_dialog_content = "Os Aurorianos têm uma vida curta, mas são eles que agora dominam o continente.",
  ui_story_5075_50751401_25_dialog_content = "Pelo contrário, uma forma de vida superior como nós - de acordo com você - é raramente vista.",
  ui_story_5075_50751401_26_dialog_content = "Você precisa se rebaixar assim?",
  ui_story_5075_50751401_27_dialog_content = "Nós, nobres demônios, compartilhamos a mesma linhagem que os <color=#FFB400>Primordiais</color>.. Os aurorianos inferiores não merecem ser mencionados na mesma frase que nós!",
  ui_story_5075_50751401_28_dialog_content = "Mas agora, até mesmo um Aurorian sem poder poderia zombar e brincar com demônios!",
  ui_story_5075_50751401_29_dialog_content = "Você vai simplesmente ignorar a gravidade desta situação?",
  ui_story_5075_50751401_30_dialog_content = "O poder e a linhagem dos demônios reinam supremos sobre os aurorianos.",
  ui_story_5075_50751401_31_dialog_content = "Por que deveríamos nos rebaixar e compartilhar Longzhou com eles?",
  ui_story_5075_50751401_32_option_content = "Aumento de Força!",
  ui_story_5075_50751401_33_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5075_50751401_34_dialog_content = "Aumento de Força!",
  ui_story_5075_50751401_35_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5075_50751401_36_dialog_content = "(Não adianta, mal consigo sentir a presença do verdadeiro Yoh. Não há como alcançá-lo agora.)",
  ui_story_5075_50751401_37_dialog_content = "PlayerName, você pode enviar meus pensamentos para a mente de Yoh?",
  ui_story_5075_50751401_38_dialog_content = "Vou tentar o meu melhor, mas não tenho certeza se ele pode nos ouvir em sua condição.",
  ui_story_5075_50751401_39_dialog_content = "Tudo bem.",
  ui_story_5075_50751401_40_dialog_content = "Como habitantes das vastas profundezas do oceano, o peixe-serpente nunca se afogaria tão facilmente.",
  ui_story_5075_50751401_41_dialog_content = "Certo então, prepare-se.",
  ui_story_5075_50751401_42_option_content = "Aumento de Força!",
  ui_story_5075_50751401_43_dialog_content = "Yoh, consegue me ouvir?",
  ui_story_5075_50751401_44_dialog_content = "...",
  ui_story_5075_50751401_45_dialog_content = "Antes de eu partir, o mestre da guilda me disse que nunca havia se desculpado com você pessoalmente.",
  ui_story_5075_50751401_46_dialog_content = "Ele disse que, ao fazer isso, estaria forçando você a tolerar seu comportamento desprezível por causa da bondade do seu coração.",
  ui_story_5075_50751401_47_dialog_content = "Como ele fez isso deliberadamente e aceitou os despojos que vieram com o crime, ele não tem o direito de pedir perdão.",
  ui_story_5075_50751401_48_dialog_content = "Isso também é verdade para os Lins.",
  ui_story_5075_50751401_49_dialog_content = "Se você acredita que eu também sou um traidor contra a minha ancestralidade de peixe-serpente, então naturalmente isso também me inclui.",
  ui_story_5075_50751401_50_dialog_content = "Exerça sua vingança como achar melhor, e nós a aceitaremos.",
  ui_story_5075_50751401_51_dialog_content = "Mas deve ser de você e apenas de você, sem a manipulação de ninguém, pessoalmente.",
  ui_story_5075_50751401_52_dialog_content = "Ou o rancor mantido pelo peixe-serpente é tão insignificante que você o confiaria a outra pessoa?",
  ui_story_5075_50751401_53_dialog_content = "Não.",
  ui_story_5075_50751401_54_dialog_content = "Estou recebendo uma resposta!",
  ui_story_5075_50751401_55_dialog_content = "Yoh, vou tentar expulsar os pensamentos negativos que estão controlando seu corpo.",
  ui_story_5075_50751401_56_dialog_content = "Por favor, tente trabalhar comigo!",
  ui_story_5075_50751401_57_dialog_content = "PlayerName e Yuebai com certeza são lentos.",
  ui_story_5075_50751401_58_dialog_content = "O que você disse?",
  ui_story_5075_50751401_59_dialog_content = "Eu digo, não estou mais com vontade de conversar com você.",
  ui_story_5075_50751401_60_dialog_content = "Mas por que...",
  ui_story_5075_50751401_61_dialog_content = "Pare com a farsa. Você não é meu parente.",
  ui_story_5075_50751401_62_dialog_content = "Você não é meu parente.",
  ui_story_5075_50751401_63_dialog_content = "!",
  ui_story_5075_50751401_64_dialog_content = "Quando acordei pela primeira vez, tentei entrar em contato com meus companheiros.",
  ui_story_5075_50751401_65_dialog_content = "Mas todos ainda estavam dormindo. De Longzhou a Cloud Island, muito poucos responderam.",
  ui_story_5075_50751401_66_dialog_content = "Então, o único motivo pelo qual eu falei com você foi porque você tinha a vibração do dragão negro.",
  ui_story_5075_50751401_67_dialog_content = "Mas você não é aquele dragão negro, apenas uma coleção de emoções negativas que roubou algumas memórias do seu recipiente.",
  ui_story_5075_50751401_68_dialog_content = "Você deixou apenas arrogância no Dragão Negro e apenas ódio em Yoh.",
  ui_story_5075_50751401_69_dialog_content = "Isso porque são as únicas duas coisas que você tem.",
  ui_story_5075_50751401_70_dialog_content = "Você continua enfatizando o patriotismo, mas não tem nenhuma simpatia pelos demônios.",
  ui_story_5075_50751401_71_dialog_content = "Você se diz nobre, mas se agarra apenas à covardia.",
  ui_story_5075_50751401_72_dialog_content = "Você nem tem uma personalidade para falar e se esconde atrás de uma fachada.",
  ui_story_5075_50751401_73_dialog_content = "Você realmente acredita que pode reivindicar ser uma forma de vida superior?",
  ui_story_5075_50751401_74_dialog_content = "Qual é o problema em não ter personalidade? Eu sou um verdadeiro imortal!",
  ui_story_5075_50751401_75_dialog_content = "Mesmo as chamadas divindades como você não podem se comparar a mim em longevidade! Eu...",
  ui_story_5075_50751401_76_dialog_content = "Agora, antes que ele se recomponha!",
  ui_story_5075_50751401_77_option_content = "Aumento de Força!",
  ui_story_5075_50751401_78_dialog_content = "É. Meu. Corpo.",
  ui_story_5075_50751401_79_dialog_content = "Saia. Agora!",
  ui_story_5075_50751401_80_dialog_content = "Ugh!",
  ui_story_5075_50751401_81_dialog_content = "O quê?",
  ui_story_5075_50751401_82_dialog_content = "Graças à sua distração, Chen'ni, conseguimos encontrar!",
  ui_story_5075_50751401_83_dialog_content = "Agora só temos que ajudar Yoh a expulsá-lo de dentro...",
  ui_story_5075_50751401_84_dialog_content = "Nada disso!",
  ui_story_5075_50751402_1_dialog_content = "Tsc, tsc... Apenas uma casca inútil. O que importa se eu devolver para você?",
  ui_story_5075_50751402_2_dialog_content = "Este é o lugar onde meu corpo original está enterrado.",
  ui_story_5075_50751402_3_dialog_content = "Mesmo neste estado, eu não sou algo que você pode lidar!",
  ui_story_5075_50751402_4_dialog_content = "<color=#e8d9bb>O mar ao longe se agita novamente.</color>",
  ui_story_5075_50751402_5_dialog_content = "(Mas eu me recuso a ver Haojin debaixo d'água novamente.)",
  ui_story_5075_50751402_6_dialog_content = "Chen'ni, você disse que eu poderia usar isso para pedir um desejo, certo?",
  ui_story_5075_50751402_7_dialog_content = "Ah?",
  ui_story_5075_50751402_8_dialog_content = "Qual desejo você tem em mente?",
  ui_story_5075_50751402_9_dialog_content = "Aquilo não é um Aurorian ou um demônio, nem mesmo um Eclipsita.",
  ui_story_5075_50751402_10_dialog_content = "Não é nada além de uma massa desencarnada de intenção maligna.",
  ui_story_5075_50751402_11_dialog_content = "Ó Todo-Poderoso Dragão Divino Benevolente, você poderia, por favor, se livrar deste mal e devolver a paz a este lugar mais uma vez?",
  ui_story_5075_50751402_12_dialog_content = "Concedido.",
  ui_story_5075_50751402_13_dialog_content = "Tsk, tsk... Já se passaram oitocentos anos, e sua virtuosa Donzela Dragão não levantou um dedo quando eu inundei Haojin.",
  ui_story_5075_50751402_14_dialog_content = "As oferendas devem estar escassas, então ela sofre uma diminuição de poder—",
  ui_story_5075_50751402_15_dialog_content = "<color=#e8d9bb>Em um breve momento, um lótus dourado irradia brilho.</color>",
  ui_story_5075_50751402_16_dialog_content = "<color=#e8d9bb>Uma figura cristalina e etérea se ergue entre o mar e o céu.</color>",
  ui_story_5075_50751402_17_dialog_content = "<color=#e8d9bb>A esplêndida luz dourada se espalha como ondulações, e onde quer que alcance, espíritos malignos desaparecem no ar.</color>",
  ui_story_5075_50751402_18_dialog_content = "<color=#e8d9bb>Dentro da cidade de Haojin</color>",
  ui_story_5075_50751402_19_dialog_content = "Growl...",
  ui_story_5075_50751402_20_dialog_content = "Os espíritos malignos na cidade... Todos eles desapareceram?",
  ui_story_5075_50751402_21_dialog_content = "Olha! Olhe para o céu!",
  ui_story_5075_50751402_22_dialog_content = "É a Donzela do Dragão! A Donzela do Dragão se manifestou, nos ajudando a afastar o mal!",
  ui_story_5075_50751402_23_dialog_content = "<color=#e8d9bb>O remanescente do Eclipsite, assumindo a forma de um dragão negro, vira e corre sem qualquer hesitação.</color>",
  ui_story_5075_50751402_24_dialog_content = "<color=#e8d9bb>Apenas para a figura etérea imobilizá-lo com um simples estalar de dedos.</color>",
  ui_story_5075_50751402_25_dialog_content = "Se você acredita que estou enfraquecido, por que tem medo de lutar?",
  ui_story_5075_50751402_26_dialog_content = "Tsc, tsc, tsc...",
  ui_story_5075_50751402_27_dialog_content = "Nunca pensei que depois de tanto tempo, você ainda mantivesse esse nível de força.",
  ui_story_5075_50751402_28_dialog_content = "Mas você ainda não ganhou!",
  ui_story_5075_50751402_29_dialog_content = "Enquanto a força do Arquilorde Eclipsita permanecer, sou praticamente imortal!",
  ui_story_5075_50751402_30_dialog_content = "Se você destruir essa parte de mim, meu poder vai simplesmente se reagrupar e me trazer de volta à vida.",
  ui_story_5075_50751402_31_dialog_content = "Certamente você pode me eliminar uma ou duas vezes, mas consegue continuar me eliminando mil ou dez mil vezes?",
  ui_story_5075_50751402_32_dialog_content = "Eu...",
  ui_story_5075_50751402_33_dialog_content = "<color=#e8d9bb>Não consegue terminar a frase.</color>",
  ui_story_5075_50751402_34_dialog_content = "Coisas sem mente e forma não precisam existir no mundo.",
  ui_story_5075_50751402_35_dialog_content = "<color=#e8d9bb>A figura etérea esmaga isso.</color>",
  ui_story_5075_50751402_36_dialog_content = "<color=#e8d9bb>No instante seguinte, a névoa negra surge novamente sobre o mar.</color>",
  ui_story_5075_50751402_37_dialog_content = "<color=#e8d9bb>Ressentimento e Fluxo Escuro se fundem em um núcleo turvo no centro da névoa negra, tomando forma rapidamente.</color>",
  ui_story_5075_50751402_38_dialog_content = "Odeio admitir, mas ele está certo. Não há como protegermos este lugar para sempre.",
  ui_story_5075_50751402_39_dialog_content = "Sem uma solução permanente, não podemos garantir que ninguém se machucará na próxima vez, e nas vezes seguintes...",
  ui_story_5075_50751402_40_dialog_content = "De que lado você está, PlayerName?",
  ui_story_5075_50751402_41_dialog_content = "Mas...",
  ui_story_5075_50751402_42_dialog_content = "Por milênios, dizem que protegi os navios que navegavam pelo mar.",
  ui_story_5075_50751402_43_dialog_content = "Mas nos últimos cem anos antes de eu acordar, os mortais continuaram navegando.",
  ui_story_5075_50751402_44_dialog_content = "Eles são capazes de se proteger sem intervenção divina.",
  ui_story_5075_50751402_45_dialog_content = "Isso é o que eu amo ouvir!",
  ui_story_5075_50751402_46_dialog_content = "Essa voz...",
  ui_story_5075_50751402_47_dialog_content = "Xuan Ji!",
  ui_story_5075_50751402_48_dialog_content = "Há quanto tempo, PlayerName.",
  ui_story_5075_50751402_49_dialog_content = "Vejo que cheguei a tempo para o final.",
  ui_story_5075_50751402_50_dialog_content = "Deixe-me mostrar a você a última coisa legal do Reino Ye!",
  ui_story_5075_50751402_51_dialog_content = "Operação estável. Alvo bloqueado. Potência máxima.",
  ui_story_5075_50751402_52_dialog_content = "<size=45>Fogo!</size>",
  ui_story_5075_50751402_53_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5075_50751402_54_dialog_content = "<color=#e8d9bb>Uma deslumbrante luz dourada corta o mar, e o trovão artificial percorre a névoa negra a partir do centro.</color>",
  ui_story_5075_50751402_55_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5075_50751402_56_dialog_content = "<color=#e8d9bb>Antes que a névoa negra, tentando se condensar, possa preencher a brecha anterior, ela é estilhaçada mais uma vez.</color>",
  ui_story_5075_50751402_57_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5075_50751402_58_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5075_50751402_59_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5075_50751402_60_dialog_content = "<color=#e8d9bb>Após um forte bombardeio, o mar finalmente retorna à calma.</color>",
  ui_story_5075_50751402_61_dialog_content = "Não vai voltar?",
  ui_story_5075_50751402_62_dialog_content = "Certo. Ele desapareceu completamente sem deixar rastros antes de ter a chance de reagir.",
  ui_story_5075_50751402_63_dialog_content = "Essa é uma das suas pequenas invenções enquanto eu estava dormindo também?",
  ui_story_5075_50751402_64_dialog_content = "D-Não coloque sua cabeça no barril!",
  ui_story_5075_50751402_65_dialog_content = "Relaxa, eu desliguei.",
  ui_story_5075_50751402_66_dialog_content = "Você não tem negócios importantes para tratar de volta no Reino Ye, Xuan Ji?",
  ui_story_5075_50751402_67_dialog_content = "Sim, mas quem diria que eu receberia uma ligação da Princesa Dantang no meio do caminho?",
  ui_story_5075_50751402_68_dialog_content = "Percebi que Ji estava em um aperto maior, então eu comandei o <color=#FFB400>disparador arcano</color> mais avançado para reforço.",
  ui_story_5075_50751402_69_dialog_content = "Apenas para Sua Alteza estar ausente...",
  ui_story_5075_50751402_70_dialog_content = "Embora ver você já seja bom o suficiente, PlayerName!",
  ui_story_5075_50751402_71_dialog_content = "Dantang está na cidade agora mesmo.",
  ui_story_5075_50751402_72_dialog_content = "Já que tudo voltou ao normal agora, por que não volta conosco e passa o Festival da Primavera aqui em Haojin?",
  ui_story_5075_50751402_73_dialog_content = "Ah, eu me lembro de como é incrível a cerimônia de Ano Novo para repelir monstros em Haojin.",
  ui_story_5075_50751402_74_dialog_content = "Que pena que tenho que voltar correndo para Ye por negócios inacabados.",
  ui_story_5075_50751402_75_dialog_content = "Você também deveria voltar e não perder a celebração. Nos encontraremos mais tarde.",
  ui_story_5075_50751402_76_dialog_content = "Não se esqueça de dar meus cumprimentos à Princesa Dantang.",
  ui_story_5075_50751402_77_dialog_content = "Tudo bem então, boa sorte com seu negócio oficial.",
  ui_story_5075_50751402_78_dialog_content = "Vou enviar um pássaro mecânico se algo estiver acontecendo!",
  ui_story_5075_50751402_79_dialog_content = "Hmm, isso parece uma decepção.",
  ui_story_5075_50751402_80_dialog_content = "Vim de Ye com o blaster arcano apenas para uma breve aparição.",
  ui_story_5075_50751402_81_dialog_content = "Mas mesmo que ninguém me aclamasse como um herói naquela época, estou ganhando um séquito agora.",
  ui_story_5075_50751402_82_dialog_content = "Senhora Xuan Ji.",
  ui_story_5075_50751402_83_dialog_content = "Você pegou armas altamente classificadas sem permissão.",
  ui_story_5075_50751402_84_dialog_content = "E você até contrabandeou essas armas para outro reino. Agora você é suspeito de traição.",
  ui_story_5075_50751402_X84_dialog_content = "Bem, é discutível se vocês representam o Reino Ye...",
  ui_story_5075_50751402_85_dialog_content = "O rei te enviou?",
  ui_story_5075_50751402_86_dialog_content = "De fato, nós, sob o comando secreto do <color=#FFB400>Rei de Ye</color>, vamos prendê-lo. Você vai desafiar essa ordem?",
  ui_story_5075_50751402_87_dialog_content = "... De jeito nenhum.",
  ui_story_5075_50751402_88_dialog_content = "Eu sou um cidadão de Ye, sem mencionar um ex-conselheiro de estado e luminary.",
  ui_story_5075_50751402_89_dialog_content = "Recuso-me a seguir alguém que prejudique os interesses de Ye, mas nunca desobedecerei à ordem do rei.",
  ui_story_5075_50751402_90_dialog_content = "Eu me declaro culpado.",
  ui_story_5075_50751402_91_dialog_content = "...",
  ui_story_5075_50751402_92_dialog_content = "Vamos lá, não fique tão desapontado.",
  ui_story_5075_50751402_93_dialog_content = "Esta é a minha primeira vez passando o Ano Novo na prisão, então eu agradeceria se você me avisasse quando eu não seguir o protocolo.",
  ui_story_5075_50751501_1_dialog_content = "<color=#e8d9bb>Bang! Bang!</color>",
  ui_story_5075_50751501_2_dialog_content = "Uau, um show de fogos de artifício!",
  ui_story_5075_50751501_3_dialog_content = "Após apenas uma noite, a cidade inteira está fervilhando de festividade.",
  ui_story_5075_50751501_4_dialog_content = "Os espíritos malignos foram purgados e o mal-entendido entre as pessoas e os demônios foi resolvido.",
  ui_story_5075_50751501_5_dialog_content = "Todos devem poder aproveitar um Festival de Primavera despreocupado amanhã.",
  ui_story_5075_50751501_6_dialog_content = "Yoh também está voltando para o mar?",
  ui_story_5075_50751501_7_dialog_content = "Sim. Ele diz que precisa ficar sozinho por algum tempo para decidir o que fazer a seguir.",
  ui_story_5075_50751501_8_dialog_content = "Você acha que ele vai se vingar da Família Lin?",
  ui_story_5075_50751501_9_dialog_content = "Não tenho certeza.",
  ui_story_5075_50751501_10_dialog_content = "Mas, pelo menos, conseguimos resolver nossas diferenças passadas. Quanto ao futuro...",
  ui_story_5075_50751501_11_dialog_content = "Essa é uma questão para amanhã, você não acha?",
  ui_story_5075_50751501_12_dialog_content = "\"Merry Ano Novo,\" certo?",
  ui_story_5075_50751501_13_dialog_content = "Li Tianxian não estava mentindo afinal. Este antigo encantamento realmente funciona!",
  ui_story_5075_50751501_14_dialog_content = "?",
  ui_story_5075_50751501_15_dialog_content = "... Hehe.",
  ui_story_5075_50751501_16_dialog_content = "P-Por que você está rindo, Yuebai? Isso não é algum tipo de piada, é?",
  ui_story_5075_50751501_17_dialog_content = "Não.",
  ui_story_5075_50751501_18_dialog_content = "Realmente é um encantamento poderoso.",
  ui_story_5075_50751501_19_dialog_content = "Ainda tenho assuntos para tratar com a família Lin. Até a próxima.",
  ui_story_5075_50751501_20_dialog_content = "Claro, vejo você mais tarde.",
  ui_story_5075_50751501_21_dialog_content = "<color=#e8d9bb>Craque e pop!</color>",
  ui_story_5075_50751501_22_dialog_content = "O que houve?",
  ui_story_5075_50751501_23_dialog_content = "A cerimônia de repelir monstros está vindo para cá!",
  ui_story_5075_50751501_24_dialog_content = "Chen'ni? Onde você esteve todo esse tempo?",
  ui_story_5075_50751501_25_dialog_content = "E quando você conseguiu todos esses lanches?",
  ui_story_5075_50751501_26_dialog_content = "Eu meio que dei uma volta com meus chifres de dragão à mostra, e os vendedores simplesmente me encheram com esses!",
  ui_story_5075_50751501_27_dialog_content = "Ah, é verdade, PlayerName não tem chifres nem cauda.",
  ui_story_5075_50751501_28_dialog_content = "Não fique triste. Vou dividir o espólio com você.",
  ui_story_5075_50751501_29_dialog_content = "Obrigada, mas isso não me incomoda muito.",
  ui_story_5075_50751501_30_dialog_content = "Olha, Luo Song é um dos artistas.",
  ui_story_5075_50751501_31_dialog_content = "Sem brincadeira! E olha, tem um monte de demônios com ele também!",
  ui_story_5075_50751501_32_dialog_content = "Fogos de artifício estouram, afugentando monstros, banindo a má sorte de uma maneira alegre.",
  ui_story_5075_50751501_33_dialog_content = "As bênçãos se desdobram com presságios auspiciosos. Recebendo a primavera, a felicidade ilumina cada rosto!",
  ui_story_5075_50751501_34_dialog_content = "Espere, eu pensei que eles deveriam estar afugentando monstros? Por que os demônios também são perseguidores?",
  ui_story_5075_50751501_35_dialog_content = "Eles mudaram este ano - não estão mais afugentando demônios, mas espíritos malignos.",
  ui_story_5075_50751501_36_dialog_content = "Você não viu a manifestação da Donzela do Dragão na noite passada? Ela erradicou todos os espíritos malignos, deixando os demônios intocados.",
  ui_story_5075_50751501_37_dialog_content = "Isso significa que até mesmo a Donzela do Dragão considera os demônios inofensivos, certo?",
  ui_story_5075_50751501_38_dialog_content = "Escute bem! Você precisa aprender a trabalhar em equipe se quiser derrotar um oponente poderoso!",
  ui_story_5075_50751501_39_dialog_content = "Ao combinar suas forças únicas, seu poder aumentará dramaticamente!",
  ui_story_5075_50751501_40_dialog_content = "Tudo bem Ah Ding, peça ao seu novo amigo para te ajudar a mostrar a todos o que eu quero dizer!",
  ui_story_5075_50751501_41_dialog_content = "Ha!",
  ui_story_5075_50751501_42_dialog_content = "*Rugido*",
  ui_story_5075_50751501_43_dialog_content = "Estou vendo coisas?",
  ui_story_5075_50751501_44_dialog_content = "Por que aquele gato parece tão familiar?",
  ui_story_5075_50751501_45_dialog_content = "<color=#e8d9bb>Craque e pop!</color>",
  ui_story_5075_50751501_46_dialog_content = "Fogos de artifício estouram, espantando monstros... Ai!",
  ui_story_5075_50751501_47_dialog_content = "Desculpe, eu não estava olhando para onde estava indo e esbarrei em você... Ah.",
  ui_story_5075_50751501_48_dialog_content = "Sim?",
  ui_story_5075_50751501_49_dialog_content = "Ah, é o garoto que estava implicando com aquele pequeno demônio mais cedo.",
  ui_story_5075_50751501_50_dialog_content = "Então, eh... Senhorita, você também é um demônio, não é?",
  ui_story_5075_50751501_51_dialog_content = "Aqui está um doce para você!",
  ui_story_5075_50751501_52_dialog_content = "E... se você conhece algum demônio para quem fomos malvados, por favor, diga a eles que eu sinto muito!",
  ui_story_5075_50751501_53_dialog_content = "Ele fugiu...",
  ui_story_5075_50751501_54_dialog_content = "Acho que as opiniões das pessoas sobre os demônios estão realmente começando a mudar.",
  ui_story_5075_50751501_55_dialog_content = "Hmm... Uau!",
  ui_story_5075_50751501_56_dialog_content = "É muito doce.",
  ui_story_5075_50751501_57_dialog_content = "Achei que ver isso te deixaria feliz, Chen'ni.",
  ui_story_5075_50751501_58_dialog_content = "Estou feliz.",
  ui_story_5075_50751501_59_dialog_content = "Então por que parece que...",
  ui_story_5075_50751501_60_dialog_content = "A sua felicidade não é diferente da felicidade que você sentiu ontem ou mesmo no dia anterior.",
  ui_story_5075_50751501_61_dialog_content = "Bem, é assim que é no mundo.",
  ui_story_5075_50751501_62_dialog_content = "As pessoas se voltam contra os demônios um dia por medo, e no dia seguinte os tratam bem por culpa.",
  ui_story_5075_50751501_63_dialog_content = "Quem sabe como eles verão os diabretes amanhã.",
  ui_story_5075_50751501_64_dialog_content = "Você pode ter conseguido um lanche delicioso ontem, um horrível hoje e, então, um delicioso novamente amanhã.",
  ui_story_5075_50751501_65_dialog_content = "Sempre haverá o bom e o mau, mas o bom não permanecerá bom, e o mau não permanecerá mau.",
  ui_story_5075_50751501_66_dialog_content = "Acho que gosto assim.",
  ui_story_5075_50751501_67_dialog_content = "Eu... não posso dizer que realmente entendo o que você está sentindo, Chen'ni.",
  ui_story_5075_50751501_68_dialog_content = "Mas depois de tudo pelo que passamos, acho que faz um pouco mais de sentido agora.",
  ui_story_5075_50751501_69_dialog_content = "Em seus olhos, todos os seres vivos são exatamente iguais. Não faz diferença para você se são pessoas, demônios ou qualquer outra coisa.",
  ui_story_5075_50751501_70_dialog_content = "Todos os seres têm um significado por trás de sua existência.",
  ui_story_5075_50751501_71_dialog_content = "E porque você respeita esse significado, tenta não interferir no nosso mundo.",
  ui_story_5075_50751501_72_dialog_content = "Não é que você não se importa conosco, mas sim que se importa igualmente com todos.",
  ui_story_5075_50751501_73_dialog_content = "Se for esse o caso, tenho certeza de que nossos problemas nos últimos dias devem ter parecido extremamente insignificantes para você.",
  ui_story_5075_50751501_74_dialog_content = "Esperamos que não tenhamos te decepcionado muito.",
  ui_story_5075_50751501_75_dialog_content = "Então, o que você vai fazer agora, Chen'ni?",
  ui_story_5075_50751501_76_dialog_content = "Saí porque fui acordada de forma grosseira.",
  ui_story_5075_50751501_77_dialog_content = "Então, vou voltar a dormir daqui a pouco.",
  ui_story_5075_50751501_78_dialog_content = "Tão cedo?",
  ui_story_5075_50751501_79_dialog_content = "Emissário! O rei está pedindo sua presença no palácio.",
  ui_story_5075_50751501_80_dialog_content = "Ah, claro.",
  ui_story_5075_50751501_81_dialog_content = "Chen'ni, quer vir junto? Chen'ni?",
  ui_story_5075_50751501_82_dialog_content = "Já foi, huh?",
  ui_story_5075_50751501_83_dialog_content = "Obrigado por tudo, PlayerName.",
  ui_story_5075_50751501_84_dialog_content = "Desta vez—",
  ui_story_5075_50751501_85_dialog_content = "PlayerName! PlayerName!",
  ui_story_5075_50751501_86_dialog_content = "Ouvi tudo de Dantang. Ela disse que você assumiu o comando em uma crise, demonstrando uma sabedoria e coragem incomparáveis.",
  ui_story_5075_50751501_87_dialog_content = "Não só você expôs os vilões no tribunal do Reino Ji, mas a recuada oportuna da enchente de ontem também é creditada a você!",
  ui_story_5075_50751501_88_dialog_content = "Acredito que não exagerei na conta dessa forma, Príncipe Herdeiro.",
  ui_story_5075_50751501_89_dialog_content = "De qualquer forma, eu sei agora que PlayerName é um grande herói!",
  ui_story_5075_50751501_90_dialog_content = "Você é incrível, herói! <size=45>Eu quero me casar com PlayerName!</size>",
  ui_story_5075_50751501_91_dialog_content = "<size=45>... O quê?</size>",
  ui_story_5075_50751501_92_dialog_content = "Como diz o ditado, marido e esposa são como um só. Com uma noiva incrível como você, com certeza serei um herói também!",
  ui_story_5075_50751501_93_dialog_content = "<size=45>Hmm!</size>",
  ui_story_5075_50751501_94_dialog_content = "Alguém escolte o príncipe de volta imediatamente!",
  ui_story_5075_50751501_95_dialog_content = "Diga ao tutor para ensinar a ele o significado do casamento e fazê-lo parar com todo esse absurdo que eu quase acreditei...",
  ui_story_5075_50751501_96_dialog_content = "No entanto, seus outros comentários não estão errados.",
  ui_story_5075_50751501_97_dialog_content = "A crise em Haojin foi um erro de cálculo da minha parte, e graças a você o desastre foi evitado.",
  ui_story_5075_50751501_98_dialog_content = "Portanto, sinta-se à vontade para me dizer o que quiser, e eu certamente concederei.",
  ui_story_5075_50751501_99_dialog_content = "Nesse caso, Dantang e eu gostaríamos de compartilhar nosso plano com você para melhorar as relações entre nossas duas terras!",
  ui_story_5075_50751501_100_dialog_content = "Isso é tudo? Você não deseja ouro, tesouros ou posições de poder?",
  ui_story_5075_50751501_101_dialog_content = "Para ser honesto, isso não é totalmente falso. Mas eu vim para Longzhou como o enviado oficial de Astra.",
  ui_story_5075_50751501_102_dialog_content = "Completar minha missão é minha maior prioridade.",
  ui_story_5075_50751501_103_dialog_content = "Hahaha, para um jovem talentoso como você, de certa forma, não quero deixar você voltar.",
  ui_story_5075_50751501_104_dialog_content = "Mas já que você não quer ficar em Longzhou, que tal isso?",
  ui_story_5075_50751501_105_dialog_content = "Eu aqui declaro você um Cidadão Honorário do Reino de Ji.",
  ui_story_5075_50751501_106_dialog_content = "Não importa para onde você vá ou o que faça daqui para frente, o Reino de Ji sempre o receberá de braços abertos.",
  ui_story_5075_50751501_107_dialog_content = "Obrigado, Senhor!",
  ui_story_5075_50751501_108_dialog_content = "Ufa... Passamos tanto tempo no palácio, e está ficando tarde.",
  ui_story_5075_50751501_109_dialog_content = "Após a prisão do mordomo, eles também se livraram de todos aqueles guardas e empregadas.",
  ui_story_5075_50751501_110_dialog_content = "Acho que esta é a primeira vez que estou completamente sozinho aqui.",
  ui_story_5075_50751501_111_dialog_content = "... Está tão quieto.",
  ui_story_5075_50751501_112_dialog_content = "Agora que as coisas finalmente se acalmaram, não sei o que fazer comigo mesmo.",
  ui_story_5075_50751501_113_dialog_content = "Ah sim, o Festival da Primavera é amanhã.",
  ui_story_5075_50751501_114_dialog_content = "Pelo que ouvi, todas as famílias em Longzhou vão passar a noite toda acordadas hoje enquanto comem e se divertem juntas.",
  ui_story_5075_50751501_115_dialog_content = "É a maneira deles de dizer adeus ao último ano e dar as boas-vindas ao ano novo.",
  ui_story_5075_50751501_116_dialog_content = "Talvez eu devesse fazer algo assim também... Nah, não tem sentido ficar acordado a noite toda sozinho.",
  ui_story_5075_50751501_117_dialog_content = "Eu me pergunto o que todos estão fazendo...",
  ui_story_5075_50751501_118_dialog_content = "Esperando que PlayerName me note.",
  ui_story_5075_50751501_119_dialog_content = "Huh? Qu-Quando você entrou aqui?",
  ui_story_5075_50751501_120_dialog_content = "Eu estava aqui antes de você voltar.",
  ui_story_5075_50751501_121_dialog_content = "Apenas para te ver vagando sem prestar atenção em nada, então eu tive que me mostrar.",
  ui_story_5075_50751501_122_dialog_content = "Então você viu isso, hein...",
  ui_story_5075_50751501_123_dialog_content = "Achei que você já tivesse ido.",
  ui_story_5075_50751501_124_dialog_content = "Você disse que estava voltando para o mar em um tempo, afinal.",
  ui_story_5075_50751501_125_dialog_content = "Isso mesmo. Não planejo ficar muito tempo.",
  ui_story_5075_50751501_126_dialog_content = "Vou voltar em algumas décadas.",
  ui_story_5075_50751501_127_dialog_content = "Espere, o quê? Algumas décadas são apenas \"um tempo\" para você?",
  ui_story_5075_50751501_128_dialog_content = "É muito rápido?",
  ui_story_5075_50751501_129_dialog_content = "Eu gosto de sair com você.",
  ui_story_5075_50751501_130_dialog_content = "Então, se você não se importa, é possível que eu fique por aqui por uns cem anos ou dois.",
  ui_story_5075_50751501_131_dialog_content = "... Desculpe, esqueci que os principais fiendlings têm um senso de tempo completamente diferente do nosso.",
  ui_story_5075_50751501_132_dialog_content = "Mas como é que você não tem nada aqui, PlayerName?",
  ui_story_5075_50751501_133_dialog_content = "Deve ser hora para uma refeição de Ano Novo Eve.",
  ui_story_5075_50751501_134_dialog_content = "Haha, acho que esqueci.",
  ui_story_5075_50751501_135_dialog_content = "Bem, estas são folhas de tofu que acabei de receber como oferta. Pegue.",
  ui_story_5075_50751501_136_dialog_content = "Obrigado... Uh, folhas de tofu?",
  ui_story_5075_50751501_137_dialog_content = "PlayerName! Chen'ni!",
  ui_story_5075_50751501_138_dialog_content = "Onde estão vocês dois?",
  ui_story_5075_50751501_139_dialog_content = "É aquele Luo Song?",
  ui_story_5075_50751501_140_dialog_content = "Luo Song! Por aqui!",
  ui_story_5075_50751501_141_dialog_content = "Ah, aí estão vocês! Fico feliz por finalmente ter encontrado vocês dois.",
  ui_story_5075_50751501_142_dialog_content = "Eu deveria ter perguntado onde você estava hospedado antes de eu partir.",
  ui_story_5075_50751501_143_dialog_content = "Espere, você esteve andando pelas ruas gritando nossos nomes esse tempo todo?",
  ui_story_5075_50751501_144_dialog_content = "Haha, eu sei que não foi a maneira mais inteligente de procurar por você, mas deu certo, não deu?",
  ui_story_5075_50751501_145_dialog_content = "Depois de tudo que passamos, você não se importa de me deixar comemorar o ano novo com você, certo?",
  ui_story_5075_50751501_146_dialog_content = "Claro que não!",
  ui_story_5075_50751501_147_dialog_content = "Fico feliz em ouvir isso.",
  ui_story_5075_50751501_148_dialog_content = "De qualquer forma, ajudei uma senhora a mover algumas coisas mais cedo, e ela me deu este saco de aipo como agradecimento pelo meu trabalho.",
  ui_story_5075_50751501_149_dialog_content = "Pelo menos, podemos usá-lo para preparar algo para esta noite.",
  ui_story_5075_50751501_150_dialog_content = "Oh céus, este lugar está ainda mais deserto do que a minha barraca de adivinhação.",
  ui_story_5075_50751501_151_dialog_content = "Li Tianxian, você também está aqui?",
  ui_story_5075_50751501_152_dialog_content = "Para dar uma de parasita... quero dizer, para verificar como você está, já que está em uma terra estrangeira e tudo mais.",
  ui_story_5075_50751501_153_dialog_content = "Não acredito que você nem sequer preparou uma refeição. Acho que você tem sorte de eu estar aqui.",
  ui_story_5075_50751501_154_dialog_content = "Aqui, um presente de Ano Novo de mim para você.",
  ui_story_5075_50751501_155_dialog_content = "Eu aprecio o gesto e tudo mais, mas por que me dar um monte de vegetais selvagens?",
  ui_story_5075_50751501_156_dialog_content = "Isso não é um vegetal comum. É a bolsa do pastor e é difícil de encontrar no inverno.",
  ui_story_5075_50751501_157_dialog_content = "Tive que pegar o lote de uma estufa, e isso me custou todo o lucro que fiz com as figuras de açúcar.",
  ui_story_5075_50751501_158_dialog_content = "Representa fortuna e riqueza, então seus cofres estarão cheios durante todo o ano!",
  ui_story_5075_50751501_159_dialog_content = "E você também tem folhas de tofu. Isso é auspicioso e traz prosperidade para as gerações futuras.",
  ui_story_5075_50751501_160_dialog_content = "O aipo também não é ruim. Significa dinheiro através do trabalho duro.",
  ui_story_5075_50751501_161_dialog_content = "Vem me dar uma mão, PlayerName—",
  ui_story_5075_50751501_162_dialog_content = "Um membro da guilda nos enviou um carrinho inteiro de raízes de lótus frescas. Imaginei que você não preparou nenhum ingrediente esta noite, então trouxe alguns para você.",
  ui_story_5075_50751501_163_dialog_content = "Uma carga inteira de carrinho?",
  ui_story_5075_50751501_164_dialog_content = "Apenas pegue. Tudo de qualidade, você sabe.",
  ui_story_5075_50751501_165_dialog_content = "Vejo sinais apontando para uma boa sorte para você em todos os lugares.",
  ui_story_5075_50751501_166_dialog_content = "Você acha que tudo é auspicioso, não é?",
  ui_story_5075_50751501_167_dialog_content = "É Ano Novo, claro que tudo é auspicioso.",
  ui_story_5075_50751501_168_dialog_content = "Eu conseguia ouvir o Li enganando a uma milha de distância.",
  ui_story_5075_50751501_169_dialog_content = "Embora seja bom falar felicitamente no Ano Novo Eve.",
  ui_story_5075_50751501_170_dialog_content = "Faz algum tempo, PlayerName.",
  ui_story_5075_50751501_171_dialog_content = "Dantang? Jiu? Você não deveria estar celebrando o ano novo de volta ao palácio?",
  ui_story_5075_50751501_172_dialog_content = "Devemos.",
  ui_story_5075_50751501_173_dialog_content = "Mas por causa do seu mérito nos últimos dias, PlayerName, o rei me designou para uma tarefa especial.",
  ui_story_5075_50751501_174_dialog_content = "Vou garantir que você tenha um Ano Novo agradável.",
  ui_story_5075_50751501_175_dialog_content = "Há carrinhos de comida do lado de fora do palácio. Eu vou cozinhar e fazer as refeições apropriadas para o feriado.",
  ui_story_5075_50751501_176_dialog_content = "Ah, eu gostaria de oferecer minha bênção também.",
  ui_story_5075_50751501_177_dialog_content = "Com este prato de lírios dourados, PlayerName...",
  ui_story_5075_50751501_178_dialog_content = "Desejo-lhe um futuro brilhante.",
  ui_story_5075_50751501_179_dialog_content = "Acho que vou te oferecer vagens de ervilha. Elas simbolizam uma colheita farta em Longzhou.",
  ui_story_5075_50751501_180_dialog_content = "Uau, vejo tantas pessoas!",
  ui_story_5075_50751501_181_dialog_content = "E eu estava preocupado que PlayerName fosse passar o Ano Novo Eve sozinho.",
  ui_story_5075_50751501_182_dialog_content = "É bom para o nosso jovem amigo ser tão popular.",
  ui_story_5075_50751501_183_dialog_content = "Zhong Xu! Liqing! Vocês também estão aqui!",
  ui_story_5075_50751501_184_dialog_content = "De onde veio toda essa comida na mesa? Ah, eu sei!",
  ui_story_5075_50751501_185_dialog_content = "Você está fazendo o Dez Cenários, não está?",
  ui_story_5075_50751501_186_dialog_content = "O que seria?",
  ui_story_5075_50751501_187_dialog_content = "É um famoso prato tradicional de Ji com dezenas de vegetais finamente fatiados e refogados.",
  ui_story_5075_50751501_188_dialog_content = "Isso combina todos os auspícios em um prato.",
  ui_story_5075_50751501_189_dialog_content = "É uma necessidade do Festival da Primavera em Ji.",
  ui_story_5075_50751501_190_dialog_content = "Mas eu vejo que ainda está faltando algo aqui.",
  ui_story_5075_50751501_191_dialog_content = "Permita-me contribuir com mostarda para a causa e desejar a todos uma ótima carreira.",
  ui_story_5075_50751501_192_dialog_content = "Vou acrescentar um pouco de erva-daninha pequena para garantir.",
  ui_story_5075_50751501_193_dialog_content = "Não é apenas um legume, mas também uma erva anti-toxina.",
  ui_story_5075_50751501_194_dialog_content = "Você realmente está testando minhas habilidades culinárias com esses ingredientes exóticos.",
  ui_story_5075_50751501_195_dialog_content = "Oh, isso não será um desafio para você de forma alguma, Sua Alteza.",
  ui_story_5075_50751501_196_dialog_content = "Você tem certeza, Jiu? Por que não vem me dar uma mão na cozinha então?",
  ui_story_5075_50751501_197_dialog_content = "Eu vou ajudar também.",
  ui_story_5075_50751501_198_dialog_content = "Deixe a degustação comigo.",
  ui_story_5075_50751501_199_dialog_content = "Eu posso fazer a degustação!",
  ui_story_5075_50751501_200_dialog_content = "Tudo bem, eu não posso lutar com você por isso, então por favor, fique à vontade.",
  ui_story_5075_50751501_201_dialog_content = "Vou sair e organizar os ingredientes. Apenas me diga o que você precisa e eu trarei.",
  ui_story_5075_50751501_202_dialog_content = "Também trouxe algumas decorações para colocar por todo o quarto.",
  ui_story_5075_50751501_203_dialog_content = "Isso é maravilhoso. Eu estava pensando que este lugar poderia usar mais festividade!",
  ui_story_5075_50751501_204_dialog_content = "Aqui vem os Dez Cenários que todos ajudaram a criar.",
  ui_story_5075_50751501_205_dialog_content = "Antes que o sino do Templo da Donzela Dragão toque em alguns minutos para oficialmente dar início ao Ano Novo...",
  ui_story_5075_50751501_206_dialog_content = "Minha gratidão por tudo que você fez por mim no último ano, PlayerName.",
  ui_story_5075_50751501_207_dialog_content = "Não sou bom com palavras, então vou apenas dizer \"Obrigado!\"",
  ui_story_5075_50751501_208_dialog_content = "Agradeço pelos seus serviços no ano passado e aguardo o seu patrocínio no próximo ano.",
  ui_story_5075_50751501_209_dialog_content = "Sou grato pela sua ajuda em nossas jornadas anteriores, meu jovem amigo. Desejo-lhe um lindo novo ano.",
  ui_story_5075_50751501_210_dialog_content = "Agradeço por tudo. Mantenha-se saudável para não precisar me visitar para tratamento!",
  ui_story_5075_50751501_211_dialog_content = "Podemos ter acabado de nos conhecer, mas já te considero um bom amigo.",
  ui_story_5075_50751501_212_dialog_content = "Brindemos ao novo ano! Desejo a você a força necessária para derrotar qualquer espírito maligno que cruzar seu caminho!",
  ui_story_5075_50751501_213_dialog_content = "Saúde, e Feliz Ano Novo!",
  ui_story_5075_50751501_214_dialog_content = "*golpe*",
  ui_story_5075_50751501_215_dialog_content = "Ei, eu nem tomei um gole! Não saia correndo com isso...",
  ui_story_5075_50751501_216_dialog_content = "PlayerName, PlayerName.",
  ui_story_5075_50751501_217_dialog_content = "Qual é o problema, Chen'ni?",
  ui_story_5075_50751501_218_dialog_content = "Abaixe a cabeça.",
  ui_story_5075_50751501_219_dialog_content = "Ok, mas o que você está fazendo?",
  ui_story_5075_50751501_220_dialog_content = "Deixe-me acariciar você.",
  ui_story_5075_50751501_221_dialog_content = "Seja feliz e contente todos os dias.",
  ui_story_5075_50751501_222_dialog_content = "Isso vem diretamente de uma divindade, então você pode confiar nisso!",
  ui_story_5075_50751501_223_dialog_content = "<color=#e8d9bb>Dong—dong—</color>",
  ui_story_5075_50751501_224_dialog_content = "<color=#e8d9bb>O sino do Templo da Donzela Dragão toca das Montanhas do Sul, ecoando por toda a cidade.</color>",
  ui_story_5075_50751501_225_dialog_content = "<color=#e8d9bb>Cem e oito vezes ele toca, limpando preocupações e trazendo boa sorte e saúde.</color>",
  ui_story_5075_50751501_226_dialog_content = "Esse toque... Deve sinalizar o início do Festival da Primavera e um novo ano.",
  ui_story_5075_50751501_227_dialog_content = "PlayerName.",
  ui_story_5075_50751501_228_dialog_content = "PlayerName.",
  ui_story_5075_50751501_229_dialog_content = "PlayerName.",
  ui_story_5075_50751501_230_dialog_content = "PlayerName.",
  ui_story_5075_50751501_231_dialog_content = "Amigo jovem.",
  ui_story_5075_50751501_232_dialog_content = "PlayerName.",
  ui_story_5075_50751501_233_dialog_content = "PlayerName.",
  ui_story_5075_50751501_234_dialog_content = "PlayerName.",
  ui_story_5075_50751501_235_dialog_content = "<size=45>Feliz Ano Novo!</size>"
}
return config
